// Endpoints are compile-time deployment inputs for packaged/native clients. The loopback
// defaults keep local development usable; production and device builds must provide the
// explicit HTTPS origins through `ERPX_CONSOLE_GRPC_ENDPOINT` and
// `ERPX_CONSOLE_AUTH_HTTP_ORIGIN` rather than silently targeting a developer workstation.
const GRPC_ENDPOINT: &str = match option_env!("ERPX_CONSOLE_GRPC_ENDPOINT") {
    Some(value) => value,
    None => "http://127.0.0.1:50051",
};
const AUTH_HTTP_ORIGIN: &str = match option_env!("ERPX_CONSOLE_AUTH_HTTP_ORIGIN") {
    Some(value) => value,
    None => "http://127.0.0.1:50052",
};
const CUSTOMER_ACCESS_AUDIT_PAGE_SIZE: u32 = 25;
const MAX_AUTH_RESPONSE_BYTES: usize = 64 * 1024;
const AUTH_HTTP_SCRIPT: &str = r#"
const url = await dioxus.recv();
const body = await dioxus.recv();
const accessToken = await dioxus.recv();
try {
    const headers = {"content-type": "application/json", "cache-control": "no-store"};
    if (accessToken) headers["x-erpx-access-token"] = accessToken;
    const response = await fetch(url, {
        method: "POST",
        headers,
        body,
        cache: "no-store",
        credentials: "omit"
    });
    const text = await response.text();
    if (new TextEncoder().encode(text).byteLength > 65536) return [response.status, ""];
    return [response.status, text];
} catch (_) {
    return [0, ""];
}
"#;

#[derive(Clone)]
struct AuthHttpResponse {
    status: u16,
    body: String,
}

impl std::fmt::Debug for AuthHttpResponse {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("AuthHttpResponse")
            .field("status", &self.status)
            .field("body_len", &self.body.len())
            .finish()
    }
}

#[derive(Debug, Clone, Copy, Default)]
struct HttpSessionTransport;

impl SessionTransport for HttpSessionTransport {
    fn login(&self, request: LoginRequest) -> SessionFuture<'_, IssuedSession> {
        Box::pin(async move {
            let body = format!(
                "{{\"principal_ref\":{},\"password\":{},\"device_label\":{}}}",
                json_string(&request.principal_ref),
                json_string(request.password.as_str()),
                json_string(&request.device_label),
            );
            decode_issued_session(post_auth_json("/auth/login", body, None).await?)
        })
    }

    fn refresh(
        &self,
        session_id: &SessionId,
        refresh_token: &RefreshToken,
    ) -> SessionFuture<'_, IssuedSession> {
        let body = format!(
            "{{\"session_id\":{},\"refresh_token\":{}}}",
            json_string(session_id.as_str()),
            json_string(refresh_token.as_str()),
        );
        Box::pin(async move {
            decode_issued_session(post_auth_json("/auth/refresh", body, None).await?)
        })
    }

    fn revoke(&self, session_id: &SessionId, access_token: &AccessToken) -> SessionFuture<'_, ()> {
        let body = format!("{{\"session_id\":{}}}", json_string(session_id.as_str()));
        let access_token = access_token.as_str().to_owned();
        Box::pin(async move {
            let response = post_auth_json("/auth/revoke", body, Some(access_token)).await?;
            if response.status != 200 {
                return Err(auth_http_status(response.status));
            }
            if json_bool(&response.body, "revoked") == Some(true) {
                Ok(())
            } else {
                Err(AuthTransportError::Server {
                    code: "invalid_revoke_response".into(),
                })
            }
        })
    }
}

async fn post_auth_json(
    path: &'static str,
    body: String,
    access_token: Option<String>,
) -> Result<AuthHttpResponse, AuthTransportError> {
    let eval = document::eval(AUTH_HTTP_SCRIPT);
    for value in [
        format!("{AUTH_HTTP_ORIGIN}{path}"),
        body,
        access_token.unwrap_or_default(),
    ] {
        eval.send(value).map_err(|_| AuthTransportError::Offline)?;
    }
    let (status, body): (u16, String) =
        eval.join().await.map_err(|_| AuthTransportError::Offline)?;
    Ok(AuthHttpResponse { status, body })
}

fn auth_http_status(status: u16) -> AuthTransportError {
    match status {
        0 | 408 => AuthTransportError::Offline,
        400 | 405 => AuthTransportError::InvalidRequest,
        401 | 403 => AuthTransportError::Unauthorized,
        status => AuthTransportError::Server {
            code: format!("http_{status}"),
        },
    }
}

fn decode_issued_session(response: AuthHttpResponse) -> Result<IssuedSession, AuthTransportError> {
    if response.status != 200 {
        return Err(auth_http_status(response.status));
    }
    let fields = json_string_fields(
        &response.body,
        [
            "session_id",
            "access_token",
            "refresh_token",
            "access_expires_at",
            "refresh_expires_at",
        ],
    )?;
    let [
        session_id,
        access_token,
        refresh_token,
        access_expires_at,
        refresh_expires_at,
    ] = fields.try_into().map_err(|_| invalid_session_response())?;
    IssuedSession::new(
        session_id,
        access_token,
        refresh_token,
        access_expires_at,
        refresh_expires_at,
    )
    .map_err(|_| AuthTransportError::Server {
        code: "invalid_session_response".into(),
    })
}

fn json_string(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len() + 2);
    escaped.push('"');
    for character in value.chars() {
        match character {
            '"' => escaped.push_str("\\\""),
            '\\' => escaped.push_str("\\\\"),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            character if character.is_control() => {
                escaped.push_str(&format!("\\u{:04x}", character as u32));
            }
            character => escaped.push(character),
        }
    }
    escaped.push('"');
    escaped
}

fn json_string_fields<const N: usize>(
    body: &str,
    keys: [&str; N],
) -> Result<Vec<String>, AuthTransportError> {
    if body.len() > MAX_AUTH_RESPONSE_BYTES || has_duplicate_top_level_keys(body) {
        return Err(invalid_session_response());
    }
    let value: serde_json::Value =
        serde_json::from_str(body).map_err(|_| invalid_session_response())?;
    let object = value.as_object().ok_or_else(invalid_session_response)?;
    keys.into_iter()
        .map(|key| {
            object
                .get(key)
                .and_then(serde_json::Value::as_str)
                .map(str::to_owned)
                .ok_or_else(invalid_session_response)
        })
        .collect()
}

fn json_bool(body: &str, key: &str) -> Option<bool> {
    if body.len() > MAX_AUTH_RESPONSE_BYTES || has_duplicate_top_level_keys(body) {
        return None;
    }
    let value: serde_json::Value = serde_json::from_str(body).ok()?;
    value.as_object()?.get(key)?.as_bool()
}

/// `serde_json::Value` intentionally uses last-write-wins maps. Authentication responses are a
/// security boundary, so reject duplicate root fields before decoding instead of accepting an
/// ambiguous response whose meaning depends on which parser handled it first.
fn has_duplicate_top_level_keys(body: &str) -> bool {
    let bytes = body.as_bytes();
    let mut depth = 0usize;
    let mut in_string = false;
    let mut escaped = false;
    let mut expecting_key = false;
    let mut key_start = 0usize;
    let mut key_is_top_level = false;
    let mut keys = std::collections::BTreeSet::new();

    for (index, byte) in bytes.iter().copied().enumerate() {
        if in_string {
            if escaped {
                escaped = false;
            } else if byte == b'\\' {
                escaped = true;
            } else if byte == b'"' {
                in_string = false;
                if key_is_top_level {
                    let raw = &body[key_start..=index];
                    let Ok(key) = serde_json::from_str::<String>(raw) else {
                        return true;
                    };
                    if !keys.insert(key) {
                        return true;
                    }
                    key_is_top_level = false;
                    expecting_key = false;
                }
            }
            continue;
        }

        match byte {
            b'"' => {
                in_string = true;
                key_start = index;
                key_is_top_level = depth == 1 && expecting_key;
            }
            b'{' => {
                depth = depth.saturating_add(1);
                if depth == 1 {
                    expecting_key = true;
                }
            }
            b'}' => {
                depth = depth.saturating_sub(1);
                if depth == 0 {
                    expecting_key = false;
                }
            }
            b',' if depth == 1 => expecting_key = true,
            _ => {}
        }
    }
    false
}

fn invalid_session_response() -> AuthTransportError {
    AuthTransportError::Server {
        code: "invalid_session_response".into(),
    }
}

fn platform_query_context(principal_ref: &str, session_id: &str) -> QueryContext {
    let correlation_id = Uuid::new_v4().to_string();
    QueryContext {
        contract_version: u32::from(CONTRACT_VERSION),
        request_id: Uuid::new_v4().to_string(),
        correlation_id: correlation_id.clone(),
        actor: Some(ActorAttribution {
            principal_ref: principal_ref.to_owned(),
            kind: ActorKind::PlatformUser as i32,
            session_id: session_id.to_owned(),
            represented_principal_ref: String::new(),
            support_capability_id: String::new(),
        }),
        tenant_scope: Some(TenantScope {
            scope: Some(tenant_scope::Scope::Platform(PlatformScope {})),
        }),
        consistency: Some(QueryConsistency {
            requirement: Some(query_consistency::Requirement::Eventual(
                EventualConsistency {},
            )),
        }),
        audit: Some(AuditContext {
            purpose: "platform_customer_console".into(),
            customer_visible: true,
            module: "platform".into(),
            correlation_id,
        }),
    }
}

fn platform_support_query_context(principal_ref: &str, session_id: &str) -> QueryContext {
    let mut context = platform_query_context(principal_ref, session_id);
    if let Some(audit) = context.audit.as_mut() {
        audit.purpose = "platform_incident_console_read".into();
        audit.customer_visible = false;
        audit.module = "support".into();
    }
    context
}

