#[cfg(target_arch = "wasm32")]
async fn execute_entitlement_command(
    scope: EntitlementScope,
    input: EntitlementCommandInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<EntitlementCommandReceiptModel, String> {
    let channel = tonic_web_wasm_client::Client::new(GRPC_ENDPOINT.to_string());
    let mut client = EntitlementServiceClient::new(channel);
    match input {
        EntitlementCommandInput::Allocate {
            seats,
            branch_limit,
            expected_version,
            mfa_code,
        } => {
            let seats = seats
                .trim()
                .parse::<u32>()
                .map_err(|_| "seats must be a positive integer".to_string())?;
            let branch_limit = branch_limit
                .trim()
                .parse::<u32>()
                .map_err(|_| "branch limit must be a positive integer".to_string())?;
            if seats == 0 || branch_limit == 0 {
                return Err("seats and branch limit must be positive".into());
            }
            let mut request = tonic::Request::new(AllocateCompanyEntitlementRequest {
                customer_id: scope.customer_id.clone(),
                module_key: scope.module_key.clone(),
                company_id: scope.company_id.clone(),
                seats,
                branch_limit,
                context: Some(entitlement_command_request_context(
                    &scope,
                    &principal_ref,
                    &session_id,
                    "commercial_entitlement_allocate",
                    &expected_version,
                )?),
                mfa_code,
            });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .allocate_company_entitlement(request)
                .await
                .map_err(entitlement_rpc_error)?
                .into_inner();
            entitlement_command_receipt(response.receipt, response.correlation_id)
        }
        EntitlementCommandInput::ActivateCompany {
            activated_at,
            expected_version,
            mfa_code,
        } => {
            let mut request = tonic::Request::new(ActivateCompanyEntitlementRequest {
                customer_id: scope.customer_id.clone(),
                module_key: scope.module_key.clone(),
                company_id: scope.company_id.clone(),
                activated_at,
                context: Some(entitlement_command_request_context(
                    &scope,
                    &principal_ref,
                    &session_id,
                    "commercial_entitlement_activate_company",
                    &expected_version,
                )?),
                mfa_code,
            });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .activate_company_entitlement(request)
                .await
                .map_err(entitlement_rpc_error)?
                .into_inner();
            entitlement_command_receipt(response.receipt, response.correlation_id)
        }
        EntitlementCommandInput::ActivateBranch {
            activated_at,
            expected_version,
            mfa_code,
        } => {
            if scope.branch_id.trim().is_empty() {
                return Err("enter a branch UUID before activating a branch entitlement".into());
            }
            let mut request = tonic::Request::new(ActivateBranchEntitlementRequest {
                customer_id: scope.customer_id.clone(),
                module_key: scope.module_key.clone(),
                company_id: scope.company_id.clone(),
                branch_id: scope.branch_id.clone(),
                activated_at,
                context: Some(entitlement_command_request_context(
                    &scope,
                    &principal_ref,
                    &session_id,
                    "commercial_entitlement_activate_branch",
                    &expected_version,
                )?),
                mfa_code,
            });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .activate_branch_entitlement(request)
                .await
                .map_err(entitlement_rpc_error)?
                .into_inner();
            entitlement_command_receipt(response.receipt, response.correlation_id)
        }
    }
}

