impl OperationsReadModel {
    fn from_wire(
        scope: &OperationsScope,
        summary: erpx_proto::platform::GetOperationsSummaryResponse,
        exceptions: erpx_proto::platform::ListOperationsExceptionsResponse,
        policies: ListOperationsWorkQueuePoliciesResponse,
    ) -> Result<Self, String> {
        let summary_correlation_id = bounded_operations_value(
            &summary.correlation_id,
            "summary correlation ID",
            false,
            128,
        )?;
        let summary = summary
            .summary
            .ok_or_else(|| "Operations summary response was empty".to_string())?;
        if summary.tenant_id != scope.tenant_id || summary.holding_id != scope.holding_id {
            return Err("Operations summary scope did not match the requested scope".to_string());
        }
        if summary.projection_name != "operations_read_model" {
            return Err("Operations response used an unrecognized read projection".to_string());
        }
        let source_counts = summary
            .source_counts
            .into_iter()
            .take(100)
            .map(|source| {
                Ok(OperationsSourceCountRecord {
                    source_domain: bounded_operations_value(
                        &source.source_domain,
                        "source domain",
                        false,
                        128,
                    )?,
                    reference_count: source.reference_count,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        let summary = OperationsSummaryRecord {
            tenant_id: scope.tenant_id.clone(),
            holding_id: scope.holding_id.clone(),
            projection_name: summary.projection_name,
            read_row_count: summary.read_row_count,
            exception_count: summary.exception_count,
            projection_checkpoint_count: summary.projection_checkpoint_count,
            event_count: summary.event_count,
            source_reference_count: summary.source_reference_count,
            source_counts,
            latest_event_at: bounded_operations_value(
                &summary.latest_event_at,
                "latest event timestamp",
                true,
                64,
            )?,
        };
        let erpx_proto::platform::ListOperationsExceptionsResponse {
            exceptions: exception_rows,
            has_more,
            next_cursor: raw_next_cursor,
            correlation_id: raw_exception_correlation_id,
        } = exceptions;
        if exception_rows.len() > 100 {
            return Err("Operations exception page exceeded its display bound".to_string());
        }
        let exception_correlation_id = bounded_operations_value(
            &raw_exception_correlation_id,
            "exception correlation ID",
            false,
            128,
        )?;
        let exceptions = exception_rows
            .into_iter()
            .map(|exception| {
                Ok(OperationsExceptionRecord {
                    exception_id: bounded_operations_value(
                        &exception.exception_id,
                        "exception ID",
                        false,
                        128,
                    )?,
                    category: bounded_operations_value(
                        &exception.category,
                        "exception category",
                        false,
                        128,
                    )?,
                    severity: bounded_operations_value(
                        &exception.severity,
                        "exception severity",
                        false,
                        64,
                    )?,
                    status: bounded_operations_value(
                        &exception.status,
                        "exception status",
                        false,
                        64,
                    )?,
                    assigned_to: bounded_operations_value(
                        &exception.assigned_to,
                        "exception assignee",
                        true,
                        128,
                    )?,
                    manager_ref: bounded_operations_value(
                        &exception.manager_ref,
                        "exception manager",
                        true,
                        128,
                    )?,
                    due_at: bounded_operations_value(
                        &exception.due_at,
                        "exception due timestamp",
                        true,
                        64,
                    )?,
                    aggregate_version: exception.aggregate_version,
                    updated_at: bounded_operations_value(
                        &exception.updated_at,
                        "exception updated timestamp",
                        false,
                        64,
                    )?,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        let next_cursor =
            bounded_operations_value(&raw_next_cursor, "Operations pagination cursor", true, 512)?;
        if !has_more && !next_cursor.is_empty() {
            return Err("Operations response returned a cursor without another page".to_string());
        }
        let ListOperationsWorkQueuePoliciesResponse {
            policies: policy_rows,
            has_more: policies_has_more,
            next_cursor: policies_next_cursor,
            correlation_id: policies_correlation_id,
        } = policies;
        if policy_rows.len() > 100 {
            return Err("Operations policy page exceeded its display bound".to_string());
        }
        let _policies_correlation_id = bounded_operations_value(
            &policies_correlation_id,
            "policy correlation ID",
            false,
            128,
        )?;
        let policies = policy_rows
            .into_iter()
            .map(|policy| {
                Ok(OperationsPolicyRecord {
                    policy_id: bounded_operations_value(
                        &policy.policy_id,
                        "policy ID",
                        false,
                        128,
                    )?,
                    name: bounded_operations_value(&policy.name, "policy name", false, 255)?,
                    allowed_domains: policy
                        .allowed_domains
                        .into_iter()
                        .take(16)
                        .map(|domain| {
                            bounded_operations_value(&domain, "policy domain", false, 128)
                        })
                        .collect::<Result<Vec<_>, _>>()?,
                    escalation_after_minutes: policy.escalation_after_minutes,
                    status: bounded_operations_value(&policy.status, "policy status", false, 64)?,
                    aggregate_version: policy.aggregate_version,
                    updated_at: bounded_operations_value(
                        &policy.updated_at,
                        "policy updated timestamp",
                        false,
                        64,
                    )?,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        if !policies_has_more && !policies_next_cursor.is_empty() {
            return Err(
                "Operations policy response returned a cursor without another page".to_string(),
            );
        }
        Ok(Self {
            summary,
            exceptions,
            policies,
            has_more,
            next_cursor,
            summary_correlation_id,
            exception_correlation_id,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct FinanceScope {
    tenant_id: String,
    holding_ref: String,
    holding_id: String,
}

impl FinanceScope {
    fn new(tenant_id: &str, holding_ref: &str, holding_id: &str) -> Result<Self, &'static str> {
        let tenant = OperationsScope::new(tenant_id, holding_id)
            .map_err(|_| "Enter a valid opaque tenant reference and holding UUID.")?;
        let holding_ref = holding_ref.trim();
        if holding_ref.is_empty()
            || holding_ref.len() > 128
            || !holding_ref
                .chars()
                .all(|character| character.is_ascii_alphanumeric() || "_-".contains(character))
        {
            return Err("Enter a valid opaque Finance holding reference.");
        }
        Ok(Self {
            tenant_id: tenant.tenant_id,
            holding_ref: holding_ref.to_owned(),
            holding_id: tenant.holding_id,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct EntitlementScope {
    customer_id: String,
    subscription_id: String,
    holding_id: String,
    module_key: String,
    company_id: String,
    branch_id: String,
}

impl EntitlementScope {
    fn new(
        customer_id: &str,
        subscription_id: &str,
        holding_id: &str,
        module_key: &str,
        company_id: &str,
        branch_id: &str,
    ) -> Result<Self, &'static str> {
        for (value, label) in [
            (customer_id, "customer UUID"),
            (subscription_id, "subscription UUID"),
            (holding_id, "holding UUID"),
            (company_id, "company UUID"),
        ] {
            Uuid::parse_str(value.trim()).map_err(|_| match label {
                "customer UUID" => "Enter a valid customer UUID.",
                "subscription UUID" => "Enter a valid subscription UUID.",
                "holding UUID" => "Enter a valid holding UUID.",
                _ => "Enter a valid company UUID.",
            })?;
        }
        let branch_id = branch_id.trim();
        if !branch_id.is_empty() {
            Uuid::parse_str(branch_id).map_err(|_| "Enter a valid branch UUID.")?;
        }
        let module_key = module_key.trim();
        if module_key.is_empty()
            || module_key.len() > 128
            || !module_key
                .chars()
                .all(|character| character.is_ascii_alphanumeric() || "._-".contains(character))
        {
            return Err("Enter a valid module key.");
        }
        Ok(Self {
            customer_id: customer_id.trim().to_owned(),
            subscription_id: subscription_id.trim().to_owned(),
            holding_id: holding_id.trim().to_owned(),
            module_key: module_key.to_owned(),
            company_id: company_id.trim().to_owned(),
            branch_id: branch_id.to_owned(),
        })
    }

    fn target_scope(&self) -> Result<TenantScope, String> {
        let holding_id = Uuid::parse_str(&self.holding_id)
            .map_err(|_| "the entitlement holding scope must be a UUID".to_string())?;
        let company_id = Uuid::parse_str(&self.company_id)
            .map_err(|_| "the entitlement company scope must be a UUID".to_string())?;
        let scope = if self.branch_id.trim().is_empty() {
            tenant_scope::Scope::Company(CompanyScope {
                holding_id: holding_id.to_string(),
                company_id: company_id.to_string(),
            })
        } else {
            let branch_id = Uuid::parse_str(&self.branch_id)
                .map_err(|_| "the entitlement branch scope must be a UUID".to_string())?;
            tenant_scope::Scope::Branch(BranchScope {
                holding_id: holding_id.to_string(),
                company_id: company_id.to_string(),
                branch_id: branch_id.to_string(),
            })
        };
        Ok(TenantScope { scope: Some(scope) })
    }
}

