#[derive(Debug, Clone, PartialEq, Eq)]
struct QualityInspectionRowModel {
    inspection_id: String,
    holding_id: String,
    company_id: String,
    branch_id: String,
    reference: String,
    kind: String,
    status: String,
    quantity: u64,
    source_version: u64,
    projected_at: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct QualityReadModel {
    scope: QualityScope,
    rows: Vec<QualityInspectionRowModel>,
    has_more: bool,
    next_cursor: Option<String>,
    correlation_id: String,
}

impl QualityReadModel {
    fn from_wire(
        scope: &QualityScope,
        response: ListQualityInspectionsResponse,
    ) -> Result<Self, String> {
        if response.rows.len() > 100 {
            return Err("Quality read response exceeded its display bound".into());
        }
        let correlation_id = bounded_finance_value(
            &response.correlation_id,
            "Quality correlation ID",
            false,
            128,
        )?;
        if response.has_more && response.next_cursor.is_empty() {
            return Err("Quality read response omitted its next cursor".into());
        }
        if !response.has_more && !response.next_cursor.is_empty() {
            return Err("Quality read response returned a cursor without another page".into());
        }
        let rows = response
            .rows
            .into_iter()
            .map(|row| {
                if row.holding_id != scope.finance.holding_id
                    || row.company_id != scope.company_id
                    || row.branch_id != scope.branch_id
                    || Uuid::parse_str(&row.inspection_id).is_err()
                    || Uuid::parse_str(&row.holding_id).is_err()
                    || Uuid::parse_str(&row.company_id).is_err()
                    || (!row.branch_id.is_empty() && Uuid::parse_str(&row.branch_id).is_err())
                    || row.source_version == 0
                    || row.quantity == 0
                {
                    return Err("Quality read row identity or version was invalid".into());
                }
                if row.inspection_json.len() > 1024 * 1024
                    || !serde_json::from_slice::<serde_json::Value>(&row.inspection_json)
                        .map(|value| value.is_object())
                        .unwrap_or(false)
                {
                    return Err("Quality read row payload was invalid".into());
                }
                let reference =
                    bounded_finance_value(&row.reference, "Quality reference", false, 128)?;
                let kind = bounded_finance_value(&row.kind, "Quality kind", false, 32)?;
                let status = bounded_finance_value(&row.status, "Quality status", false, 32)?;
                let projected_at =
                    bounded_finance_value(&row.projected_at, "Quality projected_at", false, 64)?;
                Ok(QualityInspectionRowModel {
                    inspection_id: row.inspection_id,
                    holding_id: row.holding_id,
                    company_id: row.company_id,
                    branch_id: row.branch_id,
                    reference,
                    kind,
                    status,
                    quantity: row.quantity,
                    source_version: row.source_version,
                    projected_at,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        Ok(Self {
            scope: scope.clone(),
            rows,
            has_more: response.has_more,
            next_cursor: (!response.next_cursor.is_empty()).then_some(response.next_cursor),
            correlation_id,
        })
    }
}

