fn finance_command_context(
    principal_ref: &str,
    session_id: &str,
    holding_id: &str,
    purpose: &str,
    idempotency_key: &str,
    expected_version: Option<u64>,
) -> Result<(CommandContext, DomainCommandContext), String> {
    let holding_id = Uuid::parse_str(holding_id)
        .map_err(|_| "the Finance holding scope must be a UUID".to_string())?;
    let session_id = Uuid::parse_str(session_id)
        .map_err(|_| "the authenticated Finance session must be a UUID".to_string())?;
    let command_id = Uuid::new_v4();
    let correlation_id = Uuid::new_v4();
    let proto_context = CommandContext {
        contract_version: u32::from(CONTRACT_VERSION),
        command_id: command_id.to_string(),
        idempotency_key: idempotency_key.to_owned(),
        correlation_id: correlation_id.to_string(),
        causation_id: String::new(),
        actor: Some(ActorAttribution {
            principal_ref: principal_ref.to_owned(),
            kind: ActorKind::PlatformUser as i32,
            session_id: session_id.to_string(),
            represented_principal_ref: String::new(),
            support_capability_id: String::new(),
        }),
        tenant_scope: Some(TenantScope {
            scope: Some(tenant_scope::Scope::Holding(HoldingScope {
                holding_id: holding_id.to_string(),
            })),
        }),
        audit: Some(AuditContext {
            purpose: purpose.to_owned(),
            customer_visible: false,
            module: "finance".into(),
            correlation_id: correlation_id.to_string(),
        }),
        expected_aggregate_version: expected_version.unwrap_or_default(),
        subscription_id: String::new(),
        mfa_code: String::new(),
    };
    let domain_context = DomainCommandContext {
        contract_version: CONTRACT_VERSION,
        command_id,
        idempotency_key: idempotency_key.to_owned(),
        correlation_id,
        causation_id: None,
        actor: DomainActorAttribution {
            principal_ref: principal_ref.to_owned(),
            kind: DomainActorKind::PlatformUser,
            session_id: Some(session_id),
            represented_principal_ref: None,
            support_capability_id: None,
        },
        tenant_scope: DomainTenantScope::Holding { holding_id },
        audit: DomainAuditContext {
            purpose: purpose.to_owned(),
            customer_visible: false,
            module: Some("finance".into()),
            correlation_id,
        },
        expected_aggregate_version: expected_version,
        subscription_id: None,
    };
    Ok((proto_context, domain_context))
}

fn finance_command_text(value: &str, field: &str, max_len: usize) -> Result<String, String> {
    let value = value.trim();
    if value.is_empty() || value.len() > max_len || value.chars().any(char::is_control) {
        return Err(format!(
            "{field} is required and must be at most {max_len} bytes"
        ));
    }
    Ok(value.to_owned())
}

fn finance_json_text(value: &str, field: &str, max_len: usize) -> Result<String, String> {
    let value = value.trim();
    if value.is_empty()
        || value.len() > max_len
        || value
            .chars()
            .any(|character| character.is_control() && !matches!(character, '\n' | '\r' | '\t'))
    {
        return Err(format!(
            "{field} is required and must be at most {max_len} bytes"
        ));
    }
    Ok(value.to_owned())
}

fn finance_command_uuid(value: &str, field: &str) -> Result<String, String> {
    let value = finance_command_text(value, field, 64)?;
    Uuid::parse_str(&value).map_err(|_| format!("{field} must be a UUID"))?;
    Ok(value)
}

fn finance_command_date(value: &str, field: &str) -> Result<String, String> {
    let value = finance_command_text(value, field, 10)?;
    if value.len() != 10
        || value.as_bytes().get(4) != Some(&b'-')
        || value.as_bytes().get(7) != Some(&b'-')
        || !value
            .chars()
            .enumerate()
            .all(|(index, character)| index == 4 || index == 7 || character.is_ascii_digit())
    {
        return Err(format!("{field} must be YYYY-MM-DD"));
    }
    Ok(value)
}

fn finance_period_json(
    scope: &FinanceScope,
    input: &FinancePeriodCommandInput,
) -> Result<(Vec<u8>, Option<u64>), String> {
    let period_id = finance_command_uuid(&input.period_id, "period ID")?;
    let company_id = finance_command_uuid(&input.company_id, "company ID")?;
    let label = finance_command_text(&input.label, "period label", 255)?;
    let starts_on = finance_command_date(&input.starts_on, "period start")?;
    let ends_on = finance_command_date(&input.ends_on, "period end")?;
    let expected_version = if input.expected_version.trim().is_empty() {
        None
    } else {
        let value = input
            .expected_version
            .trim()
            .parse::<u64>()
            .map_err(|_| "expected version must be a positive integer".to_string())?;
        if value == 0 {
            return Err("expected version must be a positive integer".into());
        }
        Some(value)
    };
    let period_json = serde_json::to_vec(&serde_json::json!({
        "id": period_id,
        "holding_id": scope.holding_id,
        "company_id": company_id,
        "label": label,
        "starts_on": starts_on,
        "ends_on": ends_on,
        "status": "open",
        "last_transition": null,
    }))
    .map_err(|_| "Finance period payload could not be encoded".to_string())?;
    Ok((period_json, expected_version))
}

