fn bounded_finance_uuid(value: &str, label: &str) -> Result<String, &'static str> {
    let value = value.trim();
    if Uuid::parse_str(value).is_err() {
        return Err(match label {
            "period" => "Enter a valid Finance period UUID.",
            "company" => "Enter a valid Finance company UUID.",
            _ => "Enter a valid Finance UUID.",
        });
    }
    Ok(value.to_owned())
}

