#[derive(Debug, Clone, PartialEq, Eq)]
struct AssetMaintenanceListRowModel {
    aggregate_type: String,
    aggregate_id: String,
    reference: String,
    source_version: u64,
    projected_at: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct AssetMaintenanceListReadModel {
    scope: AssetMaintenanceListScope,
    rows: Vec<AssetMaintenanceListRowModel>,
    has_more: bool,
    next_cursor: Option<String>,
    correlation_id: String,
}

impl AssetMaintenanceListReadModel {
    fn from_wire(
        scope: &AssetMaintenanceListScope,
        response: ListAssetMaintenanceAggregatesResponse,
    ) -> Result<Self, String> {
        if response.rows.len() > 100 {
            return Err("Asset/Maintenance read response exceeded its display bound".into());
        }
        let correlation_id = bounded_finance_value(
            &response.correlation_id,
            "Asset/Maintenance correlation ID",
            false,
            128,
        )?;
        if response.has_more && response.next_cursor.is_empty() {
            return Err("Asset/Maintenance read response omitted its next cursor".into());
        }
        if !response.has_more && !response.next_cursor.is_empty() {
            return Err(
                "Asset/Maintenance read response returned a cursor without another page".into(),
            );
        }
        let rows = response
            .rows
            .into_iter()
            .map(|row: AssetMaintenanceAggregateReadRow| {
                let aggregate_type = bounded_finance_value(
                    &row.aggregate_type,
                    "Asset/Maintenance aggregate type",
                    false,
                    64,
                )?;
                if !matches!(aggregate_type.as_str(), "asset" | "maintenance_work_order") {
                    return Err("Asset/Maintenance aggregate type was invalid".into());
                }
                let aggregate_id = bounded_finance_uuid(
                    &row.aggregate_id,
                    "Asset/Maintenance aggregate",
                )
                .map_err(|_| "Asset/Maintenance aggregate identity was invalid".to_string())?;
                if row.holding_id != scope.finance.holding_id
                    || row.company_id != scope.company_id
                    || row.branch_id != scope.branch_id
                    || row.source_version == 0
                    || Uuid::parse_str(&row.holding_id).is_err()
                    || Uuid::parse_str(&row.company_id).is_err()
                    || (!row.branch_id.is_empty() && Uuid::parse_str(&row.branch_id).is_err())
                    || row.aggregate_json.len() > 1024 * 1024
                    || !serde_json::from_slice::<serde_json::Value>(&row.aggregate_json)
                        .map(|value| value.is_object())
                        .unwrap_or(false)
                {
                    return Err(
                        "Asset/Maintenance read row identity, scope, version, or payload was invalid"
                            .into(),
                    );
                }
                Ok(AssetMaintenanceListRowModel {
                    aggregate_type,
                    aggregate_id,
                    reference: bounded_finance_value(
                        &row.reference,
                        "Asset/Maintenance reference",
                        false,
                        255,
                    )?,
                    source_version: row.source_version,
                    projected_at: bounded_finance_value(
                        &row.projected_at,
                        "Asset/Maintenance projected_at",
                        false,
                        64,
                    )?,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        Ok(Self {
            scope: scope.clone(),
            rows,
            has_more: response.has_more,
            next_cursor: (!response.next_cursor.is_empty()).then_some(response.next_cursor),
            correlation_id,
        })
    }
}

