#[derive(Debug, Clone, PartialEq, Eq)]
struct ProductAggregateReadModel {
    scope: ProductAggregateScope,
    present: bool,
    source_version: u64,
    correlation_id: String,
}

impl ProductAggregateReadModel {
    fn from_wire(
        scope: &ProductAggregateScope,
        aggregate_type: &str,
        aggregate_id: &str,
        source_version: u64,
        aggregate_json: &[u8],
        present: bool,
        correlation_id: &str,
    ) -> Result<Self, String> {
        let correlation_id =
            bounded_finance_value(correlation_id, "product correlation ID", false, 128)?;
        if aggregate_type != scope.aggregate_type || aggregate_id != scope.aggregate_id {
            return Err(
                "Product response aggregate identity did not match the requested scope".into(),
            );
        }
        if aggregate_json.len() > 1024 * 1024 {
            return Err("Product aggregate payload exceeded its transport bound".into());
        }
        if !present && (!aggregate_json.is_empty() || source_version != 0) {
            return Err("Product missing response carried aggregate material".into());
        }
        Ok(Self {
            scope: scope.clone(),
            present,
            source_version,
            correlation_id,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ScmTransitionResult {
    aggregate_type: String,
    aggregate_id: String,
    version: u64,
    replayed: bool,
    correlation_id: String,
}

impl ScmTransitionResult {
    fn from_wire(
        scope: &ProductAggregateScope,
        response: TransitionScmAggregateResponse,
    ) -> Result<Self, String> {
        let receipt = response
            .receipt
            .ok_or_else(|| "SCM transition response omitted its receipt".to_string())?;
        let correlation_id = bounded_finance_value(
            &response.correlation_id,
            "SCM transition correlation ID",
            false,
            128,
        )?;
        if receipt.aggregate_type != scope.aggregate_type
            || receipt.aggregate_id != scope.aggregate_id
            || receipt.version == 0
        {
            return Err("SCM transition receipt identity was invalid".into());
        }
        Ok(Self {
            aggregate_type: receipt.aggregate_type,
            aggregate_id: receipt.aggregate_id,
            version: receipt.version,
            replayed: receipt.replayed,
            correlation_id,
        })
    }
}

