#[derive(Debug, Clone, PartialEq, Eq)]
struct FinanceThaiTaxReportModel {
    scope: FinanceScope,
    company_id: String,
    tax_period: String,
    currency: String,
    fact_count: u32,
    output_vat_base_minor: i64,
    output_vat_minor: i64,
    input_vat_base_minor: i64,
    input_vat_minor: i64,
    withholding_base_minor: i64,
    withholding_minor: i64,
    facts: Vec<FinanceThaiTaxFactRecord>,
    source_version: u64,
    projected_at: String,
    correlation_id: String,
}

impl FinanceThaiTaxReportModel {
    fn from_wire(
        scope: &FinanceScope,
        company_id: &str,
        tax_period: &str,
        currency: &str,
        response: GetThaiTaxReportResponse,
    ) -> Result<Self, String> {
        if response.holding_id != scope.holding_id
            || response.company_id != company_id
            || response.tax_period != tax_period
            || response.currency != currency
        {
            return Err(
                "Thai tax report scope did not match the requested company or period".into(),
            );
        }
        if response.facts.len() > 1_000 {
            return Err("Thai tax report display bound exceeded".into());
        }
        if response.fact_count != response.facts.len() as u32 {
            return Err("Thai tax report fact count was inconsistent".into());
        }
        let correlation_id = bounded_operations_value(
            &response.correlation_id,
            "Thai tax report correlation ID",
            false,
            128,
        )?;
        let projected_at = bounded_operations_value(
            &response.projected_at,
            "Thai tax report projection timestamp",
            false,
            64,
        )?;
        let facts = response
            .facts
            .into_iter()
            .map(|fact| {
                if Uuid::parse_str(&fact.fact_id).is_err()
                    || Uuid::parse_str(&fact.journal_id).is_err()
                    || Uuid::parse_str(&fact.line_id).is_err()
                    || fact.kind.is_empty()
                {
                    return Err("Thai tax report contained an invalid fact identity".into());
                }
                Ok(FinanceThaiTaxFactRecord {
                    fact_id: fact.fact_id,
                    journal_id: fact.journal_id,
                    line_id: fact.line_id,
                    tax_date: fact.tax_date,
                    kind: fact.kind,
                    base_minor: fact.base_minor,
                    tax_minor: fact.tax_minor,
                    tax_rate_basis_points: fact.tax_rate_basis_points,
                    tax_identifier: fact.tax_identifier,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        Ok(Self {
            scope: scope.clone(),
            company_id: company_id.into(),
            tax_period: tax_period.into(),
            currency: currency.into(),
            fact_count: response.fact_count,
            output_vat_base_minor: response.output_vat_base_minor,
            output_vat_minor: response.output_vat_minor,
            input_vat_base_minor: response.input_vat_base_minor,
            input_vat_minor: response.input_vat_minor,
            withholding_base_minor: response.withholding_base_minor,
            withholding_minor: response.withholding_minor,
            facts,
            source_version: response.source_version,
            projected_at,
            correlation_id,
        })
    }
}

