#[derive(Debug, Clone, PartialEq, Eq)]
struct FinanceConsolidatedTrialBalanceModel {
    scope: FinanceScope,
    currency: String,
    company_ids: Vec<String>,
    lines: Vec<FinanceConsolidatedTrialBalanceLineRecord>,
    total_debit_minor: i64,
    total_credit_minor: i64,
    source_version: u64,
    correlation_id: String,
}

impl FinanceConsolidatedTrialBalanceModel {
    fn from_wire(
        scope: &FinanceScope,
        response: GetFinanceConsolidatedTrialBalanceResponse,
    ) -> Result<Self, String> {
        if response.holding_id != scope.holding_id || !response.read_only {
            return Err("Finance consolidation response scope or mutability was invalid".into());
        }
        if response.company_ids.is_empty() || response.company_ids.len() > 1_000 {
            return Err("Finance consolidation company bound was invalid".into());
        }
        if response.lines.len() > 10_000 {
            return Err("Finance consolidation line bound was exceeded".into());
        }
        let company_ids = response
            .company_ids
            .into_iter()
            .map(|company_id| {
                Uuid::parse_str(&company_id)
                    .map(|_| company_id)
                    .map_err(|_| "Finance consolidation company identity was invalid".to_string())
            })
            .collect::<Result<Vec<_>, _>>()?;
        let currency = bounded_finance_value(
            &response.currency,
            "Finance consolidation currency",
            false,
            3,
        )?;
        let correlation_id = bounded_operations_value(
            &response.correlation_id,
            "Finance consolidation correlation ID",
            false,
            128,
        )?;
        let lines = response
            .lines
            .into_iter()
            .map(|line| {
                if line.account_code.trim().is_empty()
                    || line.account_code.len() > 64
                    || line.account_name.trim().is_empty()
                    || line.account_kind.trim().is_empty()
                {
                    return Err("Finance consolidation line identity was invalid".into());
                }
                Ok(FinanceConsolidatedTrialBalanceLineRecord {
                    account_code: line.account_code,
                    account_name: line.account_name,
                    account_kind: line.account_kind,
                    debit_minor: line.debit_minor,
                    credit_minor: line.credit_minor,
                    net_minor: line.net_minor,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        Ok(Self {
            scope: scope.clone(),
            currency,
            company_ids,
            lines,
            total_debit_minor: response.total_debit_minor,
            total_credit_minor: response.total_credit_minor,
            source_version: response.source_version,
            correlation_id,
        })
    }
}

