#[derive(Debug, Clone, PartialEq, Eq)]
struct FinanceChartRecord {
    chart_id: String,
    holding_id: String,
    company_id: String,
    name: String,
    source_version: u64,
    projected_at: String,
    accounts: Vec<FinanceChartAccountRecord>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct FinanceChartReadModel {
    scope: FinanceChartScope,
    charts: Vec<FinanceChartRecord>,
    has_more: bool,
    next_cursor: String,
    correlation_id: String,
}

impl FinanceChartReadModel {
    fn from_wire(
        scope: &FinanceChartScope,
        response: ListFinanceChartsResponse,
    ) -> Result<Self, String> {
        if response.charts.len() > 100 {
            return Err("Finance chart page exceeded its display bound".into());
        }
        let correlation_id = bounded_finance_value(
            &response.correlation_id,
            "Finance chart correlation ID",
            false,
            128,
        )?;
        let next_cursor = bounded_finance_value(
            &response.next_after_chart_id,
            "Finance chart pagination cursor",
            true,
            128,
        )?;
        if response.has_more {
            if next_cursor.is_empty() || Uuid::parse_str(&next_cursor).is_err() {
                return Err("Finance chart pagination cursor was invalid".into());
            }
        } else if !next_cursor.is_empty() {
            return Err("Finance chart returned a cursor without another page".into());
        }
        let charts = response
            .charts
            .into_iter()
            .map(|row| {
                let chart = Self::chart_from_wire(row)?;
                if chart.holding_id != scope.finance.holding_id
                    || chart.company_id != scope.company_id
                {
                    return Err("Finance chart row escaped its requested scope".into());
                }
                Ok(chart)
            })
            .collect::<Result<Vec<_>, String>>()?;
        Ok(Self {
            scope: scope.clone(),
            charts,
            has_more: response.has_more,
            next_cursor,
            correlation_id,
        })
    }

    fn chart_from_wire(row: FinanceChartReadRow) -> Result<FinanceChartRecord, String> {
        let chart_id = bounded_finance_uuid(&row.chart_id, "chart")
            .map_err(|_| "Finance chart ID was not a UUID".to_string())?;
        let holding_id = bounded_finance_uuid(&row.holding_id, "holding")
            .map_err(|_| "Finance chart holding ID was not a UUID".to_string())?;
        let company_id = bounded_finance_uuid(&row.company_id, "company")
            .map_err(|_| "Finance chart company ID was not a UUID".to_string())?;
        let name = bounded_finance_value(&row.name, "Finance chart name", false, 256)?;
        let projected_at = bounded_finance_value(
            &row.projected_at,
            "Finance chart projection timestamp",
            false,
            64,
        )?;
        if row.accounts.len() > 4096 {
            return Err("Finance chart account set exceeded its display bound".into());
        }
        let accounts = row
            .accounts
            .into_iter()
            .map(Self::account_from_wire)
            .collect::<Result<Vec<_>, String>>()?;
        Ok(FinanceChartRecord {
            chart_id,
            holding_id,
            company_id,
            name,
            source_version: row.source_version,
            projected_at,
            accounts,
        })
    }

    fn account_from_wire(
        row: FinanceChartAccountReadRow,
    ) -> Result<FinanceChartAccountRecord, String> {
        let account_id = bounded_finance_uuid(&row.account_id, "account")
            .map_err(|_| "Finance chart account ID was not a UUID".to_string())?;
        let code = bounded_finance_value(&row.code, "Finance chart account code", false, 64)?;
        let name = bounded_finance_value(&row.name, "Finance chart account name", false, 256)?;
        let category =
            bounded_finance_value(&row.category, "Finance chart account category", false, 32)?;
        if !matches!(
            category.as_str(),
            "asset" | "liability" | "equity" | "revenue" | "expense"
        ) {
            return Err("Finance chart account category was invalid".into());
        }
        let normal_balance = bounded_finance_value(
            &row.normal_balance,
            "Finance chart normal balance",
            false,
            16,
        )?;
        if !matches!(normal_balance.as_str(), "debit" | "credit") {
            return Err("Finance chart normal balance was invalid".into());
        }
        let parent_account_id = bounded_finance_value(
            &row.parent_account_id,
            "Finance chart parent account ID",
            true,
            128,
        )?;
        if row.has_parent_account_id == parent_account_id.is_empty()
            || (!parent_account_id.is_empty() && Uuid::parse_str(&parent_account_id).is_err())
        {
            return Err("Finance chart parent-account identity was invalid".into());
        }
        let status = bounded_finance_value(&row.status, "Finance chart account status", false, 16)?;
        if !matches!(status.as_str(), "active" | "inactive") {
            return Err("Finance chart account status was invalid".into());
        }
        Ok(FinanceChartAccountRecord {
            account_id,
            code,
            name,
            category,
            normal_balance,
            parent_account_id,
            status,
            source_version: row.source_version,
        })
    }
}

