#[derive(Debug, Clone, PartialEq, Eq)]
struct HrJsonCommandInput {
    aggregate_kind: String,
    payload_json: String,
    expected_version: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct HrJsonCommandReceipt {
    aggregate_type: String,
    aggregate_id: String,
    version: u64,
    replayed: bool,
    correlation_id: String,
}

fn hr_command_context(
    scope: &HrEmployeeScope,
    principal_ref: &str,
    session_id: &str,
    purpose: &str,
    idempotency_key: &str,
    expected_version: Option<u64>,
) -> Result<(CommandContext, DomainCommandContext), String> {
    let (mut proto_context, mut domain_context) = finance_command_context(
        principal_ref,
        session_id,
        &scope.finance.holding_id,
        purpose,
        idempotency_key,
        expected_version,
    )?;
    let holding_id = scope.finance.holding_id.clone();
    let company_id = scope.company_id.clone();
    let branch_id = scope.branch_id.clone();
    let proto_scope = if branch_id.is_empty() {
        tenant_scope::Scope::Company(CompanyScope {
            holding_id: holding_id.clone(),
            company_id: company_id.clone(),
        })
    } else {
        tenant_scope::Scope::Branch(BranchScope {
            holding_id: holding_id.clone(),
            company_id: company_id.clone(),
            branch_id,
        })
    };
    proto_context.tenant_scope = Some(TenantScope {
        scope: Some(proto_scope),
    });
    let holding_id = Uuid::parse_str(&holding_id)
        .map_err(|_| "the HR holding scope must be a UUID".to_string())?;
    let company_id = Uuid::parse_str(&company_id)
        .map_err(|_| "the HR company scope must be a UUID".to_string())?;
    domain_context.tenant_scope = if scope.branch_id.is_empty() {
        DomainTenantScope::Company {
            holding_id,
            company_id,
        }
    } else {
        DomainTenantScope::Branch {
            holding_id,
            company_id,
            branch_id: Uuid::parse_str(&scope.branch_id)
                .map_err(|_| "the HR branch scope must be a UUID".to_string())?,
        }
    };
    Ok((proto_context, domain_context))
}

enum HrJsonCommandRequest {
    Employee(tonic::Request<SaveHrEmployeeRequest>),
    Leave(tonic::Request<SaveHrLeaveRequest>),
    Expense(tonic::Request<SaveHrExpenseRequest>),
    Payroll(tonic::Request<SaveHrPayrollRequest>),
}

fn hr_json_command_request(
    scope: &HrEmployeeScope,
    input: &HrJsonCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<HrJsonCommandRequest, String> {
    let aggregate_kind = finance_command_text(&input.aggregate_kind, "HR aggregate kind", 32)?;
    let expected_version = if input.expected_version.trim().is_empty() {
        None
    } else {
        let value = input
            .expected_version
            .trim()
            .parse::<u64>()
            .map_err(|_| "expected HR version must be a positive integer".to_string())?;
        if value == 0 {
            return Err("expected HR version must be a positive integer".into());
        }
        Some(value)
    };
    let max_bytes = if aggregate_kind == "payroll" {
        512 * 1024
    } else {
        256 * 1024
    };
    let payload = finance_json_text(&input.payload_json, "HR aggregate JSON", max_bytes)?;
    let (context, _) = hr_command_context(
        scope,
        principal_ref,
        session_id,
        &format!("hr_{}_save", aggregate_kind),
        &format!("console-hr-{}-{}", aggregate_kind, Uuid::new_v4()),
        expected_version,
    )?;
    let mut payload_value: serde_json::Value = serde_json::from_str(&payload)
        .map_err(|_| "HR aggregate JSON must be a JSON object".to_string())?;
    let payload_object = payload_value
        .as_object_mut()
        .ok_or_else(|| "HR aggregate JSON must be a JSON object".to_string())?;
    if aggregate_kind == "leave" {
        payload_object.insert(
            "last_command_id".into(),
            serde_json::Value::String(context.command_id.clone()),
        );
    } else if aggregate_kind == "employee" {
        payload_object.insert(
            "last_command_id".into(),
            serde_json::Value::String(context.command_id.clone()),
        );
        payload_object.insert(
            "last_idempotency_key".into(),
            serde_json::Value::String(context.idempotency_key.clone()),
        );
    }
    let payload = serde_json::to_vec(&payload_value)
        .map_err(|_| "HR aggregate payload could not be encoded".to_string())?;
    match aggregate_kind.as_str() {
        "employee" => Ok(HrJsonCommandRequest::Employee(tonic::Request::new(
            SaveHrEmployeeRequest {
                tenant_id: scope.finance.tenant_id.clone(),
                holding_ref: scope.finance.holding_ref.clone(),
                employee_json: payload,
                has_expected_version: expected_version.is_some(),
                expected_version: expected_version.unwrap_or_default(),
                context: Some(context),
            },
        ))),
        "leave" => Ok(HrJsonCommandRequest::Leave(tonic::Request::new(
            SaveHrLeaveRequest {
                tenant_id: scope.finance.tenant_id.clone(),
                holding_ref: scope.finance.holding_ref.clone(),
                leave_json: payload,
                has_expected_version: expected_version.is_some(),
                expected_version: expected_version.unwrap_or_default(),
                context: Some(context),
            },
        ))),
        "expense" => Ok(HrJsonCommandRequest::Expense(tonic::Request::new(
            SaveHrExpenseRequest {
                tenant_id: scope.finance.tenant_id.clone(),
                holding_ref: scope.finance.holding_ref.clone(),
                expense_json: payload,
                has_expected_version: expected_version.is_some(),
                expected_version: expected_version.unwrap_or_default(),
                context: Some(context),
            },
        ))),
        "payroll" => Ok(HrJsonCommandRequest::Payroll(tonic::Request::new(
            SaveHrPayrollRequest {
                tenant_id: scope.finance.tenant_id.clone(),
                holding_ref: scope.finance.holding_ref.clone(),
                payroll_json: payload,
                has_expected_version: expected_version.is_some(),
                expected_version: expected_version.unwrap_or_default(),
                context: Some(context),
            },
        ))),
        _ => Err("HR aggregate kind must be employee, leave, expense, or payroll".into()),
    }
}

fn hr_json_receipt(
    receipt: Option<erpx_proto::platform::HrWriteReceipt>,
    correlation_id: &str,
) -> Result<HrJsonCommandReceipt, String> {
    let correlation_id =
        bounded_finance_value(correlation_id, "HR command correlation ID", false, 128)?;
    let receipt = receipt.ok_or_else(|| "HR command omitted its receipt".to_string())?;
    let aggregate_type = finance_command_text(&receipt.aggregate_type, "HR aggregate type", 64)?;
    let aggregate_id = finance_command_uuid(&receipt.aggregate_id, "HR aggregate ID")?;
    let _idempotency_key =
        finance_command_text(&receipt.idempotency_key, "HR idempotency key", 512)?;
    if receipt.version == 0 {
        return Err("HR receipt version must be positive".into());
    }
    Ok(HrJsonCommandReceipt {
        aggregate_type,
        aggregate_id,
        version: receipt.version,
        replayed: receipt.replayed,
        correlation_id,
    })
}

#[cfg(target_arch = "wasm32")]
async fn save_hr_json(
    scope: HrEmployeeScope,
    input: HrJsonCommandInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<HrJsonCommandReceipt, String> {
    let channel = tonic_web_wasm_client::Client::new(GRPC_ENDPOINT.to_string());
    let mut client = HrServiceClient::new(channel);
    let request = hr_json_command_request(&scope, &input, &principal_ref, &session_id)?;
    let receipt = match request {
        HrJsonCommandRequest::Employee(mut request) => {
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .save_hr_employee(request)
                .await
                .map_err(hr_rpc_error)?
                .into_inner();
            hr_json_receipt(response.receipt, &response.correlation_id)
        }
        HrJsonCommandRequest::Leave(mut request) => {
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .save_hr_leave(request)
                .await
                .map_err(hr_rpc_error)?
                .into_inner();
            hr_json_receipt(response.receipt, &response.correlation_id)
        }
        HrJsonCommandRequest::Expense(mut request) => {
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .save_hr_expense(request)
                .await
                .map_err(hr_rpc_error)?
                .into_inner();
            hr_json_receipt(response.receipt, &response.correlation_id)
        }
        HrJsonCommandRequest::Payroll(mut request) => {
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .save_hr_payroll(request)
                .await
                .map_err(hr_rpc_error)?
                .into_inner();
            hr_json_receipt(response.receipt, &response.correlation_id)
        }
    }?;
    Ok(receipt)
}

