#[derive(Debug, Clone, PartialEq, Eq)]
struct HrEmployeeRecord {
    employee_id: String,
    employee_ref: String,
    display_name: String,
    company_id: String,
    branch_id: String,
    status: String,
    hired_on: String,
    terminated_on: String,
    source_version: u64,
    projected_at: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct HrEmployeeReadModel {
    scope: HrEmployeeScope,
    employees: Vec<HrEmployeeRecord>,
    has_more: bool,
    next_cursor: String,
    correlation_id: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct HrEmployeeTransitionResult {
    employee_id: String,
    version: u64,
    replayed: bool,
    correlation_id: String,
}

impl HrEmployeeTransitionResult {
    fn from_wire(
        employee_id: &str,
        response: TransitionHrEmployeeResponse,
    ) -> Result<Self, String> {
        let receipt = response
            .receipt
            .ok_or_else(|| "HR transition response omitted its receipt".to_string())?;
        let correlation_id = bounded_finance_value(
            &response.correlation_id,
            "HR transition correlation ID",
            false,
            128,
        )?;
        if receipt.aggregate_type != "hr_employee"
            || receipt.aggregate_id != employee_id
            || receipt.version == 0
        {
            return Err("HR transition receipt identity was invalid".into());
        }
        Ok(Self {
            employee_id: receipt.aggregate_id,
            version: receipt.version,
            replayed: receipt.replayed,
            correlation_id,
        })
    }
}

fn bounded_hr_date(value: &str, field: &str, allow_empty: bool) -> Result<String, String> {
    let value = value.trim();
    if value.is_empty() && allow_empty {
        return Ok(String::new());
    }
    let bytes = value.as_bytes();
    if bytes.len() != 10
        || bytes[4] != b'-'
        || bytes[7] != b'-'
        || !bytes
            .iter()
            .enumerate()
            .all(|(index, byte)| matches!(index, 4 | 7) || byte.is_ascii_digit())
    {
        return Err(format!("{field} was malformed"));
    }
    let month = value[5..7]
        .parse::<u8>()
        .map_err(|_| format!("{field} was malformed"))?;
    let day = value[8..10]
        .parse::<u8>()
        .map_err(|_| format!("{field} was malformed"))?;
    if month == 0 || month > 12 || day == 0 || day > 31 {
        return Err(format!("{field} was malformed"));
    }
    Ok(value.to_owned())
}

impl HrEmployeeReadModel {
    fn from_wire(
        scope: &HrEmployeeScope,
        response: ListHrEmployeesResponse,
    ) -> Result<Self, String> {
        if response.employees.len() > 100 {
            return Err("HR employee page exceeded its display bound".into());
        }
        let correlation_id = bounded_finance_value(
            &response.correlation_id,
            "HR employee correlation ID",
            false,
            128,
        )?;
        let next_cursor = bounded_finance_value(
            &response.next_before_employee_id,
            "HR employee pagination cursor",
            true,
            128,
        )?;
        if response.has_more {
            if next_cursor.is_empty() || Uuid::parse_str(&next_cursor).is_err() {
                return Err("HR employee pagination cursor was invalid".into());
            }
        } else if !next_cursor.is_empty() {
            return Err("HR employee returned a cursor without another page".into());
        }
        let employees = response
            .employees
            .into_iter()
            .map(|row| Self::employee_from_wire(scope, row))
            .collect::<Result<Vec<_>, String>>()?;
        Ok(Self {
            scope: scope.clone(),
            employees,
            has_more: response.has_more,
            next_cursor,
            correlation_id,
        })
    }

    fn employee_from_wire(
        scope: &HrEmployeeScope,
        row: HrEmployeeReadRow,
    ) -> Result<HrEmployeeRecord, String> {
        let employee_id = bounded_finance_uuid(&row.employee_id, "employee")
            .map_err(|_| "HR employee ID was not a UUID".to_string())?;
        let holding_id = bounded_finance_uuid(&row.holding_id, "holding")
            .map_err(|_| "HR employee holding ID was not a UUID".to_string())?;
        let company_id = bounded_finance_uuid(&row.company_id, "company")
            .map_err(|_| "HR employee company ID was not a UUID".to_string())?;
        if holding_id != scope.finance.holding_id || company_id != scope.company_id {
            return Err("HR employee row escaped its requested scope".into());
        }
        let branch_id = bounded_finance_value(&row.branch_id, "HR employee branch ID", true, 128)?;
        if !branch_id.is_empty() && Uuid::parse_str(&branch_id).is_err() {
            return Err("HR employee branch ID was not a UUID".into());
        }
        if !scope.branch_id.is_empty() && branch_id != scope.branch_id {
            return Err("HR employee row escaped its branch scope".into());
        }
        let employee_ref =
            bounded_finance_value(&row.employee_ref, "HR employee reference", false, 128)?;
        let display_name =
            bounded_finance_value(&row.display_name, "HR employee display name", false, 255)?;
        let status = bounded_finance_value(&row.status, "HR employee status", false, 32)?;
        if !matches!(
            status.as_str(),
            "draft" | "active" | "on_leave" | "suspended" | "terminated"
        ) {
            return Err("HR employee status was invalid".into());
        }
        let hired_on = bounded_hr_date(&row.hired_on, "HR employee hired date", false)?;
        let terminated_on =
            bounded_hr_date(&row.terminated_on, "HR employee terminated date", true)?;
        if (status == "terminated") == terminated_on.is_empty() {
            return Err("HR employee termination state was inconsistent".into());
        }
        if row.source_version == 0 {
            return Err("HR employee source version must be positive".into());
        }
        let projected_at = bounded_finance_value(
            &row.projected_at,
            "HR employee projection timestamp",
            false,
            64,
        )?;
        Ok(HrEmployeeRecord {
            employee_id,
            employee_ref,
            display_name,
            company_id,
            branch_id,
            status,
            hired_on,
            terminated_on,
            source_version: row.source_version,
            projected_at,
        })
    }
}

