fn hr_read_correlation(value: &str, field: &str) -> Result<String, String> {
    bounded_finance_value(value, field, false, 128)
}

fn hr_scope_row(
    scope: &HrEmployeeScope,
    holding_id: &str,
    company_id: &str,
    branch_id: &str,
    label: &str,
) -> Result<String, String> {
    let holding_id = bounded_finance_uuid(holding_id, &format!("{label} holding"))
        .map_err(|_| format!("{label} holding ID was not a UUID"))?;
    let company_id = bounded_finance_uuid(company_id, &format!("{label} company"))
        .map_err(|_| format!("{label} company ID was not a UUID"))?;
    if holding_id != scope.finance.holding_id || company_id != scope.company_id {
        return Err(format!("{label} row escaped its requested scope"));
    }
    let branch_id = bounded_finance_value(branch_id, &format!("{label} branch ID"), true, 128)?;
    if !branch_id.is_empty() && Uuid::parse_str(&branch_id).is_err() {
        return Err(format!("{label} branch ID was not a UUID"));
    }
    if !scope.branch_id.is_empty() && branch_id != scope.branch_id {
        return Err(format!("{label} row escaped its branch scope"));
    }
    Ok(branch_id)
}

fn hr_source_fields(
    source_version: u64,
    source_event_id: &str,
    projected_at: &str,
    label: &str,
) -> Result<String, String> {
    if source_version == 0 {
        return Err(format!("{label} source version must be positive"));
    }
    let _source_event_id = bounded_finance_value(
        source_event_id,
        &format!("{label} source event ID"),
        false,
        128,
    )?;
    bounded_finance_value(
        projected_at,
        &format!("{label} projection timestamp"),
        false,
        64,
    )
}

fn hr_page_cursor(value: &str, has_more: bool, label: &str) -> Result<(), String> {
    let cursor = bounded_finance_value(value, &format!("{label} pagination cursor"), true, 128)?;
    if has_more {
        if cursor.is_empty() {
            return Err(format!("{label} page omitted its next cursor"));
        }
    } else if !cursor.is_empty() {
        return Err(format!(
            "{label} page returned a cursor without another page"
        ));
    }
    Ok(())
}

fn hr_leave_from_wire(
    scope: &HrEmployeeScope,
    row: HrLeaveReadRow,
) -> Result<HrLeaveRecord, String> {
    hr_scope_row(
        scope,
        &row.holding_id,
        &row.company_id,
        &row.branch_id,
        "HR leave",
    )?;
    let leave_id = bounded_finance_uuid(&row.leave_id, "HR leave")
        .map_err(|_| "HR leave ID was not a UUID".to_string())?;
    let employee_id = bounded_finance_uuid(&row.employee_id, "HR leave employee")
        .map_err(|_| "HR leave employee ID was not a UUID".to_string())?;
    let starts_on = bounded_hr_date(&row.starts_on, "HR leave start date", false)?;
    let ends_on = bounded_hr_date(&row.ends_on, "HR leave end date", false)?;
    if starts_on > ends_on {
        return Err("HR leave dates were reversed".into());
    }
    let reason = bounded_finance_value(&row.reason, "HR leave reason", true, 512)?;
    let status = bounded_finance_value(&row.status, "HR leave status", false, 32)?;
    if !matches!(
        status.as_str(),
        "draft" | "requested" | "approved" | "rejected" | "cancelled" | "taken"
    ) {
        return Err("HR leave status was invalid".into());
    }
    let requested_by = bounded_finance_value(&row.requested_by, "HR leave requester", false, 128)?;
    let approved_by = bounded_finance_value(&row.approved_by, "HR leave approver", true, 128)?;
    let projected_at = hr_source_fields(
        row.source_version,
        &row.source_event_id,
        &row.projected_at,
        "HR leave",
    )?;
    Ok(HrLeaveRecord {
        leave_id,
        employee_id,
        starts_on,
        ends_on,
        reason,
        status,
        requested_by,
        approved_by,
        source_version: row.source_version,
        projected_at,
    })
}

fn hr_expense_from_wire(
    scope: &HrEmployeeScope,
    row: HrExpenseReadRow,
) -> Result<HrExpenseRecord, String> {
    hr_scope_row(
        scope,
        &row.holding_id,
        &row.company_id,
        &row.branch_id,
        "HR expense",
    )?;
    let expense_id = bounded_finance_uuid(&row.expense_id, "HR expense")
        .map_err(|_| "HR expense ID was not a UUID".to_string())?;
    let employee_id = bounded_finance_uuid(&row.employee_id, "HR expense employee")
        .map_err(|_| "HR expense employee ID was not a UUID".to_string())?;
    if row.amount_minor < 0 {
        return Err("HR expense amount was negative".into());
    }
    let currency = bounded_finance_value(&row.currency, "HR expense currency", false, 3)?;
    if currency.len() != 3 || !currency.bytes().all(|byte| byte.is_ascii_uppercase()) {
        return Err("HR expense currency was invalid".into());
    }
    let status = bounded_finance_value(&row.status, "HR expense status", false, 32)?;
    if !matches!(
        status.as_str(),
        "draft" | "submitted" | "approved" | "rejected" | "paid" | "reimbursed"
    ) {
        return Err("HR expense status was invalid".into());
    }
    let submitted_by =
        bounded_finance_value(&row.submitted_by, "HR expense submitter", false, 128)?;
    let approved_by = bounded_finance_value(&row.approved_by, "HR expense approver", true, 128)?;
    let projected_at = hr_source_fields(
        row.source_version,
        &row.source_event_id,
        &row.projected_at,
        "HR expense",
    )?;
    Ok(HrExpenseRecord {
        expense_id,
        employee_id,
        currency,
        amount_minor: row.amount_minor,
        status,
        submitted_by,
        approved_by,
        source_version: row.source_version,
        projected_at,
    })
}

fn hr_payroll_line_from_wire(
    scope: &HrEmployeeScope,
    row: HrPayrollLineReadRow,
) -> Result<HrPayrollLineRecord, String> {
    hr_scope_row(
        scope,
        &row.holding_id,
        &row.company_id,
        &row.branch_id,
        "HR payroll line",
    )?;
    let employee_id = bounded_finance_uuid(&row.employee_id, "HR payroll employee")
        .map_err(|_| "HR payroll employee ID was not a UUID".to_string())?;
    if row.line_no <= 0
        || row.gross_minor < 0
        || row.deductions_minor < 0
        || row.net_minor < 0
        || row.deductions_minor > row.gross_minor
        || row.gross_minor - row.deductions_minor != row.net_minor
    {
        return Err("HR payroll line amounts were not reconciled".into());
    }
    let _ = hr_source_fields(
        row.source_version,
        &row.source_event_id,
        &row.projected_at,
        "HR payroll line",
    )?;
    Ok(HrPayrollLineRecord {
        line_no: row.line_no as u32,
        employee_id,
        gross_minor: row.gross_minor,
        deductions_minor: row.deductions_minor,
        net_minor: row.net_minor,
    })
}

fn hr_payroll_from_wire(
    scope: &HrEmployeeScope,
    row: HrPayrollRunReadRow,
) -> Result<HrPayrollRecord, String> {
    hr_scope_row(
        scope,
        &row.holding_id,
        &row.company_id,
        &row.branch_id,
        "HR payroll",
    )?;
    let payroll_id = bounded_finance_uuid(&row.payroll_id, "HR payroll")
        .map_err(|_| "HR payroll ID was not a UUID".to_string())?;
    let starts_on = bounded_hr_date(&row.starts_on, "HR payroll start date", false)?;
    let ends_on = bounded_hr_date(&row.ends_on, "HR payroll end date", false)?;
    if starts_on > ends_on
        || row.total_gross_minor < 0
        || row.total_deductions_minor < 0
        || row.total_net_minor < 0
        || row.total_deductions_minor > row.total_gross_minor
        || row.total_gross_minor - row.total_deductions_minor != row.total_net_minor
    {
        return Err("HR payroll totals or dates were invalid".into());
    }
    let status = bounded_finance_value(&row.status, "HR payroll status", false, 32)?;
    if !matches!(
        status.as_str(),
        "draft" | "prepared" | "reviewed" | "approved" | "posted" | "paid" | "voided"
    ) {
        return Err("HR payroll status was invalid".into());
    }
    if row.lines.len() > 100 {
        return Err("HR payroll line page exceeded its bound".into());
    }
    let lines = row
        .lines
        .into_iter()
        .map(|line| hr_payroll_line_from_wire(scope, line))
        .collect::<Result<Vec<_>, _>>()?;
    if !row.lines_truncated {
        let totals =
            lines
                .iter()
                .try_fold((0_i64, 0_i64, 0_i64), |(gross, deductions, net), line| {
                    Ok::<_, String>((
                        gross
                            .checked_add(line.gross_minor)
                            .ok_or("HR payroll gross overflow")?,
                        deductions
                            .checked_add(line.deductions_minor)
                            .ok_or("HR payroll deductions overflow")?,
                        net.checked_add(line.net_minor)
                            .ok_or("HR payroll net overflow")?,
                    ))
                })?;
        if totals
            != (
                row.total_gross_minor,
                row.total_deductions_minor,
                row.total_net_minor,
            )
        {
            return Err("HR payroll lines did not reconcile with totals".into());
        }
    }
    let prepared_by = bounded_finance_value(&row.prepared_by, "HR payroll preparer", true, 128)?;
    let reviewed_by = bounded_finance_value(&row.reviewed_by, "HR payroll reviewer", true, 128)?;
    let approved_by = bounded_finance_value(&row.approved_by, "HR payroll approver", true, 128)?;
    let projected_at = hr_source_fields(
        row.source_version,
        &row.source_event_id,
        &row.projected_at,
        "HR payroll",
    )?;
    Ok(HrPayrollRecord {
        payroll_id,
        starts_on,
        ends_on,
        status,
        prepared_by,
        reviewed_by,
        approved_by,
        total_gross_minor: row.total_gross_minor,
        total_deductions_minor: row.total_deductions_minor,
        total_net_minor: row.total_net_minor,
        lines,
        lines_truncated: row.lines_truncated,
        source_version: row.source_version,
        projected_at,
    })
}

