impl HrReadBundle {
    fn from_wire(
        scope: &HrEmployeeScope,
        employees: ListHrEmployeesResponse,
        leaves: ListHrLeaveRequestsResponse,
        expenses: ListHrExpenseClaimsResponse,
        payroll: ListHrPayrollRunsResponse,
        reassignments: ListHrReassignmentsResponse,
    ) -> Result<Self, String> {
        let employee_model = HrEmployeeReadModel::from_wire(scope, employees)?;
        if leaves.leave_requests.len() > 100
            || expenses.expenses.len() > 100
            || payroll.payroll_runs.len() > 100
            || reassignments.reassignments.len() > 100
        {
            return Err("HR projection page exceeded its display bound".into());
        }
        hr_page_cursor(&leaves.next_cursor, leaves.has_more, "HR leave")?;
        hr_page_cursor(&expenses.next_cursor, expenses.has_more, "HR expense")?;
        hr_page_cursor(&payroll.next_cursor, payroll.has_more, "HR payroll")?;
        hr_page_cursor(
            &reassignments.next_cursor,
            reassignments.has_more,
            "HR reassignment",
        )?;
        let _ = hr_read_correlation(&leaves.correlation_id, "HR leave correlation ID")?;
        let _ = hr_read_correlation(&expenses.correlation_id, "HR expense correlation ID")?;
        let _ = hr_read_correlation(&payroll.correlation_id, "HR payroll correlation ID")?;
        let _ = hr_read_correlation(
            &reassignments.correlation_id,
            "HR reassignment correlation ID",
        )?;
        Ok(Self {
            scope: scope.clone(),
            employees: employee_model.employees,
            employee_has_more: employee_model.has_more,
            leave_requests: leaves
                .leave_requests
                .into_iter()
                .map(|row| hr_leave_from_wire(scope, row))
                .collect::<Result<Vec<_>, _>>()?,
            leave_has_more: leaves.has_more,
            expenses: expenses
                .expenses
                .into_iter()
                .map(|row| hr_expense_from_wire(scope, row))
                .collect::<Result<Vec<_>, _>>()?,
            expense_has_more: expenses.has_more,
            payroll_runs: payroll
                .payroll_runs
                .into_iter()
                .map(|row| hr_payroll_from_wire(scope, row))
                .collect::<Result<Vec<_>, _>>()?,
            payroll_has_more: payroll.has_more,
            reassignments: reassignments
                .reassignments
                .into_iter()
                .map(|row| hr_reassignment_from_wire(scope, row))
                .collect::<Result<Vec<_>, _>>()?,
            reassignment_has_more: reassignments.has_more,
            correlation_id: employee_model.correlation_id,
        })
    }
}

