#[derive(Debug, Clone, PartialEq, Eq)]
struct LegalContractReadModel {
    scope: LegalContractScope,
    contracts: Vec<LegalContractRecord>,
    has_more: bool,
    next_cursor: String,
    correlation_id: String,
}

impl LegalContractReadModel {
    fn from_wire(
        scope: &LegalContractScope,
        response: ListLegalContractsResponse,
    ) -> Result<Self, String> {
        if response.contracts.len() > 100 {
            return Err("Legal contract page exceeded its display bound".into());
        }
        let correlation_id = bounded_finance_value(
            &response.correlation_id,
            "Legal contract correlation ID",
            false,
            128,
        )?;
        let next_cursor =
            bounded_finance_value(&response.next_cursor, "Legal contract cursor", true, 512)?;
        if response.has_more && next_cursor.is_empty() {
            return Err("Legal contract response omitted its next cursor".into());
        }
        if !response.has_more && !next_cursor.is_empty() {
            return Err("Legal contract returned a cursor without another page".into());
        }
        let contracts = response
            .contracts
            .into_iter()
            .map(|row| Self::contract_from_wire(scope, row))
            .collect::<Result<Vec<_>, String>>()?;
        Ok(Self {
            scope: scope.clone(),
            contracts,
            has_more: response.has_more,
            next_cursor,
            correlation_id,
        })
    }

    fn contract_from_wire(
        scope: &LegalContractScope,
        row: LegalContractReadRow,
    ) -> Result<LegalContractRecord, String> {
        let contract_id = bounded_finance_uuid(&row.contract_id, "contract")
            .map_err(|_| "Legal contract ID was not a UUID".to_string())?;
        let holding_id = bounded_finance_uuid(&row.holding_id, "holding")
            .map_err(|_| "Legal contract holding ID was not a UUID".to_string())?;
        let company_id = bounded_finance_uuid(&row.company_id, "company")
            .map_err(|_| "Legal contract company ID was not a UUID".to_string())?;
        if holding_id != scope.finance.holding_id || company_id != scope.company_id {
            return Err("Legal contract row escaped its requested scope".into());
        }
        let branch_id =
            bounded_finance_value(&row.branch_id, "Legal contract branch ID", true, 128)?;
        if !branch_id.is_empty() && Uuid::parse_str(&branch_id).is_err() {
            return Err("Legal contract branch ID was not a UUID".into());
        }
        if !scope.branch_id.is_empty() && branch_id != scope.branch_id {
            return Err("Legal contract row escaped its branch scope".into());
        }
        let reference =
            bounded_finance_value(&row.reference, "Legal contract reference", false, 128)?;
        let title = bounded_finance_value(&row.title, "Legal contract title", false, 255)?;
        let status = bounded_finance_value(&row.status, "Legal contract status", false, 32)?;
        if !matches!(
            status.as_str(),
            "draft" | "review" | "approved" | "active" | "expired" | "terminated" | "archived"
        ) {
            return Err("Legal contract status was invalid".into());
        }
        let retention_until = bounded_finance_value(
            &row.retention_until,
            "Legal contract retention timestamp",
            false,
            64,
        )?;
        let retention_state =
            bounded_finance_value(&row.retention_state, "Legal retention state", false, 16)?;
        if !matches!(retention_state.as_str(), "active" | "ended") {
            return Err("Legal retention state was invalid".into());
        }
        if row.parties.len() > 256 {
            return Err("Legal contract party set exceeded its display bound".into());
        }
        for party in &row.parties {
            if Uuid::parse_str(&party.party_id).is_err()
                || bounded_finance_value(&party.role, "Legal party role", false, 128).is_err()
            {
                return Err("Legal contract party metadata was invalid".into());
            }
        }
        if row.source_version == 0 {
            return Err("Legal contract source version must be positive".into());
        }
        let projected_at = bounded_finance_value(
            &row.projected_at,
            "Legal contract projection timestamp",
            false,
            64,
        )?;
        Ok(LegalContractRecord {
            contract_id,
            reference,
            title,
            company_id,
            branch_id,
            status,
            retention_until,
            retention_state,
            party_count: row.parties.len(),
            approved: !row.approved_by.trim().is_empty(),
            source_version: row.source_version,
            projected_at,
        })
    }
}

