        let currency = bounded_finance_value(&row.currency, "POS currency", false, 3)?;
        if currency.len() != 3 || !currency.chars().all(|value| value.is_ascii_uppercase()) {
            return Err("POS currency was invalid".into());
        }
        let status = bounded_finance_value(&row.status, "POS sale status", false, 32)?;
