/// Display-safe access-audit data. The server response also contains a session reference and
/// customer identifier; neither is needed by this route, so neither crosses into the view model.
#[derive(Debug, Clone, PartialEq, Eq)]
struct CustomerAccessAuditEntryView {
    audit_id: String,
    actor: String,
    module: String,
    scope: String,
    purpose: String,
    occurred_at: String,
    correlation_id: String,
}

const CUSTOMER_360_DETAIL_SECTION_NAMES: &[&str] = &[
    "account",
    "organization",
    "contacts",
    "commercial",
    "entitlements",
    "onboarding",
    "health",
    "support",
    "access_audit",
    "notes",
];

const CUSTOMER_360_DETAIL_FACT_MAX_BYTES: usize = 256;

#[derive(Debug, Clone, PartialEq, Eq)]
struct Customer360SectionSummary {
    name: String,
    state: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Customer360SectionFactView {
    section: String,
    key: String,
    value: String,
}

fn customer_360_fact_key_allowed(section: &str, key: &str) -> bool {
    match section {
        "account" => matches!(
            key,
            "account_code"
                | "trading_name"
                | "country"
                | "account_state"
                | "subscription_state"
                | "responsibility_contact_count"
                | "customer_success_owner_present"
        ),
        "organization" => matches!(
            key,
            "holding_count"
                | "company_count"
                | "branch_count"
                | "department_count"
                | "active_user_count"
                | "expiring_role_count"
                | "open_ticket_count"
                | "module_count"
        ),
        "contacts" => matches!(key, "contact_count" | "customer_success_owner_present"),
        "commercial" => matches!(
            key,
            "payment_state"
                | "invoice_count"
                | "quote_count"
                | "discount_count"
                | "lifetime_value_minor"
                | "module_allocation_count"
        ),
        "entitlements" => matches!(
            key,
            "active_module_count"
                | "subscription_allocation_count"
                | "organization_allocation_count"
        ),
        "onboarding" => matches!(
            key,
            "state" | "imports_completed" | "training_completed" | "go_live_at" | "owner_present"
        ),
        "health" => matches!(
            key,
            "state"
                | "projection_lag_seconds"
                | "worker_failures"
                | "storage_status"
                | "backup_status"
                | "point_in_time_recovery_status"
                | "integration_failure_count"
                | "api_usage_count"
                | "last_activity_at"
        ),
        "support" => key == "open_ticket_count",
        "access_audit" => matches!(key, "read_count" | "last_access_at" | "customer_visible"),
        "notes" => matches!(key, "note_count" | "has_next_page"),
        _ => false,
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Customer360DetailRecord {
    customer_id: String,
    sections: Vec<Customer360SectionSummary>,
    facts: Vec<Customer360SectionFactView>,
    notes: CustomerNotesDisplayModel,
    projection_updated_at: String,
    freshness: String,
    read_only: bool,
    supported: bool,
    present: bool,
    unsupported_reason: String,
}

fn customer_360_section_summaries(
    section_states: &[erpx_proto::platform::Customer360SectionState],
    supported: bool,
    present: bool,
) -> Result<Vec<Customer360SectionSummary>, String> {
    if section_states.is_empty() {
        if supported && present {
            return Err("Customer 360 detail omitted section states".into());
        }
        return Ok(Vec::new());
    }
    if section_states.len() != CUSTOMER_360_DETAIL_SECTION_NAMES.len() {
        return Err("Customer 360 detail section state count was invalid".into());
    }
    let mut summaries = Vec::with_capacity(section_states.len());
    for section in section_states {
        let name = bounded_customer360_value(&section.section, "Customer 360 section", false, 32)?;
        if !CUSTOMER_360_DETAIL_SECTION_NAMES.contains(&name.as_str()) {
            return Err("Customer 360 detail section was not allow-listed".into());
        }
        let state =
            bounded_customer360_value(&section.state, "Customer 360 section state", false, 16)?;
        if !matches!(state.as_str(), "present" | "absent" | "unsupported") {
            return Err("Customer 360 detail section state was invalid".into());
        }
        if summaries
            .iter()
            .any(|summary: &Customer360SectionSummary| summary.name == name)
        {
            return Err("Customer 360 detail section was repeated".into());
        }
        summaries.push(Customer360SectionSummary { name, state });
    }
    if CUSTOMER_360_DETAIL_SECTION_NAMES
        .iter()
        .any(|name| !summaries.iter().any(|summary| summary.name == *name))
    {
        return Err("Customer 360 detail section state was incomplete".into());
    }
    Ok(summaries)
}

fn customer_360_section_facts(
    facts: &[erpx_proto::platform::Customer360SectionFact],
) -> Result<Vec<Customer360SectionFactView>, String> {
    if facts.len() > 100 {
        return Err("Customer 360 detail fact count exceeded its display bound".into());
    }
    let mut parsed = Vec::with_capacity(facts.len());
    for fact in facts {
        let section =
            bounded_customer360_value(&fact.section, "Customer 360 fact section", false, 32)?;
        let key = bounded_customer360_value(&fact.key, "Customer 360 fact key", false, 64)?;
        let value = bounded_customer360_value(
            &fact.value,
            "Customer 360 fact value",
            false,
            CUSTOMER_360_DETAIL_FACT_MAX_BYTES,
        )?;
        if !CUSTOMER_360_DETAIL_SECTION_NAMES.contains(&section.as_str())
            || !customer_360_fact_key_allowed(&section, &key)
        {
            return Err("Customer 360 fact was not allow-listed".into());
        }
        if parsed
            .iter()
            .any(|item: &Customer360SectionFactView| item.section == section && item.key == key)
        {
            return Err("Customer 360 fact was repeated".into());
        }
        parsed.push(Customer360SectionFactView {
            section,
            key,
            value,
        });
    }
    Ok(parsed)
}

impl Customer360DetailRecord {
    fn from_response(
        value: erpx_proto::platform::GetCustomer360DetailResponse,
    ) -> Result<Self, String> {
        let customer_id =
            bounded_customer360_value(&value.customer_id, "Customer 360 customer ID", false, 128)?;
        let projection_updated_at = bounded_customer360_value(
            &value.projection_updated_at,
            "Customer 360 projection timestamp",
            true,
            64,
        )?;
        let freshness =
            bounded_customer360_value(&value.freshness, "Customer 360 freshness", false, 32)?;
        let unsupported_reason = bounded_customer360_value(
            &value.unsupported_reason,
            "Customer 360 unsupported reason",
            true,
            512,
        )?;
        let sections =
            customer_360_section_summaries(&value.section_states, value.supported, value.present)?;
        let facts = customer_360_section_facts(&value.section_facts)?;
        if value.supported && value.present && facts.is_empty() {
            return Err("Customer 360 detail omitted allow-listed facts".into());
        }
        if value.notes.len() > 100 {
            return Err("Customer 360 notes page exceeded its display bound".into());
        }
        let next_before_occurred_at = bounded_customer360_value(
            &value.notes_next_before_occurred_at,
            "Customer 360 notes cursor timestamp",
            true,
            64,
        )?;
        let next_before_id = bounded_customer360_value(
            &value.notes_next_before_id,
            "Customer 360 notes cursor ID",
            true,
            128,
        )?;
        if next_before_occurred_at.is_empty() != next_before_id.is_empty() {
            return Err("Customer 360 notes cursor was incomplete".into());
        }
        if !next_before_id.is_empty() && Uuid::parse_str(&next_before_id).is_err() {
            return Err("Customer 360 notes cursor ID was not a UUID".into());
        }
        let note_inputs = value.notes.into_iter().map(|note| {
            CustomerNoteDtoInput::new(note.id, note.author_ref, note.created_at, note.body)
        });
        let notes = CustomerNotesDisplayModel::from_safe_dtos(
            note_inputs,
            (!next_before_occurred_at.is_empty()).then_some(next_before_occurred_at),
            (!next_before_id.is_empty()).then_some(next_before_id),
        );
        if notes.dropped_record_count() != 0 {
            return Err("Customer 360 notes response contained invalid display fields".into());
        }
        Ok(Self {
            customer_id,
            sections,
            facts,
            notes,
            projection_updated_at,
            freshness,
            read_only: value.read_only,
            supported: value.supported,
            present: value.present,
            unsupported_reason,
        })
    }
}

fn bounded_customer360_value(
    value: &str,
    label: &str,
    allow_empty: bool,
    max_bytes: usize,
) -> Result<String, String> {
    let value = value.trim();
    if !allow_empty && value.is_empty() {
        return Err(format!("{label} was empty"));
    }
    if value.len() > max_bytes || value.chars().any(char::is_control) {
        return Err(format!("{label} was invalid"));
    }
    Ok(value.to_string())
}

