#[derive(Debug, Clone, PartialEq, Eq)]
struct CustomerAccessAuditPage {
    entries: Vec<CustomerAccessAuditEntryView>,
    projection_updated_at: String,
    freshness: String,
    read_only: bool,
    correlation_id: String,
    present: bool,
    has_next_page: bool,
    next_before_occurred_at: String,
    next_before_audit_id: String,
}

impl CustomerAccessAuditPage {
    fn from_response(
        response: erpx_proto::platform::GetCustomerAccessAuditResponse,
    ) -> Result<Self, String> {
        if response.entries.len() > CUSTOMER_ACCESS_AUDIT_PAGE_SIZE as usize {
            return Err("customer access-audit response exceeded its page bound".into());
        }
        let next_before_occurred_at = bounded_customer360_value(
            &response.next_before_occurred_at,
            "customer access-audit cursor timestamp",
            true,
            64,
        )?;
        let next_before_audit_id = bounded_customer360_value(
            &response.next_before_audit_id,
            "customer access-audit cursor ID",
            true,
            128,
        )?;
        if next_before_occurred_at.is_empty() != next_before_audit_id.is_empty() {
            return Err("customer access-audit cursor was incomplete".into());
        }
        if !next_before_audit_id.is_empty() && Uuid::parse_str(&next_before_audit_id).is_err() {
            return Err("customer access-audit cursor ID was not a UUID".into());
        }
        let entries = response
            .entries
            .into_iter()
            .map(CustomerAccessAuditEntryView::from)
            .collect::<Vec<_>>();
        for entry in &entries {
            bounded_customer360_value(&entry.audit_id, "customer access-audit ID", false, 128)?;
            bounded_customer360_value(&entry.actor, "customer access-audit actor", false, 256)?;
            bounded_customer360_value(&entry.module, "customer access-audit module", false, 128)?;
            bounded_customer360_value(&entry.scope, "customer access-audit scope", false, 4096)?;
            bounded_customer360_value(&entry.purpose, "customer access-audit purpose", false, 256)?;
            bounded_customer360_value(
                &entry.occurred_at,
                "customer access-audit timestamp",
                false,
                64,
            )?;
            bounded_customer360_value(
                &entry.correlation_id,
                "customer access-audit correlation ID",
                false,
                128,
            )?;
        }
        Ok(Self {
            entries,
            projection_updated_at: response.projection_updated_at,
            freshness: response.freshness,
            read_only: response.read_only,
            correlation_id: response.correlation_id,
            present: response.present,
            has_next_page: !next_before_occurred_at.is_empty(),
            next_before_occurred_at,
            next_before_audit_id,
        })
    }
}

const INCIDENT_LIST_PAGE_SIZE: u32 = 100;
const SUPPORT_TICKET_LIST_PAGE_SIZE: u32 = 100;

#[derive(Debug, Clone, PartialEq, Eq)]
struct IncidentReadPage {
    model: IncidentListDisplayModel,
    has_more: bool,
    correlation_id: String,
}

impl IncidentReadPage {
    fn from_wire(response: ListIncidentsResponse) -> Result<Self, String> {
        if response.incidents.len() > INCIDENT_LIST_PAGE_SIZE as usize {
            return Err("incident response exceeded its page bound".into());
        }
        let correlation_id = bounded_incident_value(
            &response.correlation_id,
            "incident correlation ID",
            false,
            128,
        )?;
        let inputs = response.incidents.into_iter().map(incident_dto_input);
        let model =
            IncidentListDisplayModel::from_safe_dtos(IncidentProjectionMetadata::unknown(), inputs);
        if model.dropped_record_count() != 0 {
            return Err("incident response contained invalid display fields".into());
        }
        Ok(Self {
            model,
            has_more: response.has_more,
            correlation_id,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SupportTicketReadPage {
    model: SupportTicketListDisplayModel,
    has_more: bool,
    next_cursor: String,
    correlation_id: String,
}

impl SupportTicketReadPage {
    fn from_wire(response: ListTicketsResponse) -> Result<Self, String> {
        if response.tickets.len() > SUPPORT_TICKET_LIST_PAGE_SIZE as usize {
            return Err("support ticket response exceeded its page bound".into());
        }
        let correlation_id = bounded_incident_value(
            &response.correlation_id,
            "support ticket correlation ID",
            false,
            128,
        )?;
        let next_cursor =
            bounded_incident_value(&response.next_cursor, "support ticket cursor", true, 512)?;
        if response.has_more == next_cursor.is_empty() {
            return Err("support ticket pagination metadata was inconsistent".into());
        }
        let inputs = response.tickets.into_iter().map(|ticket| {
            SupportTicketDtoInput::new(
                ticket.id,
                ticket.customer_id,
                ticket.status,
                ticket.severity,
            )
        });
        let model = SupportTicketListDisplayModel::from_safe_dtos(
            SupportProjectionMetadata::unknown(),
            inputs,
        );
        if model.dropped_record_count() != 0 {
            return Err("support ticket response contained invalid display fields".into());
        }
        Ok(Self {
            model,
            has_more: response.has_more,
            next_cursor,
            correlation_id,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SupportDiagnosticsRead {
    model: SupportDisplayModel,
    schema_version: String,
    captured_at: String,
    correlation_id: String,
}

impl SupportDiagnosticsRead {
    fn from_wire(response: GetSupportDiagnosticsResponse) -> Result<Self, String> {
        if response.fields.len() > 32 {
            return Err("support diagnostics response exceeded its field bound".into());
        }
        let schema_version = bounded_incident_value(
            &response.schema_version,
            "support diagnostics schema version",
            false,
            128,
        )?;
        let captured_at = bounded_incident_value(
            &response.captured_at,
            "support diagnostics captured timestamp",
            false,
            64,
        )?;
        let correlation_id = bounded_incident_value(
            &response.correlation_id,
            "support diagnostics correlation ID",
            false,
            128,
        )?;
        let metadata = SupportProjectionMetadata::fresh(captured_at.clone());
        let context = SupportContextMetadata::new(
            SupportMode::DiagnosticRead,
            SupportApprovalState::Approved,
            SupportImpersonationState::NotActive,
            true,
            None::<String>,
        );
        let fields = response
            .fields
            .iter()
            .map(|field| SupportFieldInput::new(&field.key, &field.value));
        let model = SupportDisplayModel::from_untrusted_fields(
            SupportRoute::PlatformSupportDiagnostics,
            metadata,
            context,
            fields,
        );
        if model.fields().is_empty() || model.redacted_field_count() != 0 {
            return Err("support diagnostics response contained invalid display fields".into());
        }
        Ok(Self {
            model,
            schema_version,
            captured_at,
            correlation_id,
        })
    }
}

/// Bounded command input for the platform support/incident surface. The
/// authenticated principal is injected into the command context and, for
/// incident creation, is also the only accepted commander identity; callers
/// cannot forge actor or aggregate identity through these fields.
#[derive(Debug, Clone, PartialEq, Eq)]
enum SupportCommandInput {
    CreateTicket {
        customer_id: String,
        severity: String,
        description: String,
    },
    TransitionTicket {
        ticket_id: String,
        next_status: String,
        expected_version: String,
    },
    CreateIncident {
        leads: String,
        affected_services: String,
        affected_customer_accounts: String,
    },
    TransitionIncident {
        incident_id: String,
        next_status: String,
        expected_version: String,
    },
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SupportCommandReceipt {
    resource: String,
    resource_id: String,
    status: String,
    version: u64,
    correlation_id: String,
}

fn support_command_context(
    principal_ref: &str,
    session_id: &str,
    purpose: &str,
    idempotency_key: &str,
    expected_version: u64,
) -> CommandContext {
    let mut context = platform_command_context(principal_ref, session_id, purpose, idempotency_key);
    context.expected_aggregate_version = expected_version;
    if let Some(audit) = context.audit.as_mut() {
        audit.module = "support".into();
    }
    context
}

fn support_csv_values(
    value: &str,
    field: &str,
    max_items: usize,
    max_item_bytes: usize,
) -> Result<Vec<String>, String> {
    let values = value
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| bounded_incident_value(value, field, false, max_item_bytes))
        .collect::<Result<Vec<_>, _>>()?;
    if values.len() > max_items {
        return Err(format!("{field} has too many entries"));
    }
    Ok(values)
}

fn support_expected_version(value: &str, field: &str) -> Result<u64, String> {
    let version = value
        .trim()
        .parse::<u64>()
        .map_err(|_| format!("{field} must be a positive integer"))?;
    if version == 0 {
        return Err(format!("{field} must be positive"));
    }
    Ok(version)
}

fn support_next_version(version: u64, field: &str) -> Result<u64, String> {
    version
        .checked_add(1)
        .ok_or_else(|| format!("{field} exceeded its version bound"))
}

fn support_ticket_request(
    input: &SupportCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<(tonic::Request<CreateTicketRequest>, String), String> {
    let SupportCommandInput::CreateTicket {
        customer_id,
        severity,
        description,
    } = input
    else {
        return Err("support ticket create input was not selected".into());
    };
    let customer_id = Uuid::parse_str(customer_id.trim())
        .map_err(|_| "customer ID must be a UUID".to_string())?;
    let severity = bounded_incident_value(severity, "ticket severity", false, 32)?;
    let description = bounded_incident_value(description, "ticket description", false, 4_096)?;
    let idempotency_key = format!("console-support-ticket-{}", Uuid::new_v4());
    let context = support_command_context(
        principal_ref,
        session_id,
        "support_ticket_create",
        &idempotency_key,
        0,
    );
    Ok((
        tonic::Request::new(CreateTicketRequest {
            customer_id: customer_id.to_string(),
            severity,
            description,
            context: Some(context.clone()),
        }),
        context.correlation_id,
    ))
}

fn support_ticket_transition_request(
    input: &SupportCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<(tonic::Request<UpdateTicketRequest>, String), String> {
    let SupportCommandInput::TransitionTicket {
        ticket_id,
        next_status,
        expected_version,
    } = input
    else {
        return Err("support ticket transition input was not selected".into());
    };
    let ticket_id =
        Uuid::parse_str(ticket_id.trim()).map_err(|_| "ticket ID must be a UUID".to_string())?;
    let next_status = bounded_incident_value(next_status, "ticket status", false, 32)?;
    let expected_version = support_expected_version(expected_version, "ticket version")?;
    let idempotency_key = format!("console-support-ticket-transition-{}", Uuid::new_v4());
    let context = support_command_context(
        principal_ref,
        session_id,
        "support_ticket_transition",
        &idempotency_key,
        expected_version,
    );
    Ok((
        tonic::Request::new(UpdateTicketRequest {
            ticket_id: ticket_id.to_string(),
            next_status,
            context: Some(context.clone()),
        }),
        context.correlation_id,
    ))
}

fn support_incident_create_request(
    input: &SupportCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<(tonic::Request<CreateIncidentRequest>, String), String> {
    let SupportCommandInput::CreateIncident {
        leads,
        affected_services,
        affected_customer_accounts,
    } = input
    else {
        return Err("incident create input was not selected".into());
    };
    let leads = support_csv_values(leads, "incident leads", 64, 128)?;
    let affected_services = support_csv_values(affected_services, "affected services", 64, 128)?;
    let affected_customer_accounts = support_csv_values(
        affected_customer_accounts,
        "affected customer accounts",
        256,
        64,
    )?
    .into_iter()
    .map(|value| {
        Uuid::parse_str(&value)
            .map(|id| id.to_string())
            .map_err(|_| "affected customer accounts must be UUIDs".to_string())
    })
    .collect::<Result<Vec<_>, _>>()?;
    let idempotency_key = format!("console-incident-create-{}", Uuid::new_v4());
    let context = support_command_context(
        principal_ref,
        session_id,
        "platform_incident_create",
        &idempotency_key,
        0,
    );
    Ok((
        tonic::Request::new(CreateIncidentRequest {
            commander_ref: principal_ref.to_owned(),
            leads,
            affected_services,
            affected_customer_accounts,
            context: Some(context.clone()),
        }),
        context.correlation_id,
    ))
}

fn support_incident_transition_request(
    input: &SupportCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<(tonic::Request<UpdateIncidentRequest>, String), String> {
    let SupportCommandInput::TransitionIncident {
        incident_id,
        next_status,
        expected_version,
    } = input
    else {
        return Err("incident transition input was not selected".into());
    };
    let incident_id = Uuid::parse_str(incident_id.trim())
        .map_err(|_| "incident ID must be a UUID".to_string())?;
    let next_status = bounded_incident_value(next_status, "incident status", false, 32)?;
    let expected_version = support_expected_version(expected_version, "incident version")?;
    let idempotency_key = format!("console-incident-transition-{}", Uuid::new_v4());
    let context = support_command_context(
        principal_ref,
        session_id,
        "platform_incident_transition",
        &idempotency_key,
        expected_version,
    );
    Ok((
        tonic::Request::new(UpdateIncidentRequest {
            incident_id: incident_id.to_string(),
            next_status,
            context: Some(context.clone()),
        }),
        context.correlation_id,
    ))
}

fn support_ticket_receipt(
    ticket: Option<erpx_proto::platform::Ticket>,
    correlation_id: String,
    expected_version: u64,
) -> Result<SupportCommandReceipt, String> {
    let ticket = ticket.ok_or_else(|| "support command omitted its ticket".to_string())?;
    let resource_id = bounded_incident_value(&ticket.id, "ticket ID", false, 128)?;
    let status = bounded_incident_value(&ticket.status, "ticket status", false, 32)?;
    let correlation_id = bounded_incident_value(
        &correlation_id,
        "support command correlation ID",
        false,
        128,
    )?;
    Ok(SupportCommandReceipt {
        resource: "ticket".into(),
        resource_id,
        status,
        version: expected_version,
        correlation_id,
    })
}

fn support_incident_receipt(
    incident: Option<IncidentMessage>,
    response_correlation_id: String,
) -> Result<SupportCommandReceipt, String> {
    let incident = incident.ok_or_else(|| "support command omitted its incident".to_string())?;
    let resource_id = bounded_incident_value(&incident.id, "incident ID", false, 128)?;
    let status = bounded_incident_value(&incident.status, "incident status", false, 32)?;
    if incident.version == 0 {
        return Err("incident command returned a zero version".into());
    }
    let correlation_id = bounded_incident_value(
        &response_correlation_id,
        "incident command correlation ID",
        false,
        128,
    )?;
    Ok(SupportCommandReceipt {
        resource: "incident".into(),
        resource_id,
        status,
        version: incident.version,
        correlation_id,
    })
}

fn incident_dto_input(value: IncidentMessage) -> IncidentDtoInput {
    IncidentDtoInput::new(
        value.id,
        value.status,
        value.commander_ref,
        value.leads,
        value.affected_services,
        value.affected_customer_accounts,
        value.version,
    )
}

fn bounded_incident_value(
    value: &str,
    field: &str,
    allow_empty: bool,
    max_len: usize,
) -> Result<String, String> {
    let value = value.trim();
    if (!allow_empty && value.is_empty())
        || value.len() > max_len
        || value.chars().any(char::is_control)
    {
        return Err(format!("{field} was malformed"));
    }
    Ok(value.to_owned())
}

fn incidents_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::InvalidArgument | tonic::Code::FailedPrecondition => {
            "incident_scope_unavailable".into()
        }
        _ => "incident_read_failed".into(),
    }
}

