fn incident_read_error_state(error: &str) -> UiStateKind {
    match error {
        "authentication_required" | "authorization_denied" => UiStateKind::Denied,
        "offline" => UiStateKind::Offline,
        _ => UiStateKind::Error,
    }
}

fn incident_read_error_message(error: &str) -> &'static str {
    match error {
        "authentication_required" => "Sign in to load the authorized platform incident projection.",
        "authorization_denied" => "The server denied this platform incident read.",
        "offline" => "The platform incident projection is temporarily unavailable.",
        "incident_scope_unavailable" => "The platform incident read scope was rejected.",
        _ => "The platform incident projection could not be loaded.",
    }
}

fn support_ticket_read_error_message(error: &str) -> &'static str {
    match error {
        "authentication_required" => {
            "Sign in to load the authorized platform support ticket projection."
        }
        "authorization_denied" => "The server denied this platform support ticket read.",
        "offline" => "The platform support ticket projection is temporarily unavailable.",
        "support_ticket_scope_unavailable" => {
            "The platform support ticket read scope was rejected."
        }
        _ => "The platform support ticket projection could not be loaded.",
    }
}

