fn crm_command_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::InvalidArgument | tonic::Code::FailedPrecondition => {
            "crm_command_rejected".into()
        }
        tonic::Code::Aborted => "crm_command_conflict".into(),
        _ => "crm_command_failed".into(),
    }
}

fn crm_command_context(
    scope: &CrmReadScope,
    principal_ref: &str,
    session_id: &str,
    purpose: &str,
    idempotency_key: &str,
    expected_version: u64,
) -> Result<CommandContext, String> {
    Uuid::parse_str(&scope.tenant_id)
        .map_err(|_| "the CRM tenant reference must be a UUID for commands".to_string())?;
    Uuid::parse_str(session_id)
        .map_err(|_| "the authenticated CRM session must be a UUID".to_string())?;
    let correlation_id = Uuid::new_v4().to_string();
    Ok(CommandContext {
        contract_version: u32::from(CONTRACT_VERSION),
        command_id: Uuid::new_v4().to_string(),
        idempotency_key: idempotency_key.to_owned(),
        correlation_id: correlation_id.clone(),
        causation_id: String::new(),
        actor: Some(ActorAttribution {
            principal_ref: principal_ref.to_owned(),
            kind: ActorKind::PlatformUser as i32,
            session_id: session_id.to_owned(),
            represented_principal_ref: String::new(),
            support_capability_id: String::new(),
        }),
        tenant_scope: Some(TenantScope {
            scope: Some(scope.scope.clone()),
        }),
        audit: Some(AuditContext {
            purpose: purpose.to_owned(),
            customer_visible: true,
            module: "crm".into(),
            correlation_id,
        }),
        expected_aggregate_version: expected_version,
        subscription_id: String::new(),
        mfa_code: String::new(),
    })
}

fn crm_json_with_command_id(value: &str, field: &str, command_id: &str) -> Result<Vec<u8>, String> {
    let mut parsed = finance_json_object(value, field, 2 * 1024 * 1024)?;
    parsed
        .as_object_mut()
        .expect("finance_json_object guarantees an object")
        .insert(
            "command_id".into(),
            serde_json::Value::String(command_id.into()),
        );
    let encoded =
        serde_json::to_vec(&parsed).map_err(|_| format!("{field} could not be encoded"))?;
    if encoded.len() > 2 * 1024 * 1024 {
        return Err(format!("{field} exceeds its size bound"));
    }
    Ok(encoded)
}

fn crm_handoff_request(
    scope: &CrmReadScope,
    input: &CrmCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<SaveCrmHandoffRequest>, String> {
    let context = crm_command_context(
        scope,
        principal_ref,
        session_id,
        "crm_handoff_save",
        &format!("crm-handoff-save-{}", Uuid::new_v4()),
        0,
    )?;
    let handoff_json =
        crm_json_with_command_id(&input.payload_json, "CRM handoff JSON", &context.command_id)?;
    Ok(tonic::Request::new(SaveCrmHandoffRequest {
        tenant_id: scope.tenant_id.clone(),
        holding_ref: scope.holding_ref.clone(),
        handoff_json,
        context: Some(context),
    }))
}

fn crm_opportunity_request(
    scope: &CrmReadScope,
    input: &CrmCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<SaveCrmOpportunityRequest>, String> {
    let expected_version =
        finance_expected_version(&input.expected_version, "expected CRM opportunity version")?;
    let context = crm_command_context(
        scope,
        principal_ref,
        session_id,
        "crm_opportunity_save",
        &format!("crm-opportunity-save-{}", Uuid::new_v4()),
        expected_version.unwrap_or_default(),
    )?;
    let opportunity_json = crm_json_with_command_id(
        &input.payload_json,
        "CRM opportunity JSON",
        &context.command_id,
    )?;
    Ok(tonic::Request::new(SaveCrmOpportunityRequest {
        tenant_id: scope.tenant_id.clone(),
        holding_ref: scope.holding_ref.clone(),
        opportunity_json,
        has_expected_version: expected_version.is_some(),
        expected_version: expected_version.unwrap_or_default(),
        context: Some(context),
    }))
}

fn crm_attribution_request(
    scope: &CrmReadScope,
    input: &CrmAttributionCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<RecordCrmAttributionRequest>, String> {
    let opportunity_id = finance_command_uuid(&input.opportunity_id, "CRM opportunity ID")?;
    let model = match input.model.trim() {
        "first_touch" | "last_touch" | "linear" | "u_shaped" | "weighted" => {
            input.model.trim().to_owned()
        }
        _ => return Err("CRM attribution model is not supported".into()),
    };
    let expected_version =
        input.expected_version.trim().parse::<u64>().map_err(|_| {
            "expected CRM opportunity version must be a positive integer".to_string()
        })?;
    if expected_version == 0 {
        return Err("expected CRM opportunity version must be a positive integer".into());
    }
    let context = crm_command_context(
        scope,
        principal_ref,
        session_id,
        "crm_attribution_record",
        &format!("crm-attribution-record-{}", Uuid::new_v4()),
        expected_version,
    )?;
    Ok(tonic::Request::new(RecordCrmAttributionRequest {
        tenant_id: scope.tenant_id.clone(),
        holding_ref: scope.holding_ref.clone(),
        opportunity_id,
        model,
        expected_opportunity_version: expected_version,
        context: Some(context),
    }))
}

fn marketing_erasure_request(
    scope: &CrmReadScope,
    input: &MarketingErasureCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<EraseMarketingProfileRequest>, String> {
    let profile_id = finance_command_uuid(&input.profile_id, "Marketing profile ID")?;
    let reason = finance_command_text(&input.reason, "Marketing erasure reason", 512)?;
    let erased_at = input.erased_at.trim();
    if erased_at.len() > 64 || erased_at.chars().any(char::is_control) {
        return Err("Marketing erasure timestamp is outside its bound".into());
    }
    let mut context = crm_command_context(
        scope,
        principal_ref,
        session_id,
        "marketing_profile_erasure",
        &format!("marketing-profile-erasure-{}", Uuid::new_v4()),
        0,
    )?;
    if let Some(audit) = context.audit.as_mut() {
        audit.module = "marketing".into();
    }
    Ok(tonic::Request::new(EraseMarketingProfileRequest {
        tenant_id: scope.tenant_id.clone(),
        holding_ref: scope.holding_ref.clone(),
        profile_id,
        reason,
        erased_at: erased_at.to_owned(),
        context: Some(context),
    }))
}

fn marketing_content_command_context(
    scope: &CrmReadScope,
    principal_ref: &str,
    session_id: &str,
    purpose: &str,
    idempotency_key: &str,
) -> Result<CommandContext, String> {
    let mut context = crm_command_context(
        scope,
        principal_ref,
        session_id,
        purpose,
        idempotency_key,
        0,
    )?;
    if let Some(audit) = context.audit.as_mut() {
        audit.module = "marketing".into();
    }
    Ok(context)
}

