#[cfg(target_arch = "wasm32")]
async fn fetch_platform_backup_jobs(
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<Vec<PlatformBackupJobRecord>, String> {
    let tenants = fetch_platform_tenants(
        access_token.clone(),
        principal_ref.clone(),
        session_id.clone(),
    )
    .await?;
    if tenants.len() > 100 {
        return Err("platform backup history tenant bound exceeded".to_string());
    }
    let channel = tonic_web_wasm_client::Client::new(GRPC_ENDPOINT.to_string());
    let mut client = PlatformOperationsServiceClient::new(channel);
    let mut jobs = Vec::new();
    for tenant in tenants {
        let mut request = tonic::Request::new(ListTenantBackupJobsRequest {
            tenant_id: tenant.tenant_id,
            page_size: 100,
            context: Some(platform_query_context(&principal_ref, &session_id)),
        });
        request.metadata_mut().insert(
            "x-erpx-access-token",
            MetadataValue::try_from(access_token.as_str())
                .map_err(|_| "access token is not valid transport metadata".to_string())?,
        );
        request.metadata_mut().insert(
            "x-erpx-actor",
            MetadataValue::try_from(principal_ref.as_str())
                .map_err(|_| "principal reference is not valid transport metadata".to_string())?,
        );
        request.metadata_mut().insert(
            "x-erpx-session",
            MetadataValue::try_from(session_id.as_str())
                .map_err(|_| "session reference is not valid transport metadata".to_string())?,
        );
        let page = client
            .list_tenant_backup_jobs(request)
            .await
            .map_err(|_| "platform backup history read failed".to_string())?
            .into_inner();
        if page.jobs.len() > 100 {
            return Err("platform backup-job page exceeded its bound".to_string());
        }
        let page_jobs = page
            .jobs
            .into_iter()
            .map(PlatformBackupJobRecord::from_wire)
            .collect::<Result<Vec<_>, _>>()?;
        jobs.extend(page_jobs);
    }
    Ok(jobs)
}

