fn support_command_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::Aborted => "conflict".into(),
        tonic::Code::InvalidArgument | tonic::Code::FailedPrecondition => {
            "support_command_rejected".into()
        }
        _ => "support_command_failed".into(),
    }
}

#[cfg(target_arch = "wasm32")]
async fn execute_support_command(
    input: SupportCommandInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<SupportCommandReceipt, String> {
    let channel = tonic_web_wasm_client::Client::new(GRPC_ENDPOINT.to_string());
    let mut client = SupportServiceClient::new(channel);
    match input {
        input @ SupportCommandInput::CreateTicket { .. } => {
            let (mut request, correlation_id) =
                support_ticket_request(&input, &principal_ref, &session_id)?;
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .create_ticket(request)
                .await
                .map_err(support_command_rpc_error)?
                .into_inner();
            support_ticket_receipt(response.ticket, correlation_id, 1)
        }
        input @ SupportCommandInput::TransitionTicket { .. } => {
            let expected_version = match &input {
                SupportCommandInput::TransitionTicket {
                    expected_version, ..
                } => support_expected_version(expected_version, "ticket version")?,
                _ => unreachable!(),
            };
            let (mut request, correlation_id) =
                support_ticket_transition_request(&input, &principal_ref, &session_id)?;
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .update_ticket(request)
                .await
                .map_err(support_command_rpc_error)?
                .into_inner();
            support_ticket_receipt(
                response.ticket,
                correlation_id,
                support_next_version(expected_version, "ticket version")?,
            )
        }
        input @ SupportCommandInput::CreateIncident { .. } => {
            let (mut request, _) =
                support_incident_create_request(&input, &principal_ref, &session_id)?;
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .create_incident(request)
                .await
                .map_err(support_command_rpc_error)?
                .into_inner();
            support_incident_receipt(response.incident, response.correlation_id)
        }
        input @ SupportCommandInput::TransitionIncident { .. } => {
            let (mut request, _) =
                support_incident_transition_request(&input, &principal_ref, &session_id)?;
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .update_incident(request)
                .await
                .map_err(support_command_rpc_error)?
                .into_inner();
            support_incident_receipt(response.incident, response.correlation_id)
        }
    }
}

