fn operations_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::InvalidArgument | tonic::Code::FailedPrecondition => {
            "operations_scope_unavailable".into()
        }
        tonic::Code::NotFound => "operations_route_unavailable".into(),
        _ => "operations_read_failed".into(),
    }
}

#[cfg(target_arch = "wasm32")]
async fn fetch_operations_read(
    scope: OperationsScope,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<OperationsReadModel, String> {
    let channel = tonic_web_wasm_client::Client::new(GRPC_ENDPOINT.to_string());
    let mut client = OperationsServiceClient::new(channel);
    let summary_context = operations_query_context(&principal_ref, &session_id, &scope.holding_id)?;
    let mut summary_request = tonic::Request::new(GetOperationsSummaryRequest {
        tenant_id: scope.tenant_id.clone(),
        holding_id: scope.holding_id.clone(),
        context: Some(summary_context),
    });
    add_platform_metadata(
        &mut summary_request,
        &access_token,
        &principal_ref,
        &session_id,
    )?;
    let summary = client
        .get_operations_summary(summary_request)
        .await
        .map_err(operations_rpc_error)?
        .into_inner();

    let exceptions_context =
        operations_query_context(&principal_ref, &session_id, &scope.holding_id)?;
    let mut exceptions_request = tonic::Request::new(ListOperationsExceptionsRequest {
        tenant_id: scope.tenant_id.clone(),
        holding_id: scope.holding_id.clone(),
        page_size: 25,
        after_cursor: String::new(),
        context: Some(exceptions_context),
    });
    add_platform_metadata(
        &mut exceptions_request,
        &access_token,
        &principal_ref,
        &session_id,
    )?;
    let exceptions = client
        .list_operations_exceptions(exceptions_request)
        .await
        .map_err(operations_rpc_error)?
        .into_inner();
    let policies_context =
        operations_query_context(&principal_ref, &session_id, &scope.holding_id)?;
    let mut policies_request = tonic::Request::new(ListOperationsWorkQueuePoliciesRequest {
        tenant_id: scope.tenant_id.clone(),
        holding_id: scope.holding_id.clone(),
        page_size: 25,
        after_cursor: String::new(),
        context: Some(policies_context),
    });
    add_platform_metadata(
        &mut policies_request,
        &access_token,
        &principal_ref,
        &session_id,
    )?;
    let policies = client
        .list_operations_work_queue_policies(policies_request)
        .await
        .map_err(operations_rpc_error)?
        .into_inner();
    OperationsReadModel::from_wire(&scope, summary, exceptions, policies)
}

