fn finance_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::InvalidArgument | tonic::Code::FailedPrecondition => {
            "finance_scope_unavailable".into()
        }
        tonic::Code::NotFound => "finance_route_unavailable".into(),
        _ => "finance_read_failed".into(),
    }
}

fn finance_command_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::InvalidArgument | tonic::Code::FailedPrecondition => {
            "finance_command_rejected".into()
        }
        tonic::Code::NotFound => "finance_route_unavailable".into(),
        _ => "finance_command_failed".into(),
    }
}

fn finance_period_request(
    scope: &FinanceScope,
    input: &FinancePeriodCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<SaveFinancePeriodRequest>, String> {
    let (period_json, expected_version) = finance_period_json(scope, input)?;
    let (context, _) = finance_command_context(
        principal_ref,
        session_id,
        &scope.holding_id,
        "finance_period_save",
        &format!("console-finance-period-save-{}", Uuid::new_v4()),
        expected_version,
    )?;
    Ok(tonic::Request::new(SaveFinancePeriodRequest {
        tenant_id: scope.tenant_id.clone(),
        holding_ref: scope.holding_ref.clone(),
        period_json,
        has_expected_version: expected_version.is_some(),
        expected_version: expected_version.unwrap_or_default(),
        context: Some(context),
    }))
}

fn finance_chart_request(
    scope: &FinanceScope,
    input: &FinanceChartCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<SaveFinanceChartRequest>, String> {
    let expected_version = if input.expected_version.trim().is_empty() {
        None
    } else {
        let value = input
            .expected_version
            .trim()
            .parse::<u64>()
            .map_err(|_| "expected chart version must be a positive integer".to_string())?;
        if value == 0 {
            return Err("expected chart version must be a positive integer".into());
        }
        Some(value)
    };
    let chart_json = finance_json_text(&input.chart_json, "chart JSON", 2 * 1024 * 1024)?;
    let mut chart: serde_json::Value = serde_json::from_str(&chart_json)
        .map_err(|_| "chart JSON must be a JSON object".to_string())?;
    let chart_object = chart
        .as_object_mut()
        .ok_or_else(|| "chart JSON must be a JSON object".to_string())?;
    let (context, _) = finance_command_context(
        principal_ref,
        session_id,
        &scope.holding_id,
        "finance_chart_save",
        &format!("console-finance-chart-save-{}", Uuid::new_v4()),
        expected_version,
    )?;
    chart_object.insert(
        "last_command".into(),
        serde_json::json!({
            "command_id": context.command_id,
            "idempotency_key": context.idempotency_key,
            "actor_ref": principal_ref,
            "correlation_id": context.correlation_id,
        }),
    );
    let chart_json = serde_json::to_vec(&chart)
        .map_err(|_| "Finance chart payload could not be encoded".to_string())?;
    Ok(tonic::Request::new(SaveFinanceChartRequest {
        tenant_id: scope.tenant_id.clone(),
        holding_ref: scope.holding_ref.clone(),
        chart_json,
        has_expected_version: expected_version.is_some(),
        expected_version: expected_version.unwrap_or_default(),
        context: Some(context),
    }))
}

fn finance_close_request(
    scope: &FinanceScope,
    input: &FinanceCloseCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<SaveFinanceCloseReviewRequest>, String> {
    let period_json = finance_json_text(&input.period_json, "period JSON", 256 * 1024)?;
    let status = finance_command_text(&input.status, "close status", 32)?;
    let context_field = match status.as_str() {
        "open" => "opened_context",
        "review" => "reviewed_context",
        "closed" => "closed_context",
        _ => return Err("close status must be open, review, or closed".into()),
    };
    let expected_version = if input.expected_version.trim().is_empty() {
        None
    } else {
        let value = input
            .expected_version
            .trim()
            .parse::<u64>()
            .map_err(|_| "expected close version must be a positive integer".to_string())?;
        if value == 0 {
            return Err("expected close version must be a positive integer".into());
        }
        Some(value)
    };
    let review_json = finance_json_text(&input.review_json, "close review JSON", 2 * 1024 * 1024)?;
    let mut review: serde_json::Value = serde_json::from_str(&review_json)
        .map_err(|_| "close review JSON must be a JSON object".to_string())?;
    let review_object = review
        .as_object_mut()
        .ok_or_else(|| "close review JSON must be a JSON object".to_string())?;
    let (context, domain_context) = finance_command_context(
        principal_ref,
        session_id,
        &scope.holding_id,
        "finance_close_review_save",
        &format!("console-finance-close-{}", Uuid::new_v4()),
        expected_version,
    )?;
    review_object.insert("status".into(), serde_json::Value::String(status));
    review_object.insert(
        context_field.into(),
        serde_json::to_value(domain_context)
            .map_err(|_| "Finance close context could not be encoded".to_string())?,
    );
    let review_json = serde_json::to_vec(&review)
        .map_err(|_| "Finance close review payload could not be encoded".to_string())?;
    Ok(tonic::Request::new(SaveFinanceCloseReviewRequest {
        tenant_id: scope.tenant_id.clone(),
        holding_ref: scope.holding_ref.clone(),
        period_json: period_json.into_bytes(),
        review_json,
        has_expected_version: expected_version.is_some(),
        expected_version: expected_version.unwrap_or_default(),
        context: Some(context),
    }))
}

fn finance_journal_request(
    scope: &FinanceScope,
    input: &FinanceJournalCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<PostFinanceJournalRequest>, String> {
    let chart_json = finance_json_text(&input.chart_json, "chart JSON", 2 * 1024 * 1024)?;
    let chart_json = chart_json.into_bytes();
    let (period_json, _) = finance_period_json(scope, &input.period)?;
    let journal_id = finance_command_uuid(&input.journal_id, "journal ID")?;
    let company_id = finance_command_uuid(&input.period.company_id, "company ID")?;
    let period_id = finance_command_uuid(&input.period.period_id, "period ID")?;
    let entry_date = finance_command_date(&input.entry_date, "journal entry date")?;
    let description = finance_command_text(&input.description, "journal description", 1_024)?;
    let debit_account_id = finance_command_uuid(&input.debit_account_id, "debit account ID")?;
    let credit_account_id = finance_command_uuid(&input.credit_account_id, "credit account ID")?;
    if debit_account_id == credit_account_id {
        return Err("debit and credit account IDs must be different".into());
    }
    let amount_minor = input
        .amount_minor
        .trim()
        .parse::<i64>()
        .map_err(|_| "journal amount must be a positive integer in minor units".to_string())?;
    if amount_minor <= 0 {
        return Err("journal amount must be a positive integer in minor units".into());
    }
    let (context, domain_context) = finance_command_context(
        principal_ref,
        session_id,
        &scope.holding_id,
        "finance_journal_post",
        &format!("console-finance-journal-post-{}", journal_id),
        None,
    )?;
    let journal_json = serde_json::to_vec(&serde_json::json!({
        "id": journal_id,
        "holding_id": scope.holding_id,
        "company_id": company_id,
        "period_id": period_id,
        "entry_date": entry_date,
        "description": description,
        "lines": [
            {
                "id": Uuid::new_v4(),
                "account_id": debit_account_id,
                "memo": null,
                "debit_minor": amount_minor,
                "credit_minor": 0,
            },
            {
                "id": Uuid::new_v4(),
                "account_id": credit_account_id,
                "memo": null,
                "debit_minor": 0,
                "credit_minor": amount_minor,
            },
        ],
        "context": domain_context,
    }))
    .map_err(|_| "Finance journal payload could not be encoded".to_string())?;
    Ok(tonic::Request::new(PostFinanceJournalRequest {
        tenant_id: scope.tenant_id.clone(),
        holding_ref: scope.holding_ref.clone(),
        chart_json,
        period_json,
        journal_json,
        context: Some(context),
    }))
}

