fn finance_expected_version(value: &str, field: &str) -> Result<Option<u64>, String> {
    if value.trim().is_empty() {
        return Ok(None);
    }
    let version = value
        .trim()
        .parse::<u64>()
        .map_err(|_| format!("{field} must be a positive integer"))?;
    if version == 0 {
        return Err(format!("{field} must be a positive integer"));
    }
    Ok(Some(version))
}

fn finance_json_object(
    value: &str,
    field: &str,
    max_len: usize,
) -> Result<serde_json::Value, String> {
    let value = finance_json_text(value, field, max_len)?;
    let parsed: serde_json::Value =
        serde_json::from_str(&value).map_err(|_| format!("{field} must be a JSON object"))?;
    if !parsed.is_object() {
        return Err(format!("{field} must be a JSON object"));
    }
    Ok(parsed)
}

fn finance_json_with_context(
    value: &str,
    field: &str,
    max_len: usize,
    domain_context: &DomainCommandContext,
) -> Result<Vec<u8>, String> {
    let mut parsed = finance_json_object(value, field, max_len)?;
    parsed
        .as_object_mut()
        .expect("finance_json_object guarantees an object")
        .insert(
            "context".into(),
            serde_json::to_value(domain_context)
                .map_err(|_| format!("{field} context could not be encoded"))?,
        );
    serde_json::to_vec(&parsed).map_err(|_| format!("{field} could not be encoded"))
}

fn finance_allocation_record_kind(
    record: &serde_json::Value,
    field: &str,
) -> Result<&'static str, String> {
    if field == "allocation" {
        return Ok("allocation");
    }
    let kind = record
        .get("kind")
        .and_then(serde_json::Value::as_str)
        .ok_or_else(|| format!("{field} must include a typed kind"))?;
    match kind {
        "vendor_payment" => Ok("vendor_payment"),
        "customer_payment" => Ok("customer_payment"),
        "payable" => Ok("payable_invoice"),
        "receivable" => Ok("receivable_invoice"),
        _ => Err(format!(
            "{field} kind is not supported by allocation batching"
        )),
    }
}

fn finance_bind_allocation_record(
    record: &mut serde_json::Value,
    field: &str,
    context: &DomainCommandContext,
) -> Result<(), String> {
    let kind = finance_allocation_record_kind(record, field)?;
    let metadata = record
        .get_mut("metadata")
        .and_then(serde_json::Value::as_object_mut)
        .ok_or_else(|| format!("{field} must include metadata"))?;
    metadata.insert(
        "command_id".into(),
        serde_json::Value::String(context.command_id.to_string()),
    );
    metadata.insert(
        "idempotency_key".into(),
        serde_json::Value::String(format!(
            "finance-subledger/{kind}/{}",
            context.idempotency_key
        )),
    );
    metadata.insert(
        "context".into(),
        serde_json::to_value(context)
            .map_err(|_| format!("{field} command context could not be encoded"))?,
    );
    Ok(())
}

fn finance_allocation_batch_request(
    scope: &FinanceScope,
    input: &FinanceAllocationBatchCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<SaveFinanceAllocationBatchRequest>, String> {
    let expected_version =
        finance_expected_version(&input.expected_version, "expected payment version")?
            .ok_or_else(|| "allocation batches require an expected payment version".to_string())?;
    let mut batch =
        finance_json_object(&input.batch_json, "allocation batch JSON", 2 * 1024 * 1024)?;
    let context = finance_command_context(
        principal_ref,
        session_id,
        &scope.holding_id,
        "finance_allocation_batch_save",
        &format!("console-finance-allocation-batch-{}", Uuid::new_v4()),
        Some(expected_version),
    )?;
    let domain_context = context.1;
    let batch_object = batch
        .as_object_mut()
        .expect("finance_json_object guarantees an object");
    let payment = batch_object
        .get_mut("payment")
        .ok_or_else(|| "allocation batch must include payment".to_string())?;
    finance_bind_allocation_record(payment, "payment", &domain_context)?;
    let invoices = batch_object
        .get_mut("invoices")
        .and_then(serde_json::Value::as_array_mut)
        .ok_or_else(|| "allocation batch must include invoices".to_string())?;
    if invoices.is_empty() {
        return Err("allocation batch must include at least one invoice".into());
    }
    for invoice in invoices {
        finance_bind_allocation_record(invoice, "invoice", &domain_context)?;
    }
    let allocations = batch_object
        .get_mut("allocations")
        .and_then(serde_json::Value::as_array_mut)
        .ok_or_else(|| "allocation batch must include allocations".to_string())?;
    if allocations.is_empty() {
        return Err("allocation batch must include at least one allocation".into());
    }
    for allocation in allocations {
        finance_bind_allocation_record(allocation, "allocation", &domain_context)?;
    }
    let batch_json = serde_json::to_vec(&batch)
        .map_err(|_| "Finance allocation batch could not be encoded".to_string())?;
    Ok(tonic::Request::new(SaveFinanceAllocationBatchRequest {
        tenant_id: scope.tenant_id.clone(),
        holding_ref: scope.holding_ref.clone(),
        batch_json,
        context: Some(context.0),
    }))
}

