fn finance_period_receipt(
    response: SaveFinancePeriodResponse,
) -> Result<FinancePeriodCommandReceipt, String> {
    let correlation_id = bounded_finance_value(
        &response.correlation_id,
        "Finance period correlation ID",
        false,
        128,
    )?;
    let receipt = response
        .receipt
        .ok_or_else(|| "Finance period command omitted its receipt".to_string())?;
    let period_id = finance_command_uuid(&receipt.period_id, "Finance period receipt ID")?;
    if receipt.aggregate_type != "finance_period" || receipt.version == 0 {
        return Err("Finance period receipt failed its aggregate/version contract".into());
    }
    Ok(FinancePeriodCommandReceipt {
        period_id,
        version: receipt.version,
        replayed: receipt.replayed,
        correlation_id,
    })
}

