fn finance_allocation_batch_receipt(
    response: erpx_proto::platform::SaveFinanceAllocationBatchResponse,
) -> Result<FinanceAllocationBatchCommandReceipt, String> {
    let correlation_id = bounded_finance_value(
        &response.correlation_id,
        "Finance allocation batch correlation ID",
        false,
        128,
    )?;
    let payment = response
        .payment
        .ok_or_else(|| "Finance allocation batch omitted its payment receipt".to_string())?;
    if response.invoices.is_empty() || response.allocations.is_empty() {
        return Err("Finance allocation batch omitted invoice or allocation receipts".into());
    }
    let mut payment = finance_allocation_receipt_item(payment, "payment")?;
    payment.correlation_id = correlation_id.clone();
    let invoices = response
        .invoices
        .into_iter()
        .enumerate()
        .map(|(index, receipt)| {
            let mut receipt =
                finance_allocation_receipt_item(receipt, &format!("invoice {index}"))?;
            receipt.correlation_id = correlation_id.clone();
            Ok(receipt)
        })
        .collect::<Result<Vec<_>, String>>()?;
    let allocations = response
        .allocations
        .into_iter()
        .enumerate()
        .map(|(index, receipt)| {
            let mut receipt =
                finance_allocation_receipt_item(receipt, &format!("allocation {index}"))?;
            receipt.correlation_id = correlation_id.clone();
            Ok(receipt)
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(FinanceAllocationBatchCommandReceipt {
        payment,
        invoices,
        allocations,
        replayed: response.replayed,
        correlation_id,
    })
}

fn finance_bank_account_receipt(
    response: RegisterBankAccountResponse,
) -> Result<FinanceBankAccountCommandReceipt, String> {
    let correlation_id = bounded_finance_value(
        &response.correlation_id,
        "Finance bank account correlation ID",
        false,
        128,
    )?;
    let receipt = response
        .receipt
        .ok_or_else(|| "Finance bank account command omitted its receipt".to_string())?;
    let account_id = finance_command_uuid(&receipt.account_id, "Finance bank account receipt ID")?;
    if receipt.version == 0 {
        return Err("Finance bank account receipt version must be positive".into());
    }
    Ok(FinanceBankAccountCommandReceipt {
        account_id,
        version: receipt.version,
        replayed: receipt.replayed,
        correlation_id,
    })
}

