macro_rules! define_finance_bank_client {
    (
        $name:ident,
        $input:ty,
        $request_builder:ident,
        $method:ident,
        $receipt_parser:ident,
        $receipt_type:ty
    ) => {
        #[cfg(target_arch = "wasm32")]
        async fn $name(
            scope: FinanceScope,
            input: $input,
            access_token: String,
            principal_ref: String,
            session_id: String,
        ) -> Result<$receipt_type, String> {
            let channel = tonic_web_wasm_client::Client::new(GRPC_ENDPOINT.to_string());
            let mut client = FinanceServiceClient::new(channel);
            let mut request = $request_builder(&scope, &input, &principal_ref, &session_id)?;
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .$method(request)
                .await
                .map_err(finance_command_rpc_error)?
                .into_inner();
            $receipt_parser(response)
        }

        #[cfg(not(target_arch = "wasm32"))]
        async fn $name(
            scope: FinanceScope,
            input: $input,
            access_token: String,
            principal_ref: String,
            session_id: String,
        ) -> Result<$receipt_type, String> {
            let channel = tonic::transport::Endpoint::from_static(GRPC_ENDPOINT)
                .connect()
                .await
                .map_err(|_| "offline".to_string())?;
            let mut client = FinanceServiceClient::new(channel);
            let mut request = $request_builder(&scope, &input, &principal_ref, &session_id)?;
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .$method(request)
                .await
                .map_err(finance_command_rpc_error)?
                .into_inner();
            $receipt_parser(response)
        }
    };
}

