fn finance_consolidation_chart_payloads(value: &str) -> Result<Vec<Vec<u8>>, String> {
    let charts = value
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(|line| line.as_bytes().to_vec())
        .collect::<Vec<_>>();
    if charts.is_empty() || charts.len() > 1_000 {
        return Err("enter one compact authoritative chart JSON object per line".into());
    }
    if charts.iter().any(|chart| chart.len() > 2 * 1024 * 1024) {
        return Err("a Finance chart JSON object exceeds the server bound".into());
    }
    Ok(charts)
}

