fn hr_employee_transition_request(
    scope: &HrEmployeeScope,
    employee_id: &str,
    transition: &str,
    terminated_on: &str,
    expected_version: u64,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<TransitionHrEmployeeRequest>, String> {
    let employee_id = bounded_finance_uuid(employee_id, "employee")
        .map_err(|_| "HR employee ID was not a UUID".to_string())?;
    if transition.trim().is_empty() || transition.len() > 64 || expected_version == 0 {
        return Err("HR employee transition input is outside its bound".into());
    }
    let terminated_on = terminated_on.trim();
    if !terminated_on.is_empty()
        && (terminated_on.len() != 10
            || terminated_on.as_bytes().get(4) != Some(&b'-')
            || terminated_on.as_bytes().get(7) != Some(&b'-'))
    {
        return Err("HR termination date must be YYYY-MM-DD".into());
    }
    let context = operations_command_context(
        principal_ref,
        session_id,
        &scope.finance.holding_id,
        "hr_employee_lifecycle_transition",
        &format!("hr-employee-transition:{employee_id}:{expected_version}:{transition}"),
        expected_version,
    )?;
    Ok(tonic::Request::new(TransitionHrEmployeeRequest {
        tenant_id: scope.finance.tenant_id.clone(),
        holding_ref: scope.finance.holding_ref.clone(),
        employee_id,
        transition: transition.trim().to_owned(),
        expected_version,
        terminated_on: terminated_on.to_owned(),
        context: Some(context),
    }))
}

