fn legal_receipt(
    correlation_id: &str,
    receipt: Option<erpx_proto::platform::LegalWriteReceipt>,
) -> Result<LegalCommandReceipt, String> {
    let correlation_id =
        bounded_finance_value(correlation_id, "Legal command correlation ID", false, 128)?;
    let receipt = receipt.ok_or_else(|| "Legal command omitted its receipt".to_string())?;
    let aggregate_type = finance_command_text(&receipt.aggregate_type, "Legal aggregate type", 64)?;
    let aggregate_id = finance_command_uuid(&receipt.aggregate_id, "Legal aggregate ID")?;
    let idempotency_key =
        finance_command_text(&receipt.idempotency_key, "Legal idempotency key", 256)?;
    let event_id = finance_command_uuid(&receipt.event_id, "Legal event ID")?;
    if receipt.version == 0 {
        return Err("Legal receipt version must be positive".into());
    }
    Ok(LegalCommandReceipt {
        aggregate_type,
        aggregate_id,
        version: receipt.version,
        idempotency_key,
        event_id,
        replayed: receipt.replayed,
        correlation_id,
    })
}

macro_rules! define_legal_client {
    (
        $name:ident,
        $input:ty,
        $request_builder:ident,
        $method:ident,
        $response:ident
    ) => {
        #[cfg(target_arch = "wasm32")]
        async fn $name(
            scope: LegalContractScope,
            input: $input,
            access_token: String,
            principal_ref: String,
            session_id: String,
        ) -> Result<LegalCommandReceipt, String> {
            let channel = tonic_web_wasm_client::Client::new(GRPC_ENDPOINT.to_string());
            let mut client = LegalServiceClient::new(channel);
            let mut request = $request_builder(&scope, &input, &principal_ref, &session_id)?;
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response: $response = client
                .$method(request)
                .await
                .map_err(legal_command_rpc_error)?
                .into_inner();
            legal_receipt(&response.correlation_id, response.receipt)
        }

        #[cfg(not(target_arch = "wasm32"))]
        async fn $name(
            scope: LegalContractScope,
            input: $input,
            access_token: String,
            principal_ref: String,
            session_id: String,
        ) -> Result<LegalCommandReceipt, String> {
            let channel = tonic::transport::Endpoint::from_static(GRPC_ENDPOINT)
                .connect()
                .await
                .map_err(|_| "offline".to_string())?;
            let mut client = LegalServiceClient::new(channel);
            let mut request = $request_builder(&scope, &input, &principal_ref, &session_id)?;
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response: $response = client
                .$method(request)
                .await
                .map_err(legal_command_rpc_error)?
                .into_inner();
            legal_receipt(&response.correlation_id, response.receipt)
        }
    };
}

