fn pos_command_context(
    scope: &PosSaleScope,
    principal_ref: &str,
    session_id: &str,
    idempotency_key: &str,
    expected_version: Option<u64>,
) -> Result<CommandContext, String> {
    let holding_id = Uuid::parse_str(&scope.finance.holding_id)
        .map_err(|_| "the POS holding scope must be a UUID".to_string())?;
    let company_id = Uuid::parse_str(&scope.company_id)
        .map_err(|_| "the POS company scope must be a UUID".to_string())?;
    let correlation_id = Uuid::new_v4().to_string();
    let tenant_scope = if scope.branch_id.is_empty() {
        tenant_scope::Scope::Company(CompanyScope {
            holding_id: holding_id.to_string(),
            company_id: company_id.to_string(),
        })
    } else {
        let branch_id = Uuid::parse_str(&scope.branch_id)
            .map_err(|_| "the POS branch scope must be a UUID".to_string())?;
        tenant_scope::Scope::Branch(BranchScope {
            holding_id: holding_id.to_string(),
            company_id: company_id.to_string(),
            branch_id: branch_id.to_string(),
        })
    };
    Ok(CommandContext {
        contract_version: u32::from(CONTRACT_VERSION),
        command_id: Uuid::new_v4().to_string(),
        idempotency_key: idempotency_key.to_owned(),
        correlation_id: correlation_id.clone(),
        causation_id: String::new(),
        actor: Some(ActorAttribution {
            principal_ref: principal_ref.to_owned(),
            kind: ActorKind::PlatformUser as i32,
            session_id: session_id.to_owned(),
            represented_principal_ref: String::new(),
            support_capability_id: String::new(),
        }),
        tenant_scope: Some(TenantScope {
            scope: Some(tenant_scope),
        }),
        audit: Some(AuditContext {
            purpose: "pos_sale_save".into(),
            customer_visible: false,
            module: "pos".into(),
            correlation_id,
        }),
        expected_aggregate_version: expected_version.unwrap_or_default(),
        subscription_id: String::new(),
        mfa_code: String::new(),
    })
}

fn pos_save_request(
    scope: &PosSaleScope,
    input: &PosSaleCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<SavePosSaleRequest>, String> {
    let expected_version =
        finance_expected_version(&input.expected_version, "expected POS sale version")?;
    let mut sale = finance_json_object(&input.sale_json, "POS sale JSON", 512 * 1024)?;
    let idempotency_key = format!("console-pos-sale-{}", Uuid::new_v4());
    let context = pos_command_context(
        scope,
        principal_ref,
        session_id,
        &idempotency_key,
        expected_version,
    )?;
    let sale_object = sale
        .as_object_mut()
        .expect("finance_json_object guarantees an object");
    sale_object.insert(
        "command_id".into(),
        serde_json::Value::String(context.command_id.clone()),
    );
    sale_object.insert(
        "idempotency_key".into(),
        serde_json::Value::String(format!("pos/sale/{idempotency_key}")),
    );
    let sale_json =
        serde_json::to_vec(&sale).map_err(|_| "POS sale JSON could not be encoded".to_string())?;
    Ok(tonic::Request::new(SavePosSaleRequest {
        tenant_id: scope.finance.tenant_id.clone(),
        holding_ref: scope.finance.holding_ref.clone(),
        sale_json,
        has_expected_version: expected_version.is_some(),
        expected_version: expected_version.unwrap_or_default(),
        context: Some(context),
    }))
}

fn pos_save_receipt(response: SavePosSaleResponse) -> Result<PosSaleCommandReceipt, String> {
    let correlation_id = bounded_finance_value(
        &response.correlation_id,
        "POS sale correlation ID",
        false,
        128,
    )?;
    let aggregate_type =
        finance_command_text(&response.aggregate_type, "POS sale aggregate type", 64)?;
    if aggregate_type != "pos_sale" {
        return Err("POS sale receipt aggregate type was invalid".into());
    }
    let aggregate_id = finance_command_uuid(&response.aggregate_id, "POS sale aggregate ID")?;
    let idempotency_key =
        finance_command_text(&response.idempotency_key, "POS sale idempotency key", 256)?;
    if response.version == 0 {
        return Err("POS sale receipt version must be positive".into());
    }
    Ok(PosSaleCommandReceipt {
        aggregate_type,
        aggregate_id,
        version: response.version,
        idempotency_key,
        replayed: response.replayed,
        correlation_id,
    })
}

