fn scm_transition_request(
    scope: &ProductAggregateScope,
    transition: &str,
    expected_version: u64,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<TransitionScmAggregateRequest>, String> {
    if transition.trim().is_empty() || transition.len() > 64 || expected_version == 0 {
        return Err("SCM transition input is outside its bound".into());
    }
    let context = operations_command_context(
        principal_ref,
        session_id,
        &scope.finance.holding_id,
        "scm_lifecycle_transition",
        &format!(
            "scm-transition:{}:{}:{}",
            scope.aggregate_id, expected_version, transition
        ),
        expected_version,
    )?;
    Ok(tonic::Request::new(TransitionScmAggregateRequest {
        tenant_id: scope.finance.tenant_id.clone(),
        holding_ref: scope.finance.holding_ref.clone(),
        aggregate_type: scope.aggregate_type.clone(),
        aggregate_id: scope.aggregate_id.clone(),
        transition: transition.trim().to_owned(),
        expected_version,
        context: Some(context),
    }))
}

fn scm_save_request(
    scope: &ProductAggregateScope,
    input: &ScmCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<SaveScmAggregateRequest>, String> {
    let expected_version = if input.expected_version.trim().is_empty() {
        None
    } else {
        let value = input
            .expected_version
            .trim()
            .parse::<u64>()
            .map_err(|_| "expected SCM version must be a positive integer".to_string())?;
        if value == 0 {
            return Err("expected SCM version must be a positive integer".into());
        }
        Some(value)
    };
    let context = operations_command_context(
        principal_ref,
        session_id,
        &scope.finance.holding_id,
        "scm_aggregate_save",
        &format!("scm-save-{}", Uuid::new_v4()),
        expected_version.unwrap_or_default(),
    )?;
    let aggregate_json = bind_product_aggregate_command_json(
        &input.aggregate_json,
        "SCM aggregate JSON",
        "scm",
        &context,
    )?;
    Ok(tonic::Request::new(SaveScmAggregateRequest {
        tenant_id: scope.finance.tenant_id.clone(),
        holding_ref: scope.finance.holding_ref.clone(),
        aggregate_json: aggregate_json.into_bytes(),
        has_expected_version: expected_version.is_some(),
        expected_version: expected_version.unwrap_or_default(),
        context: Some(context),
    }))
}

fn asset_save_request(
    scope: &ProductAggregateScope,
    input: &AssetCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<SaveAssetMaintenanceAggregateRequest>, String> {
    let aggregate_json = finance_json_text(
        &input.aggregate_json,
        "Asset/Maintenance aggregate JSON",
        1_048_576,
    )?;
    let _: serde_json::Value = serde_json::from_str(&aggregate_json)
        .map_err(|_| "Asset/Maintenance aggregate JSON must be valid JSON".to_string())?;
    let expected_version = finance_expected_version(
        &input.expected_version,
        "expected Asset/Maintenance version",
    )?;
    let context = operations_command_context(
        principal_ref,
        session_id,
        &scope.finance.holding_id,
        "asset_maintenance_aggregate_save",
        &format!("asset-maintenance-save-{}", Uuid::new_v4()),
        expected_version.unwrap_or_default(),
    )?;
    Ok(tonic::Request::new(SaveAssetMaintenanceAggregateRequest {
        tenant_id: scope.finance.tenant_id.clone(),
        holding_ref: scope.finance.holding_ref.clone(),
        aggregate_json: aggregate_json.into_bytes(),
        idempotency_key: context.idempotency_key.clone(),
        has_expected_version: expected_version.is_some(),
        expected_version: expected_version.unwrap_or_default(),
        context: Some(context),
    }))
}

fn asset_save_receipt(
    response: SaveAssetMaintenanceAggregateResponse,
) -> Result<AssetCommandReceipt, String> {
    let correlation_id = bounded_finance_value(
        &response.correlation_id,
        "Asset/Maintenance command correlation ID",
        false,
        128,
    )?;
    let receipt = response
        .receipt
        .ok_or_else(|| "Asset/Maintenance command omitted its receipt".to_string())?;
    let aggregate_type = finance_command_text(
        &receipt.aggregate_type,
        "Asset/Maintenance aggregate type",
        128,
    )?;
    let aggregate_id =
        finance_command_uuid(&receipt.aggregate_id, "Asset/Maintenance aggregate ID")?;
    if receipt.version == 0 {
        return Err("Asset/Maintenance receipt version must be positive".into());
    }
    Ok(AssetCommandReceipt {
        aggregate_type,
        aggregate_id,
        version: receipt.version,
        replayed: receipt.replayed,
        correlation_id,
    })
}

