fn scm_save_receipt(response: SaveScmAggregateResponse) -> Result<ScmCommandReceipt, String> {
    let correlation_id = bounded_finance_value(
        &response.correlation_id,
        "SCM command correlation ID",
        false,
        128,
    )?;
    let receipt = response
        .receipt
        .ok_or_else(|| "SCM command omitted its receipt".to_string())?;
    let aggregate_type = finance_command_text(&receipt.aggregate_type, "SCM aggregate type", 128)?;
    let aggregate_id = finance_command_uuid(&receipt.aggregate_id, "SCM aggregate ID")?;
    if receipt.version == 0 {
        return Err("SCM receipt version must be positive".into());
    }
    Ok(ScmCommandReceipt {
        aggregate_type,
        aggregate_id,
        version: receipt.version,
        replayed: receipt.replayed,
        correlation_id,
    })
}

