    let on_support_command = move |input: SupportCommandInput| {
        let (access_token, principal_ref, session_id) = {
            let controller = auth.read();
            (
                controller
                    .access_token()
                    .map(|token| token.as_str().to_owned()),
                controller
                    .metadata()
                    .and_then(|metadata| metadata.principal_label.clone()),
                controller
                    .session_id()
                    .map(|session| session.as_str().to_owned()),
            )
        };
        let (Some(access_token), Some(principal_ref), Some(session_id)) =
            (access_token, principal_ref, session_id)
        else {
            support_command_message.set(Some(
                "Sign in with an eligible support or incident role before issuing a command."
                    .into(),
            ));
            return;
        };
        support_command_busy.set(true);
        support_command_message.set(None);
        let mut busy_for_task = support_command_busy;
        let mut message_for_task = support_command_message;
        let mut incidents_for_task = incidents;
        let mut tickets_for_task = support_tickets;
        spawn(async move {
            let result =
                execute_support_command(input, access_token, principal_ref, session_id).await;
            busy_for_task.set(false);
            message_for_task.set(Some(match result {
                Ok(receipt) => {
                    incidents_for_task.restart();
                    tickets_for_task.restart();
                    format!(
                        "{} {} is now {} at version {} · correlation {}.",
                        receipt.resource,
                        receipt.resource_id,
                        receipt.status,
                        receipt.version,
                        receipt.correlation_id
                    )
                }
                Err(error) => format!("Support command failed: {error}."),
            }));
        });
    };

