    // CRM reads require the explicit holding/company/branch scope entered in the route surface.
    // Platform scope is rejected by the server and is never converted into a tenant query here.
    let mut crm_scope = use_signal(|| None::<CrmReadScope>);
    let mut crm_after_id = use_signal(|| None::<String>);
    let mut crm_command_busy = use_signal(|| false);
    let mut crm_command_message = use_signal(|| None::<String>);
    let crm_rows = use_resource(move || {
        let route = *marketing_crm_route.read();
        let surface = route.and_then(crm_surface_for_route);
        let scope = crm_scope.read().clone();
        let after_id = crm_after_id.read().clone();
        let (access_token, principal_ref, session_id) = {
            let controller = auth.read();
            (
                controller
                    .access_token()
                    .map(|token| token.as_str().to_owned()),
                controller
                    .metadata()
                    .and_then(|metadata| metadata.principal_label.clone()),
                controller
                    .session_id()
                    .map(|session| session.as_str().to_owned()),
            )
        };
        async move {
            match (surface, scope, access_token, principal_ref, session_id) {
                (None, _, _, _, _) => Err(CrmReadError::RouteUnavailable),
                (Some(_), None, _, _, _) => Err(CrmReadError::ScopeUnavailable),
                (Some(_), Some(_), None, _, _)
                | (Some(_), Some(_), _, None, _)
                | (Some(_), Some(_), _, _, None) => Err(CrmReadError::Denied),
                (
                    Some(surface),
                    Some(scope),
                    Some(access_token),
                    Some(principal_ref),
                    Some(session_id),
                ) => {
                    fetch_crm_rows(
                        scope,
                        surface,
                        access_token,
                        principal_ref,
                        session_id,
                        after_id,
                    )
                    .await
                }
            }
        }
    });

    let mut marketing_content_after = use_signal(|| None::<String>);
    let marketing_content_rows = use_resource(move || {
        let route = *marketing_crm_route.read();
        let scope = crm_scope.read().clone();
        let after_cursor = marketing_content_after.read().clone();
        let (access_token, principal_ref, session_id) = {
            let controller = auth.read();
            (
                controller
                    .access_token()
                    .map(|token| token.as_str().to_owned()),
                controller
                    .metadata()
                    .and_then(|metadata| metadata.principal_label.clone()),
                controller
                    .session_id()
                    .map(|session| session.as_str().to_owned()),
            )
        };
        async move {
            let Some(route) = route.filter(|route| {
                matches!(
                    route,
                    RouteId::MarketingContent
                        | RouteId::MarketingTemplates
                        | RouteId::MarketingForms
                        | RouteId::MarketingDomains
                )
            }) else {
                return Err(CrmReadError::RouteUnavailable);
            };
            let Some(scope) = scope else {
                return Err(CrmReadError::ScopeUnavailable);
            };
            let (Some(access_token), Some(principal_ref), Some(session_id)) =
                (access_token, principal_ref, session_id)
            else {
                return Err(CrmReadError::Denied);
            };
            fetch_marketing_content_rows(
                scope,
                route,
                access_token,
                principal_ref,
                session_id,
                after_cursor,
            )
            .await
        }
    });

