    let on_billing_command = move |input: EntitlementCommandInput| {
        let Some(scope) = billing_scope.read().clone() else {
            billing_command_message.set(Some(
                "Load an explicit customer, subscription, holding, module, and company scope first."
                    .into(),
            ));
            return;
        };
        let (access_token, principal_ref, session_id) = {
            let controller = auth.read();
            (
                controller
                    .access_token()
                    .map(|token| token.as_str().to_owned()),
                controller
                    .metadata()
                    .and_then(|metadata| metadata.principal_label.clone()),
                controller
                    .session_id()
                    .map(|session| session.as_str().to_owned()),
            )
        };
        let (Some(access_token), Some(principal_ref), Some(session_id)) =
            (access_token, principal_ref, session_id)
        else {
            billing_command_message
                .set(Some("Sign in before issuing a commercial command.".into()));
            return;
        };
        billing_command_busy.set(true);
        billing_command_message.set(None);
        let mut busy_for_task = billing_command_busy;
        let mut message_for_task = billing_command_message;
        let mut probe_for_task = entitlement_probe;
        spawn(async move {
            let result =
                execute_entitlement_command(scope, input, access_token, principal_ref, session_id)
                    .await;
            busy_for_task.set(false);
            message_for_task.set(Some(match result {
                Ok(receipt) => {
                    probe_for_task.restart();
                    format!(
                        "{} {} committed at version {}{} · correlation {}.",
                        receipt.aggregate_type,
                        receipt.aggregate_id,
                        receipt.version,
                        if receipt.replayed {
                            " (idempotent replay)"
                        } else {
                            ""
                        },
                        receipt.correlation_id
                    )
                }
                Err(error) => format!("Commercial entitlement command failed: {error}."),
            }));
        });
    };

