    let mut sales_command_busy = use_signal(|| false);
    let mut sales_command_message = use_signal(|| None::<String>);
    let on_sales_transition = move |transition: String| {
        let scope = sales_scope.read().clone();
        let expected_version = sales_read
            .read()
            .as_ref()
            .and_then(|result| result.as_ref().ok())
            .and_then(|read| read.as_ref())
            .map(|read| read.source_version);
        let (access_token, principal_ref, session_id) = {
            let controller = auth.read();
            (
                controller
                    .access_token()
                    .map(|token| token.as_str().to_owned()),
                controller
                    .metadata()
                    .and_then(|metadata| metadata.principal_label.clone()),
                controller
                    .session_id()
                    .map(|session| session.as_str().to_owned()),
            )
        };
        let (
            Some(scope),
            Some(expected_version),
            Some(access_token),
            Some(principal_ref),
            Some(session_id),
        ) = (
            scope,
            expected_version,
            access_token,
            principal_ref,
            session_id,
        )
        else {
            sales_command_message.set(Some(
                "Load an authenticated Sales aggregate before requesting a lifecycle transition."
                    .into(),
            ));
            return;
        };
        sales_command_busy.set(true);
        sales_command_message.set(None);
        let mut busy_for_task = sales_command_busy;
        let mut message_for_task = sales_command_message;
        let mut read_for_task = sales_read;
        spawn(async move {
            let result = transition_sales_aggregate(
                scope,
                transition,
                expected_version,
                access_token,
                principal_ref,
                session_id,
            )
            .await;
            busy_for_task.set(false);
            message_for_task.set(Some(match result {
                Ok(receipt) => {
                    read_for_task.restart();
                    format!(
                        "Sales lifecycle transition committed at source version {}{} · correlation {}.",
                        receipt.version,
                        if receipt.replayed { " (idempotent replay)" } else { "" },
                        receipt.correlation_id
                    )
                }
                Err(error) => format!("Sales lifecycle transition failed: {error}."),
            }));
        });
    };
