#[component]
fn PlatformOperationsNavigationItem(
    definition: PlatformOperationsRouteDefinition,
    active_route: PlatformOperationsRoute,
    on_navigate: EventHandler<PlatformOperationsRoute>,
) -> Element {
    let locale = use_locale().current();
    let target = platform_operations_route_for_id(definition.id, None);
    let is_active = target.as_ref().is_some_and(|route| *route == active_route);
    let is_disabled = target.is_none();
    let title = if is_disabled {
        "An authorized opaque tenant identifier is required to open this route."
    } else {
        definition.template
    };
    rsx! {
        button {
            class: if is_active { "route-tab active" } else { "route-tab" },
            r#type: "button",
            disabled: is_disabled,
            aria_current: if is_active { "page" } else { "false" },
            title,
            onclick: move |_| {
                if let Some(route) = target.clone() {
                    on_navigate.call(route);
                }
            },
            span { class: "route-tab-icon", aria_hidden: "true", "{definition.icon}" }
            "{definition.label_for(locale)}"
        }
    }
}

#[component]
fn PlatformOperationsSurface(
    route: PlatformOperationsRoute,
    on_navigate: EventHandler<PlatformOperationsRoute>,
    evidence_model: Option<PlatformOperationsModel>,
    tenants: Option<Vec<PlatformTenantRecord>>,
    tenants_loading: bool,
    tenants_error: Option<String>,
    tenant: Option<PlatformTenantRecord>,
    tenant_loading: bool,
    tenant_error: Option<String>,
    projection_statuses: Option<Vec<PlatformProjectionStatusRecord>>,
    projection_statuses_loading: bool,
    projection_statuses_error: Option<String>,
    backup_jobs: Option<Vec<PlatformBackupJobRecord>>,
    backup_jobs_loading: bool,
    backup_jobs_error: Option<String>,
    audit_entries: Option<Vec<PlatformAuditRecord>>,
    audit_loading: bool,
    audit_error: Option<String>,
    integrations: Option<Vec<PlatformIntegrationRecord>>,
    integrations_loading: bool,
    integrations_error: Option<String>,
    settings: Option<PlatformSettingsRecord>,
    settings_loading: bool,
    settings_error: Option<String>,
    role_review: Option<PlatformRoleReviewPage>,
    role_review_loading: bool,
    role_review_error: Option<String>,
    migration_statuses: Option<Vec<MigrationStatusRecord>>,
    migration_statuses_loading: bool,
    migration_statuses_error: Option<String>,
    replay_access_token: Option<String>,
    replay_principal_ref: Option<String>,
    replay_session_id: Option<String>,
) -> Element {
    let locale = use_locale().current();
    let definition = PlatformOperationsRouteRegistry::new().definition(route.id());
    let connected = match &route {
        PlatformOperationsRoute::Tenants => {
            !tenants_loading && tenants_error.is_none() && tenants.is_some()
        }
        PlatformOperationsRoute::Tenant { .. } => {
            !tenant_loading && tenant_error.is_none() && tenant.is_some()
        }
        PlatformOperationsRoute::Projections => {
            !projection_statuses_loading
                && projection_statuses_error.is_none()
                && projection_statuses.is_some()
        }
        PlatformOperationsRoute::Backups => {
            !backup_jobs_loading && backup_jobs_error.is_none() && backup_jobs.is_some()
        }
        PlatformOperationsRoute::Audit => {
            !audit_loading && audit_error.is_none() && audit_entries.is_some()
        }
        PlatformOperationsRoute::Integrations => {
            !integrations_loading && integrations_error.is_none() && integrations.is_some()
        }
        PlatformOperationsRoute::Settings => {
            !settings_loading && settings_error.is_none() && settings.is_some()
        }
        PlatformOperationsRoute::RoleReview => {
            !role_review_loading && role_review_error.is_none() && role_review.is_some()
        }
    };
    let (connection_title, connection_message) = platform_operations_connection_copy(connected);
    let state_catalog = [
        UiStateKind::Loading,
        UiStateKind::Error,
        UiStateKind::Denied,
        UiStateKind::Stale,
        UiStateKind::ReadOnly,
    ];
    rsx! {
        section { class: "detail platform-operations-surface",
            div { class: "surface-header",
                div {
                    div { class: "eyebrow", "PLATFORM OPERATIONS · {route.path()}" }
                    h2 { "{definition.label_for(locale)}" }
                    p { "{platform_operations_route_description(route.id())}" }
                }
                span { class: "route-identity", "{definition.template}" }
            }
            div { class: "audit-banner", role: "status",
                strong { "{connection_title}" }
                " · {connection_message}"
            }
            if let Some(model) = evidence_model {
                PlatformOperationsEvidenceSurface { model }
            }
            if matches!(route, PlatformOperationsRoute::Tenants) {
                PlatformTenantRouteLauncher { on_navigate }
                PlatformTenantList {
                    tenants,
                    loading: tenants_loading,
                    error: tenants_error,
                    on_navigate,
                }
            }
            if matches!(&route, PlatformOperationsRoute::Tenant { .. }) {
                PlatformTenantDetail {
                    tenant,
                    loading: tenant_loading,
                    error: tenant_error,
                }
            }
            if matches!(&route, PlatformOperationsRoute::Projections) {
                PlatformProjectionStatusList {
                    statuses: projection_statuses,
                    loading: projection_statuses_loading,
                    error: projection_statuses_error,
                }
            }
            if matches!(&route, PlatformOperationsRoute::Backups) {
                PlatformBackupJobList {
                    jobs: backup_jobs,
                    loading: backup_jobs_loading,
                    error: backup_jobs_error,
                }
            }
            if matches!(&route, PlatformOperationsRoute::Audit) {
                PlatformAuditList {
                    entries: audit_entries,
                    loading: audit_loading,
                    error: audit_error,
                }
            }
            if matches!(&route, PlatformOperationsRoute::Integrations) {
                PlatformIntegrationList {
                    integrations,
                    loading: integrations_loading,
                    error: integrations_error,
                }
            }
            if matches!(&route, PlatformOperationsRoute::Settings) {
                PlatformSettingsView {
                    settings,
                    loading: settings_loading,
                    error: settings_error,
                }
                MigrationStatusList {
                    statuses: migration_statuses,
                    loading: migration_statuses_loading,
                    error: migration_statuses_error,
                }
                MigrationLifecycleControls {
                    access_token: replay_access_token.clone(),
                    principal_ref: replay_principal_ref.clone(),
                    session_id: replay_session_id.clone(),
                }
                MigrationWorkQueue {
                    access_token: replay_access_token.clone(),
                    principal_ref: replay_principal_ref.clone(),
                    session_id: replay_session_id.clone(),
                }
                PlatformDeadLetterReplay {
                    access_token: replay_access_token.clone(),
                    principal_ref: replay_principal_ref.clone(),
                    session_id: replay_session_id.clone(),
                }
            }
            if matches!(&route, PlatformOperationsRoute::RoleReview) {
                PlatformRoleReviewList {
                    page: role_review,
                    loading: role_review_loading,
                    error: role_review_error,
                }
            }
            div { class: "platform-operations-state-grid",
                for state in state_catalog {
                    {
                        let (title, message) = platform_operations_state_copy(state);
                        rsx! {
                            StatePanel {
                                state,
                                title: title.to_string(),
                                message: message.to_string(),
                                action_label: None,
                                on_action: None,
                            }
                        }
                    }
                }
            }
            div { class: "audit-banner",
                "No tenant values, readiness values, credentials, database keys, storage namespaces, or raw event/error payloads are rendered. High-risk replay remains server-authorized, MFA-gated, append-only audited, and idempotent."
            }
        }
    }
}

#[component]
fn PlatformDeadLetterReplay(
    access_token: Option<String>,
    principal_ref: Option<String>,
    session_id: Option<String>,
) -> Element {
    let mut event_id = use_signal(String::new);
    let mut available_at = use_signal(String::new);
    let mut mfa_code = use_signal(String::new);
    let mut busy = use_signal(|| false);
    let mut status = use_signal(|| None::<String>);

    let on_replay = move |_| {
        let (Some(access_token), Some(principal_ref), Some(session_id)) = (
            access_token.clone(),
            principal_ref.clone(),
            session_id.clone(),
        ) else {
            status.set(Some(
                "An authenticated Platform session is required.".into(),
            ));
            return;
        };
        let event_id_value = event_id.read().clone();
        let available_at_value = available_at.read().clone();
        let mfa_code_value = mfa_code.read().clone();
        if event_id_value.trim().is_empty()
            || available_at_value.trim().is_empty()
            || mfa_code_value.trim().is_empty()
        {
            status.set(Some(
                "Event ID, RFC3339 availability, and the fresh MFA code are required.".into(),
            ));
            return;
        }
        busy.set(true);
        status.set(None);
        let mut busy_for_task = busy;
        let mut status_for_task = status;
        let mut mfa_for_task = mfa_code;
        spawn(async move {
            let result = replay_platform_dead_letter(
                event_id_value,
                available_at_value,
                mfa_code_value,
                access_token,
                principal_ref,
                session_id,
            )
            .await
            .map(|response| {
                format!(
                    "{} · correlation {}",
                    response.state, response.correlation_id
                )
            });
            busy_for_task.set(false);
            mfa_for_task.set(String::new());
            status_for_task.set(Some(match result {
                Ok(message) => format!("Dead-letter replay accepted: {message}."),
                Err(error) => format!("Dead-letter replay was not accepted: {error}"),
            }));
        });
    };

    rsx! {
        section { class: "detail-section platform-dead-letter-replay", aria_label: "Dead-letter replay command",
            div { class: "eyebrow", "HIGH-RISK OPERATOR COMMAND" }
            h3 { "Replay a dead-lettered outbox event" }
            p { class: "section-caption", "The server checks platform.outbox.replay, platform scope, actor attribution, and a fresh one-time MFA code. The MFA code is cleared after submission and never rendered in a response." }
            div { class: "metric-grid",
                label {
                    "Event ID"
                    input {
                        r#type: "text",
                        autocomplete: "off",
                        placeholder: "UUID",
                        value: "{event_id}",
                        oninput: move |input| event_id.set(input.value()),
                    }
                }
                label {
                    "Available at (RFC3339)"
                    input {
                        r#type: "text",
                        autocomplete: "off",
                        placeholder: "2026-07-27T12:00:00Z",
                        value: "{available_at}",
                        oninput: move |input| available_at.set(input.value()),
                    }
                }
                label {
                    "Fresh MFA code"
                    input {
                        r#type: "password",
                        autocomplete: "one-time-code",
                        value: "{mfa_code}",
                        oninput: move |input| mfa_code.set(input.value()),
                    }
                }
            }
            button {
                class: "primary-action",
                r#type: "button",
                disabled: *busy.read(),
                onclick: on_replay,
                if *busy.read() { "Replaying…" } else { "Replay dead-letter" }
            }
            if let Some(message) = status.read().clone() {
                div { class: "audit-banner", role: "status", "{message}" }
            }
        }
    }
}

