#[component]
fn MigrationLifecycleControls(
    access_token: Option<String>,
    principal_ref: Option<String>,
    session_id: Option<String>,
) -> Element {
    let mut run_id = use_signal(String::new);
    let mut cohort = use_signal(String::new);
    let mut source_contract_hash = use_signal(String::new);
    let mut id_namespace = use_signal(String::new);
    let mut expected_version = use_signal(|| "1".to_string());
    let mut expected_phase = use_signal(|| "source_frozen".to_string());
    let mut mfa_code = use_signal(String::new);
    let mut busy = use_signal(|| false);
    let mut status = use_signal(|| None::<String>);
    let begin_access_token = access_token.clone();
    let begin_principal_ref = principal_ref.clone();
    let begin_session_id = session_id.clone();

    let on_begin = move |_| {
        let (Some(access_token), Some(principal_ref), Some(session_id)) = (
            begin_access_token.clone(),
            begin_principal_ref.clone(),
            begin_session_id.clone(),
        ) else {
            status.set(Some(
                "An authenticated Platform session is required.".into(),
            ));
            return;
        };
        let request = begin_migration_run_request(BeginMigrationRunRequestFields {
            run_id: &run_id.read(),
            cohort: &cohort.read(),
            source_contract_hash: &source_contract_hash.read(),
            id_namespace: &id_namespace.read(),
            mfa_code: &mfa_code.read(),
            principal_ref: &principal_ref,
            session_id: &session_id,
        });
        let request = match request {
            Ok(request) => request,
            Err(error) => {
                status.set(Some(error));
                return;
            }
        };
        busy.set(true);
        status.set(None);
        let mut busy_for_task = busy;
        let mut status_for_task = status;
        let mut mfa_for_task = mfa_code;
        spawn(async move {
            let result = begin_migration_run(access_token, principal_ref, session_id, request)
                .await
                .map(|response| {
                    format!(
                        "{} · {} · correlation {}",
                        response.phase, response.command_owner, response.correlation_id
                    )
                });
            busy_for_task.set(false);
            mfa_for_task.set(String::new());
            status_for_task.set(Some(match result {
                Ok(message) => format!("Migration run accepted: {message}."),
                Err(error) => format!("Migration run was not accepted: {error}"),
            }));
        });
    };

    let advance_access_token = access_token;
    let advance_principal_ref = principal_ref;
    let advance_session_id = session_id;
    let on_advance = move |_| {
        let (Some(access_token), Some(principal_ref), Some(session_id)) = (
            advance_access_token.clone(),
            advance_principal_ref.clone(),
            advance_session_id.clone(),
        ) else {
            status.set(Some(
                "An authenticated Platform session is required.".into(),
            ));
            return;
        };
        let request = advance_migration_phase_request(AdvanceMigrationPhaseRequestFields {
            run_id: &run_id.read(),
            expected_version: &expected_version.read(),
            expected_phase: &expected_phase.read(),
            mfa_code: &mfa_code.read(),
            principal_ref: &principal_ref,
            session_id: &session_id,
        });
        let request = match request {
            Ok(request) => request,
            Err(error) => {
                status.set(Some(error));
                return;
            }
        };
        busy.set(true);
        status.set(None);
        let mut busy_for_task = busy;
        let mut status_for_task = status;
        let mut mfa_for_task = mfa_code;
        spawn(async move {
            let result = advance_migration_phase(access_token, principal_ref, session_id, request)
                .await
                .map(|response| {
                    format!(
                        "{} · {} · correlation {}",
                        response.phase, response.command_owner, response.correlation_id
                    )
                });
            busy_for_task.set(false);
            mfa_for_task.set(String::new());
            status_for_task.set(Some(match result {
                Ok(message) => format!("Migration phase accepted: {message}."),
                Err(error) => format!("Migration phase was not accepted: {error}"),
            }));
        });
    };

    rsx! {
        section { class: "detail-section platform-migration-lifecycle", aria_label: "G13 migration lifecycle controls",
            div { class: "projection-meta", "Begin runs and advance the ordered G13 lifecycle · platform authorization and fresh MFA required" }
            div { class: "form-grid",
                label { "Run UUID" input {
                    value: "{run_id}",
                    oninput: move |event| run_id.set(event.value()),
                    placeholder: "migration run UUID",
                    disabled: *busy.read(),
                }}
                label { "Cohort" input {
                    value: "{cohort}",
                    oninput: move |event| cohort.set(event.value()),
                    placeholder: "holding or cohort reference",
                    disabled: *busy.read(),
                }}
                label { "Source contract hash" input {
                    value: "{source_contract_hash}",
                    oninput: move |event| source_contract_hash.set(event.value()),
                    placeholder: "64 lowercase hex characters",
                    disabled: *busy.read(),
                }}
                label { "ID namespace" input {
                    value: "{id_namespace}",
                    oninput: move |event| id_namespace.set(event.value()),
                    placeholder: "immutable migration namespace",
                    disabled: *busy.read(),
                }}
                label { "Expected version" input {
                    value: "{expected_version}",
                    oninput: move |event| expected_version.set(event.value()),
                    inputmode: "numeric",
                    disabled: *busy.read(),
                }}
                label { "Expected phase" select {
                    value: "{expected_phase}",
                    onchange: move |event| expected_phase.set(event.value()),
                    disabled: *busy.read(),
                    option { value: "source_frozen", "source frozen" }
                    option { value: "ids_mapped", "IDs mapped" }
                    option { value: "write_backfilled", "write backfilled" }
                    option { value: "read_projected", "read projected" }
                    option { value: "shadow_replaying", "shadow replaying" }
                    option { value: "reconciled", "reconciled" }
                    option { value: "read_only_pilot", "read-only pilot" }
                    option { value: "workflow_accepted", "workflow accepted" }
                    option { value: "rollback_rehearsed", "rollback rehearsed" }
                    option { value: "mutation_frozen", "mutation frozen" }
                }}
                label { "Fresh MFA code" input {
                    r#type: "password",
                    value: "{mfa_code}",
                    oninput: move |event| mfa_code.set(event.value()),
                    autocomplete: "one-time-code",
                    disabled: *busy.read(),
                }}
            }
            div { class: "button-row",
                button {
                    class: "primary-button",
                    r#type: "button",
                    disabled: *busy.read(),
                    onclick: on_begin,
                    if *busy.read() { "Working…" } else { "Begin migration run" }
                }
                button {
                    class: "secondary-button",
                    r#type: "button",
                    disabled: *busy.read(),
                    onclick: on_advance,
                    "Advance ordered phase"
                }
            }
            if let Some(message) = status.read().clone() {
                div { class: "audit-banner", role: "status", "{message}" }
            }
            div { class: "audit-banner", "The controls never submit source rows, credentials, approval references, command-owner changes, Folio retirement, or cutover requests." }
        }
    }
}

#[component]
fn MigrationWorkQueue(
    access_token: Option<String>,
    principal_ref: Option<String>,
    session_id: Option<String>,
) -> Element {
    let mut run_id = use_signal(String::new);
    let mut work_kind = use_signal(|| "backfill".to_string());
    let mut scope_key = use_signal(String::new);
    let mut source_fence = use_signal(String::new);
    let mut max_attempts = use_signal(|| "10".to_string());
    let mut mfa_code = use_signal(String::new);
    let mut busy = use_signal(|| false);
    let mut status = use_signal(|| None::<String>);

    let on_queue = move |_| {
        let (Some(access_token), Some(principal_ref), Some(session_id)) = (
            access_token.clone(),
            principal_ref.clone(),
            session_id.clone(),
        ) else {
            status.set(Some(
                "An authenticated Platform session is required.".into(),
            ));
            return;
        };
        let request = migration_work_request(MigrationWorkRequestFields {
            run_id: &run_id.read(),
            work_kind: &work_kind.read(),
            scope_key: &scope_key.read(),
            source_fence: &source_fence.read(),
            max_attempts: &max_attempts.read(),
            mfa_code: &mfa_code.read(),
            principal_ref: &principal_ref,
            session_id: &session_id,
        });
        let request = match request {
            Ok(request) => request,
            Err(error) => {
                status.set(Some(error));
                return;
            }
        };
        busy.set(true);
        status.set(None);
        let mut busy_for_task = busy;
        let mut status_for_task = status;
        let mut mfa_for_task = mfa_code;
        spawn(async move {
            let result = queue_migration_work(access_token, principal_ref, session_id, request)
                .await
                .map(|response| {
                    format!(
                        "{} · {} · correlation {}",
                        response.state, response.work_kind, response.correlation_id
                    )
                });
            busy_for_task.set(false);
            mfa_for_task.set(String::new());
            status_for_task.set(Some(match result {
                Ok(message) => format!("Migration work accepted: {message}."),
                Err(error) => format!("Migration work was not accepted: {error}"),
            }));
        });
    };

    rsx! {
        section { class: "detail-section platform-migration-work-queue", aria_label: "Queue G13 migration work",
            div { class: "projection-meta", "Queue bounded migration execution work · MFA and platform authorization required · no cutover control" }
            div { class: "form-grid",
                label { "Run UUID" input {
                    value: "{run_id}",
                    oninput: move |event| run_id.set(event.value()),
                    placeholder: "migration run UUID",
                    disabled: *busy.read(),
                }}
                label { "Work kind" select {
                    value: "{work_kind}",
                    onchange: move |event| work_kind.set(event.value()),
                    disabled: *busy.read(),
                    option { value: "backfill", "backfill" }
                    option { value: "project", "project" }
                    option { value: "shadow_replay", "shadow replay" }
                    option { value: "final_delta", "final delta" }
                    option { value: "reconcile", "reconcile" }
                    option { value: "rollback", "rollback rehearsal" }
                }}
                label { "Scope key" input {
                    value: "{scope_key}",
                    oninput: move |event| scope_key.set(event.value()),
                    placeholder: "source_snapshot:<id>:customers",
                    disabled: *busy.read(),
                }}
                label { "Source fence" input {
                    value: "{source_fence}",
                    oninput: move |event| source_fence.set(event.value()),
                    placeholder: "immutable source contract/fence",
                    disabled: *busy.read(),
                }}
                label { "Max attempts" input {
                    value: "{max_attempts}",
                    oninput: move |event| max_attempts.set(event.value()),
                    inputmode: "numeric",
                    disabled: *busy.read(),
                }}
                label { "Fresh MFA code" input {
                    r#type: "password",
                    value: "{mfa_code}",
                    oninput: move |event| mfa_code.set(event.value()),
                    autocomplete: "one-time-code",
                    disabled: *busy.read(),
                }}
            }
            button {
                class: "primary-button",
                r#type: "button",
                disabled: *busy.read(),
                onclick: on_queue,
                if *busy.read() { "Queueing…" } else { "Queue migration work" }
            }
            if let Some(message) = status.read().clone() {
                div { class: "audit-banner", role: "status", "{message}" }
            }
            div { class: "audit-banner", "Only bounded work metadata is submitted. Source payloads, credentials, tokens, command-owner changes, and cutover are not exposed." }
        }
    }
}

