#[component]
fn PlatformTenantRouteLauncher(on_navigate: EventHandler<PlatformOperationsRoute>) -> Element {
    let mut tenant_id_input = use_signal(String::new);
    let mut validation_error = use_signal(|| false);
    rsx! {
        section { class: "projection-placeholder", aria_label: "Open tenant operations route",
            div { class: "eyebrow", "TENANT DETAIL ROUTE" }
            p { "Open a tenant detail route only with an opaque identifier supplied by an authorized operator. The console does not suggest or fabricate tenant values." }
            div { class: "auth-field",
                label { r#for: "platform-tenant-id", "Opaque tenant ID" }
                input {
                    id: "platform-tenant-id",
                    autocomplete: "off",
                    value: "{tenant_id_input}",
                    oninput: move |event| {
                        validation_error.set(false);
                        tenant_id_input.set(event.value());
                    },
                }
            }
            button {
                class: "button secondary",
                r#type: "button",
                onclick: move |_| match PlatformTenantId::new(tenant_id_input.read().clone()) {
                    Ok(tenant_id) => {
                        validation_error.set(false);
                        on_navigate.call(PlatformOperationsRoute::Tenant { tenant_id });
                    }
                    Err(_) => validation_error.set(true),
                },
                "Open typed tenant route"
            }
            if *validation_error.read() {
                StatePanel {
                    state: UiStateKind::Denied,
                    title: "Tenant route identifier unavailable".to_string(),
                    message: "Enter a non-empty opaque tenant identifier without path separators, query markers, or credentials.".to_string(),
                    action_label: None,
                    on_action: None,
                }
            }
        }
    }
}

/// Return the console title/copy for a typed support or incident route.
///
/// Read and command authority remains in the Support RPC/server boundary; this
/// helper only supplies safe route copy.
#[component]
fn SupportCommandPanel(
    route: SupportRoute,
    busy: bool,
    message: Option<String>,
    on_command: EventHandler<SupportCommandInput>,
) -> Element {
    let mut mode = use_signal(|| {
        if matches!(
            route,
            SupportRoute::PlatformIncidents | SupportRoute::PlatformIncidentDetail
        ) {
            "create_incident".to_string()
        } else {
            "create_ticket".to_string()
        }
    });
    let mut customer_id = use_signal(String::new);
    let mut severity = use_signal(|| "medium".to_string());
    let mut description = use_signal(String::new);
    let mut ticket_id = use_signal(String::new);
    let mut ticket_status = use_signal(|| "triaged".to_string());
    let mut ticket_version = use_signal(|| "1".to_string());
    let mut leads = use_signal(String::new);
    let mut affected_services = use_signal(String::new);
    let mut affected_customers = use_signal(String::new);
    let mut incident_id = use_signal(String::new);
    let mut incident_status = use_signal(|| "identified".to_string());
    let mut incident_version = use_signal(|| "1".to_string());
    let mode_snapshot = mode.read().clone();
    let form = match mode_snapshot.as_str() {
        "create_ticket" => rsx! {
            label { "Customer UUID" input {
                value: "{customer_id}",
                placeholder: "customer UUID",
                oninput: move |event| customer_id.set(event.value()),
                disabled: busy,
            }}
            label { "Severity" input {
                value: "{severity}",
                placeholder: "low / medium / high",
                oninput: move |event| severity.set(event.value()),
                disabled: busy,
            }}
            label { "Description" textarea {
                value: "{description}",
                maxlength: "4096",
                oninput: move |event| description.set(event.value()),
                disabled: busy,
            }}
        },
        "transition_ticket" => rsx! {
            label { "Ticket UUID" input {
                value: "{ticket_id}",
                placeholder: "ticket UUID",
                oninput: move |event| ticket_id.set(event.value()),
                disabled: busy,
            }}
            label { "Next status" select {
                value: "{ticket_status}",
                oninput: move |event| ticket_status.set(event.value()),
                disabled: busy,
                option { value: "new", "new" }
                option { value: "triaged", "triaged" }
                option { value: "waiting_for_customer", "waiting for customer" }
                option { value: "access_requested", "access requested" }
                option { value: "approved", "approved" }
                option { value: "in_progress", "in progress" }
                option { value: "resolved", "resolved" }
                option { value: "customer_confirmed", "customer confirmed" }
                option { value: "closed", "closed" }
            }}
            label { "Expected version" input {
                value: "{ticket_version}",
                inputmode: "numeric",
                oninput: move |event| ticket_version.set(event.value()),
                disabled: busy,
            }}
        },
        "create_incident" => rsx! {
            label { "Leads (comma-separated)" input {
                value: "{leads}",
                maxlength: "8192",
                oninput: move |event| leads.set(event.value()),
                disabled: busy,
            }}
            label { "Affected services (comma-separated)" input {
                value: "{affected_services}",
                maxlength: "8192",
                oninput: move |event| affected_services.set(event.value()),
                disabled: busy,
            }}
            label { "Affected customer UUIDs (comma-separated, optional)" input {
                value: "{affected_customers}",
                maxlength: "16384",
                oninput: move |event| affected_customers.set(event.value()),
                disabled: busy,
            }}
        },
        "transition_incident" => rsx! {
            label { "Incident UUID" input {
                value: "{incident_id}",
                placeholder: "incident UUID",
                oninput: move |event| incident_id.set(event.value()),
                disabled: busy,
            }}
            label { "Next status" select {
                value: "{incident_status}",
                oninput: move |event| incident_status.set(event.value()),
                disabled: busy,
                option { value: "investigating", "investigating" }
                option { value: "identified", "identified" }
                option { value: "monitoring", "monitoring" }
                option { value: "resolved", "resolved" }
                option { value: "postmortem_complete", "postmortem complete" }
            }}
            label { "Expected version" input {
                value: "{incident_version}",
                inputmode: "numeric",
                oninput: move |event| incident_version.set(event.value()),
                disabled: busy,
            }}
        },
        _ => rsx! { p { class: "ui-safe-note", "Select an authorized command." } },
    };
    let on_submit = move |_| {
        let input = match mode.read().as_str() {
            "create_ticket" => SupportCommandInput::CreateTicket {
                customer_id: customer_id.read().clone(),
                severity: severity.read().clone(),
                description: description.read().clone(),
            },
            "transition_ticket" => SupportCommandInput::TransitionTicket {
                ticket_id: ticket_id.read().clone(),
                next_status: ticket_status.read().clone(),
                expected_version: ticket_version.read().clone(),
            },
            "create_incident" => SupportCommandInput::CreateIncident {
                leads: leads.read().clone(),
                affected_services: affected_services.read().clone(),
                affected_customer_accounts: affected_customers.read().clone(),
            },
            "transition_incident" => SupportCommandInput::TransitionIncident {
                incident_id: incident_id.read().clone(),
                next_status: incident_status.read().clone(),
                expected_version: incident_version.read().clone(),
            },
            _ => return,
        };
        on_command.call(input);
    };
    rsx! {
        section { class: "ui-support-command-panel", aria_label: "Authorized support commands",
            header { class: "ui-support-heading",
                div {
                    span { class: "ui-eyebrow", "SERVER-AUTHORIZED COMMAND" }
                    h3 { "Support and incident actions" }
                    p { "Commands are bounded here, then revalidated by the authoritative server for scope, role, MFA policy, optimistic version, SQLx state, outbox, and audit." }
                }
                span { class: "ui-readonly-pill", "AUDITED" }
            }
            label { "Command" select {
                value: "{mode_snapshot}",
                oninput: move |event| mode.set(event.value()),
                disabled: busy,
                option { value: "create_ticket", "Create ticket" }
                option { value: "transition_ticket", "Transition ticket" }
                option { value: "create_incident", "Create incident" }
                option { value: "transition_incident", "Transition incident" }
            }}
            div { class: "ui-support-command-fields", {form} }
            button {
                class: "primary-button",
                r#type: "button",
                disabled: busy,
                onclick: on_submit,
                if busy { "Submitting…" } else { "Submit authorized command" }
            }
            if let Some(message) = message {
                div { class: "audit-banner", role: "status", "{message}" }
            }
            div { class: "audit-banner", "Ticket bodies, replies, internal notes, capability secrets, and incident timelines are never rendered by this surface. Use a fresh read after every command." }
        }
    }
}

fn console_support_route_context(route: SupportRoute) -> (&'static str, &'static str) {
    match route {
        SupportRoute::PlatformIncidents | SupportRoute::PlatformIncidentDetail => (
            "Incidents",
            "Platform-scoped incident reads and audited lifecycle commands through the authoritative Support service.",
        ),
        SupportRoute::PlatformSupport
        | SupportRoute::PlatformSupportNew
        | SupportRoute::PlatformSupportDetail
        | SupportRoute::PlatformSupportAccess
        | SupportRoute::PlatformSupportDiagnostics
        | SupportRoute::PlatformSupportSessions
        | SupportRoute::TenantSupport
        | SupportRoute::TenantSupportNew
        | SupportRoute::TenantSupportDetail
        | SupportRoute::TenantSupportAccessApproval
        | SupportRoute::TenantPlatformAccess => (
            "Support",
            "Safe support projection plus bounded server-authorized ticket commands; authorization and persistence remain server-owned.",
        ),
    }
}

fn console_incident_surface_state(
    read: Option<IncidentReadPage>,
    loading: bool,
    error: Option<String>,
) -> SupportIncidentSurfaceState {
    let metadata = IncidentProjectionMetadata::unknown();
    let state = if loading {
        IncidentListState::Loading {
            metadata: Some(metadata.clone()),
        }
    } else if let Some(error) = error {
        let reason = incident_read_error_message(&error).to_string();
        match incident_read_error_state(&error) {
            UiStateKind::Denied => IncidentListState::Denied {
                metadata: Some(metadata),
                reason,
            },
            UiStateKind::Offline => IncidentListState::Offline {
                data: None,
                metadata: Some(metadata),
                reason,
            },
            _ => IncidentListState::Error { reason },
        }
    } else if let Some(read) = read {
        if read.model.items().is_empty() {
            IncidentListState::Empty { metadata }
        } else {
            IncidentListState::ReadOnly {
                data: read.model,
                metadata,
                reason: "Incident commands remain server-authorized and are not exposed by this read-only console surface.".into(),
            }
        }
    } else {
        IncidentListState::Error {
            reason: "The platform incident projection did not return a safe read result.".into(),
        }
    };
    SupportIncidentSurfaceState::IncidentList(state)
}

fn console_support_ticket_surface_state(
    read: Option<SupportTicketReadPage>,
    loading: bool,
    error: Option<String>,
) -> SupportIncidentSurfaceState {
    let metadata = SupportProjectionMetadata::unknown();
    let state = if loading {
        SupportTicketListState::Loading {
            metadata: Some(metadata.clone()),
        }
    } else if let Some(error) = error {
        let reason = support_ticket_read_error_message(&error).to_string();
        match incident_read_error_state(&error) {
            UiStateKind::Denied => SupportTicketListState::Denied {
                metadata: Some(metadata),
                reason,
            },
            UiStateKind::Offline => SupportTicketListState::Offline {
                data: None,
                metadata: Some(metadata),
                reason,
            },
            _ => SupportTicketListState::Error { reason },
        }
    } else if let Some(read) = read {
        if read.model.items().is_empty() {
            SupportTicketListState::Empty { metadata }
        } else {
            SupportTicketListState::ReadOnly {
                data: read.model,
                metadata,
                reason: "Ticket bodies, replies, and commands remain server-authorized and are not exposed by this metadata-only console surface.".into(),
            }
        }
    } else {
        SupportTicketListState::Error {
            reason: "The platform support ticket projection did not return a safe read result."
                .into(),
        }
    };
    SupportIncidentSurfaceState::TicketList(state)
}

fn console_support_diagnostics_surface_state(
    read: Option<SupportDiagnosticsRead>,
    loading: bool,
    error: Option<String>,
) -> SupportIncidentSurfaceState {
    let metadata = SupportProjectionMetadata::unknown();
    let state = if loading {
        SupportState::Loading {
            metadata: Some(metadata.clone()),
        }
    } else if let Some(error) = error {
        let reason = match error.as_str() {
            "authentication_required" => "The support diagnostics session is not authenticated.",
            "authorization_denied" => "The server denied this platform diagnostics read.",
            "offline" => "The support diagnostics service is unavailable.",
            _ => "The platform diagnostics projection could not be loaded.",
        }
        .to_string();
        match error.as_str() {
            "authentication_required" | "authorization_denied" => SupportState::Denied {
                metadata: Some(metadata),
                reason,
            },
            "offline" => SupportState::Offline {
                data: None,
                metadata: Some(metadata),
                reason,
            },
            _ => SupportState::Error { reason },
        }
    } else if let Some(read) = read {
        SupportState::ReadOnly {
            data: read.model,
            metadata: SupportProjectionMetadata::fresh(read.captured_at),
            reason: format!(
                "Authorized platform diagnostics · schema {} · correlation {}. Raw payload and commands remain outside the client model.",
                read.schema_version, read.correlation_id
            ),
        }
    } else {
        SupportState::Empty { metadata }
    };
    SupportIncidentSurfaceState::Support(state)
}

/// Build an explicit empty scaffold for a typed route without fabricating backend records.
fn console_support_surface_state(route: SupportRoute) -> SupportIncidentSurfaceState {
    match route {
        SupportRoute::PlatformIncidents => {
            SupportIncidentSurfaceState::IncidentList(IncidentListState::Empty {
                metadata: IncidentProjectionMetadata::unknown(),
            })
        }
        SupportRoute::PlatformIncidentDetail => {
            SupportIncidentSurfaceState::IncidentDetail(IncidentDetailState::Empty {
                metadata: IncidentProjectionMetadata::unknown(),
            })
        }
        _ => SupportIncidentSurfaceState::Support(SupportState::Empty {
            metadata: SupportProjectionMetadata::unknown(),
        }),
    }
}

