    #[test]
    fn initial_deep_link_dispatch_covers_each_console_surface() {
        assert_eq!(
            console_deep_link("/platform/directories?tab=connectors"),
            Some(ConsoleDeepLink::Directory)
        );
        assert_eq!(
            console_deep_link("/platform/billing#entitlements"),
            Some(ConsoleDeepLink::Billing)
        );
        assert_eq!(
            console_deep_link("/platform/projections"),
            Some(ConsoleDeepLink::PlatformOperations(
                PlatformOperationsRoute::Projections
            ))
        );
        assert_eq!(
            console_deep_link("/platform/incidents"),
            Some(ConsoleDeepLink::Support(SupportRoute::PlatformIncidents))
        );
        assert_eq!(
            console_deep_link("/marketing/leads"),
            Some(ConsoleDeepLink::Marketing(RouteId::MarketingLeads))
        );
        assert_eq!(
            console_deep_link("/finance?view=close"),
            Some(ConsoleDeepLink::ProductContext(ProductContext::Finance))
        );
        assert!(matches!(
            console_deep_link("/platform/customers/customer-001/health"),
            Some(ConsoleDeepLink::Customer(PlatformRoute::Customer { .. }))
        ));
    }

    #[test]
    fn initial_deep_link_dispatch_fails_closed_for_unsafe_or_unknown_paths() {
        for path in [
            "https://attacker.example/platform/directories",
            "/platform/customers/customer-001?access_token=secret",
            "/platform/unknown",
            "/platform/support/ticket-001",
        ] {
            assert_eq!(
                console_deep_link(path),
                None,
                "untrusted deep link must not select a console surface: {path}"
            );
        }
    }

    #[test]
    fn directory_rpc_auth_categories_render_as_denied_without_backend_details() {
        let cases = [
            (
                tonic::Status::unauthenticated("access token=secret"),
                "authentication_required",
                UiStateKind::Denied,
            ),
            (
                tonic::Status::permission_denied("directory password=secret"),
                "authorization_denied",
                UiStateKind::Denied,
            ),
            (
                tonic::Status::unavailable("ldap://secret"),
                "offline",
                UiStateKind::Offline,
            ),
        ];
        for (status, category, state) in cases {
            assert_eq!(directory_rpc_error(status), category);
            assert_eq!(directory_error_state(category), state);
            assert!(!directory_error_title(category).is_empty());
            assert!(!directory_error_message(category).contains("secret"));
            assert!(!directory_error_message(category).contains("ldap://"));
        }
        assert_eq!(
            directory_error_state("directory_read_failed"),
            UiStateKind::Error
        );
    }

