    #[test]
    fn finance_close_wire_boundary_requires_matching_scope_read_only_and_bounded_facts() {
        let scope = FinanceCloseScope::new(
            "tenant-001",
            "holding-ref-001",
            "00000000-0000-0000-0000-000000000001",
            "00000000-0000-0000-0000-000000000002",
            "00000000-0000-0000-0000-000000000003",
        )
        .expect("valid close scope");
        let response = GetFinanceCloseReviewResponse {
            view: Some(erpx_proto::platform::FinanceCloseReadView {
                review: Some(erpx_proto::platform::FinanceCloseReviewProjection {
                    holding_id: scope.finance.holding_id.clone(),
                    company_id: scope.company_id.clone(),
                    period_id: scope.period_id.clone(),
                    status: "review".into(),
                    version: 4,
                    idempotency_key: "close-review-001".into(),
                    opened_by: "principal-001".into(),
                    reviewed_by: "principal-002".into(),
                    closed_by: String::new(),
                }),
                report: Some(erpx_proto::platform::FinanceCloseReport {
                    statement: Some(erpx_proto::platform::FinanceCloseStatementSummary {
                        debit_minor: 100,
                        credit_minor: 100,
                        net_minor: 0,
                        balanced: true,
                    }),
                    controls: Some(erpx_proto::platform::FinanceCloseControlSummary {
                        total: 2,
                        resolved: 2,
                        unresolved: 0,
                    }),
                    accounts: vec![erpx_proto::platform::FinanceCloseAccountSummary {
                        account_id: "00000000-0000-0000-0000-000000000004".into(),
                        debit_minor: 100,
                        credit_minor: 100,
                        net_minor: 0,
                    }],
                }),
                metadata: Some(erpx_proto::platform::FinanceCloseReadMetadata {
                    period_id: scope.period_id.clone(),
                    holding_id: scope.finance.holding_id.clone(),
                    company_id: scope.company_id.clone(),
                    availability: "present".into(),
                    freshness: "fresh".into(),
                    read_only: true,
                    review_updated_at: "2026-07-27T10:00:00Z".into(),
                    projection_updated_at: "2026-07-27T10:00:00Z".into(),
                    source_version: 8,
                    has_source_version: true,
                    expected_fact_count: 3,
                    observed_fact_count: 3,
                    missing_fact_count: 0,
                }),
            }),
            missing: false,
            missing_metadata: None,
            correlation_id: "finance-close-correlation-001".into(),
        };
        let read = FinanceCloseReadModel::from_wire(&scope, response)
            .expect("authoritative close response");
        assert_eq!(read.status, "review");
        assert!(read.balanced == Some(true));
        assert_eq!(read.accounts.len(), 1);
        assert!(read.read_only);
        let debug = format!("{read:?}");
        assert!(!debug.contains("password"));
        assert!(!debug.contains("payload_json"));

        let mut mismatched = GetFinanceCloseReviewResponse {
            view: Some(erpx_proto::platform::FinanceCloseReadView {
                review: Some(erpx_proto::platform::FinanceCloseReviewProjection {
                    holding_id: scope.finance.holding_id.clone(),
                    company_id: scope.company_id.clone(),
                    period_id: scope.period_id.clone(),
                    status: "open".into(),
                    version: 1,
                    opened_by: "principal-001".into(),
                    ..Default::default()
                }),
                report: Some(erpx_proto::platform::FinanceCloseReport {
                    controls: Some(erpx_proto::platform::FinanceCloseControlSummary::default()),
                    ..Default::default()
                }),
                metadata: Some(erpx_proto::platform::FinanceCloseReadMetadata {
                    period_id: scope.period_id.clone(),
                    holding_id: scope.finance.holding_id.clone(),
                    company_id: scope.company_id.clone(),
                    availability: "present".into(),
                    freshness: "fresh".into(),
                    read_only: false,
                    ..Default::default()
                }),
            }),
            correlation_id: "finance-close-correlation-002".into(),
            ..Default::default()
        };
        assert!(FinanceCloseReadModel::from_wire(&scope, mismatched.clone()).is_err());
        mismatched.missing = true;
        assert!(FinanceCloseReadModel::from_wire(&scope, mismatched).is_err());
        assert!(
            FinanceCloseScope::new(
                "tenant-001",
                "holding-ref-001",
                &scope.finance.holding_id,
                "not-a-uuid",
                &scope.company_id,
            )
            .is_err()
        );
    }

