    #[test]
    fn product_aggregate_wire_boundary_discards_payload_and_enforces_identity() {
        let scope = ProductAggregateScope::new(
            "tenant-001",
            "holding-ref-001",
            "00000000-0000-0000-0000-000000000001",
            "stock_transfer",
            "00000000-0000-0000-0000-000000000010",
        )
        .expect("valid product aggregate scope");
        let read = ProductAggregateReadModel::from_wire(
            &scope,
            &scope.aggregate_type,
            &scope.aggregate_id,
            5,
            br#"{"secret":"must-not-render","quantity":10}"#,
            true,
            "product-correlation-001",
        )
        .expect("safe product aggregate read");
        assert!(read.present);
        assert_eq!(read.source_version, 5);
        let debug = format!("{read:?}");
        assert!(!debug.contains("must-not-render"));
        assert!(!debug.contains("aggregate_json"));

        let invalid_identity = GetScmAggregateResponse {
            aggregate_type: "purchase_order".into(),
            aggregate_id: scope.aggregate_id.clone(),
            correlation_id: "product-correlation-002".into(),
            ..Default::default()
        };
        assert!(
            ProductAggregateReadModel::from_wire(
                &scope,
                &invalid_identity.aggregate_type,
                &invalid_identity.aggregate_id,
                invalid_identity.source_version,
                &invalid_identity.aggregate_json,
                invalid_identity.present,
                &invalid_identity.correlation_id,
            )
            .is_err()
        );

        let invalid_missing = GetAssetMaintenanceAggregateResponse {
            aggregate_type: scope.aggregate_type.clone(),
            aggregate_id: scope.aggregate_id.clone(),
            source_version: 1,
            present: false,
            correlation_id: "product-correlation-003".into(),
            ..Default::default()
        };
        assert!(
            ProductAggregateReadModel::from_wire(
                &scope,
                &invalid_missing.aggregate_type,
                &invalid_missing.aggregate_id,
                invalid_missing.source_version,
                &invalid_missing.aggregate_json,
                invalid_missing.present,
                &invalid_missing.correlation_id,
            )
            .is_err()
        );
        assert_eq!(
            super::product_aggregate_error_state("authorization_denied"),
            UiStateKind::Denied
        );
    }

    #[test]
    fn migration_rollback_and_reconciliation_wire_values_are_allowlisted() {
        let verified = MigrationStatusRecord::from(MigrationStatus {
            reconciliation_state: "matched".into(),
            rollback_state: "succeeded".into(),
            ..MigrationStatus::default()
        });
        assert_eq!(verified.reconciliation_state.key(), "matched");
        assert_eq!(verified.rollback_state.key(), "succeeded");
        assert_eq!(verified.rollback_state.label(), "Rollback verified");

        let unknown = MigrationStatusRecord::from(MigrationStatus {
            reconciliation_state: "token=secret".into(),
            rollback_state: "postgres://secret".into(),
            ..MigrationStatus::default()
        });
        assert_eq!(unknown.reconciliation_state.key(), "unavailable");
        assert_eq!(unknown.rollback_state.key(), "unavailable");
        let debug = format!("{unknown:?}");
        assert!(!debug.contains("token=secret"));
        assert!(!debug.contains("postgres://secret"));
        assert_eq!(
            unknown.rollback_state.label(),
            "Rollback evidence unavailable"
        );
        assert!(unknown.rollback_state.message().contains("No recognized"));
    }

