    #[test]
    fn platform_operations_copy_keeps_non_ready_and_read_only_states_explicit() {
        let states = [
            UiStateKind::Loading,
            UiStateKind::Error,
            UiStateKind::Denied,
            UiStateKind::Stale,
            UiStateKind::ReadOnly,
        ];
        for state in states {
            let (title, message) = platform_operations_state_copy(state);
            assert!(!title.is_empty());
            assert!(!message.is_empty());
            assert!(!message.to_ascii_lowercase().contains("credential"));
            assert!(!message.to_ascii_lowercase().contains("secret"));
        }
        let (title, message) = platform_operations_not_connected_copy();
        assert!(title.to_ascii_lowercase().contains("not yet connected"));
        assert!(message.to_ascii_lowercase().contains("read-only"));
        assert!(message.to_ascii_lowercase().contains("data adapter"));
        let (title, message) = platform_operations_connection_copy(true);
        assert!(title.to_ascii_lowercase().contains("connected"));
        assert!(message.to_ascii_lowercase().contains("authorized"));
        assert!(message.to_ascii_lowercase().contains("read model"));
    }

    #[test]
    fn product_projection_errors_preserve_denied_offline_and_error_postures() {
        let cases = [
            ("authentication_required", UiStateKind::Denied),
            ("authorization_denied", UiStateKind::Denied),
            ("offline", UiStateKind::Offline),
            ("product_projection_read_failed", UiStateKind::Error),
        ];
        for (category, expected_kind) in cases {
            let snapshot = Err(category.to_string());
            let state =
                product_context_surface_state(ProductContext::Sales, Some(&snapshot), false);
            assert_eq!(state.kind(), Some(expected_kind));
            assert!(!state.has_model());
            assert!(!state.message().as_str().contains(category));
            assert!(!state.message().as_str().contains("secret"));
        }
    }

