    #[test]
    fn auth_wire_decoding_is_typed_and_response_debug_is_redacted() {
        let response = AuthHttpResponse {
            status: 200,
            body: r#"{"session_id":"session-1","access_token":"access-secret","refresh_token":"refresh-secret","access_expires_at":"access-expiry","refresh_expires_at":"refresh-expiry"}"#.into(),
        };
        let debug = format!("{response:?}");
        assert!(!debug.contains("access-secret"));
        assert!(!debug.contains("refresh-secret"));
        assert!(decode_issued_session(response).is_ok());
    }

    #[test]
    fn auth_wire_decoding_rejects_nested_duplicate_and_oversized_fields() {
        let valid = |body: &str| {
            decode_issued_session(AuthHttpResponse {
                status: 200,
                body: body.into(),
            })
            .is_ok()
        };
        assert!(!valid(
            r#"{"payload":{"session_id":"nested"},"access_token":"a","refresh_token":"r","access_expires_at":"a","refresh_expires_at":"r"}"#
        ));
        assert!(!valid(
            r#"{"session_id":"first","session_id":"second","access_token":"a","refresh_token":"r","access_expires_at":"a","refresh_expires_at":"r"}"#
        ));
        assert!(!valid(&format!(
            r#"{{"session_id":"{}","access_token":"a","refresh_token":"r","access_expires_at":"a","refresh_expires_at":"r"}}"#,
            "x".repeat(MAX_AUTH_RESPONSE_BYTES)
        )));
    }

    #[test]
    fn auth_bool_decoding_requires_a_unique_root_boolean() {
        assert_eq!(json_bool(r#"{"revoked":true}"#, "revoked"), Some(true));
        assert_eq!(
            json_bool(r#"{"payload":{"revoked":true}}"#, "revoked"),
            None
        );
        assert_eq!(
            json_bool(r#"{"revoked":true,"revoked":false}"#, "revoked"),
            None
        );
        assert_eq!(json_bool(r#"{"revoked":"true"}"#, "revoked"), None);
    }

    #[test]
    fn auth_status_mapping_exposes_only_safe_categories() {
        assert_eq!(auth_http_status(401), AuthTransportError::Unauthorized);
        assert_eq!(auth_http_status(0), AuthTransportError::Offline);
        assert_eq!(
            auth_http_status(422),
            AuthTransportError::Server {
                code: "http_422".into()
            }
        );
    }

    #[test]
    fn console_target_session_descriptor_reports_only_target_owned_storage() {
        let descriptor = TargetSecureSessionAdapter::descriptor();
        assert_eq!(
            descriptor.secure_session(),
            if cfg!(any(
                target_os = "ios",
                target_os = "macos",
                target_os = "android"
            )) {
                SecureSessionSupport::Supported
            } else {
                SecureSessionSupport::Unsupported
            }
        );
        if cfg!(any(
            target_os = "ios",
            target_os = "macos",
            target_os = "android"
        )) {
            assert!(descriptor.status_label().contains("configured"));
        } else {
            assert!(descriptor.status_label().contains("unavailable"));
        }
        assert!(!descriptor.status_label().contains("localStorage"));
    }

