    #[test]
    fn asset_maintenance_list_read_boundary_is_scoped_bounded_and_paginated() {
        let scope = AssetMaintenanceListScope::new(
            "tenant-001",
            "holding-ref-001",
            "00000000-0000-0000-0000-000000000001",
            "00000000-0000-0000-0000-000000000011",
            "",
        )
        .expect("Asset/Maintenance list scope");
        let response = ListAssetMaintenanceAggregatesResponse {
            rows: vec![AssetMaintenanceAggregateReadRow {
                aggregate_type: "asset".into(),
                aggregate_id: "00000000-0000-0000-0000-000000000021".into(),
                holding_id: scope.finance.holding_id.clone(),
                company_id: scope.company_id.clone(),
                branch_id: String::new(),
                reference: "ASSET-001".into(),
                source_version: 2,
                aggregate_json: br#"{}"#.to_vec(),
                projected_at: "2026-07-28T00:00:00Z".into(),
            }],
            has_more: true,
            next_cursor: "opaque-asset-cursor".into(),
            correlation_id: "asset-correlation-001".into(),
        };
        let read = AssetMaintenanceListReadModel::from_wire(&scope, response)
            .expect("typed Asset/Maintenance list read");
        assert_eq!(read.rows.len(), 1);
        assert_eq!(read.rows[0].aggregate_type, "asset");
        assert_eq!(read.rows[0].reference, "ASSET-001");
        assert_eq!(read.next_cursor.as_deref(), Some("opaque-asset-cursor"));
        let mut escaped = ListAssetMaintenanceAggregatesResponse {
            rows: vec![AssetMaintenanceAggregateReadRow {
                aggregate_type: "asset".into(),
                aggregate_id: "00000000-0000-0000-0000-000000000021".into(),
                holding_id: scope.finance.holding_id.clone(),
                company_id: "00000000-0000-0000-0000-000000000099".into(),
                branch_id: String::new(),
                reference: "ASSET-001".into(),
                source_version: 1,
                aggregate_json: br#"{}"#.to_vec(),
                projected_at: "2026-07-28T00:00:00Z".into(),
            }],
            has_more: false,
            next_cursor: String::new(),
            correlation_id: "asset-correlation-002".into(),
        };
        assert!(AssetMaintenanceListReadModel::from_wire(&scope, escaped.clone()).is_err());
        escaped.rows.clear();
        assert!(AssetMaintenanceListReadModel::from_wire(&scope, escaped).is_ok());
    }

